/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20050315-3","meetingId":"h17-c-budget","date":"2005年3月15日","dateIso":"2005-03-15","committee":"予算特別委員会","time":"午前１０時０３分～午後６時２３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件整理しています。","topics":[{"id":"topic-01","title":"◯三上委員長 おはようございます。ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１７年度品川区一般会計予算","agenda":"◯三上委員長 おはようございます。ただいまより予算特別委員会を開会いたします。 それでは、第５号議案、平成１７年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"私は、２６１ページ、交通安全対策、２６９ページ、目黒線の整備についてお伺いをいたします。改めまして、どこの辺まで構成員になってもらうような声かけをされるのか、そこの範囲を教えてほしいと求めました。","respondent":"山口交通安全担当課長","answer":"今のところの予定ですが、構成員については、鉄道事業者、大型店舗、銀行、町会等を含めて、町会等については、駅の関連する部分、概ね１００ｍから１５０ｍの区域内の町会のほうにお願いしたいと考えております。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"とりわけ駅の周辺、小山三丁目というのは、四つないし五つの商店街で分断をされております。商店街ごとに放置自転車の悩みがありますが、そこら辺の商店街のところ、そこらの取扱いをどのようにされるのか、お伺いをしたいと思います。","respondent":"山口交通安全担当課長","answer":"事前には目黒区のほうに働きかけていきたいと思います。商店街についても、目黒区と協議しながら進めていきたいと考えています。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"商店街は、目黒区に相談することではなくて、私が申し上げているのは、品川区内にある小山三丁目、具体的に挙げますと、駅前通り商店街、武蔵小山、パルム、一番通り商栄会、武蔵小山西口商店街等々ありますが、そこら辺の声かけはどうなされるのかということでお伺いしております。","respondent":"山口交通安全担当課長","answer":"大変失礼しました。大型商店街のほうにも積極的にご協力をお願いしたいと考えております。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"先ほど駅を中心に１００ｍから１５０ｍということでお話を伺いました。今整備をお願いしております補助３２０号線というのがありますけれども、お伺いをしたいと思います。","respondent":"山口交通安全担当課長","answer":"二輪車については、以前も委員会でお答えしましたが、撤去はもちろんのこと、警察署の取り締まりが効果的ですので、管轄の荏原警察署のほうに協議会を通じて積極的にお願いしてまいりたいと考えております。","id":"exchange-004"},{"speaker":"大沢委員","kind":"意見","question":"これは補助２６号線の歩道部分の横に置くことによって、歩道部分の人が歩くべきスペースを阻害している部分があります。５０ｃｃよりはかなり大きさも、幅もありますが、そこら辺の最近出てきたスクーターについてどのようにお考えになっていらっしゃいますかとの意見を述べました。","respondent":"山口交通安全担当課長","answer":"大型スクーターの駐車ということですが、武蔵小山駅の踏切のところに新しく駐車場ができていますので、大型スクーターの駐車場を設置、駐車場を管理運営される会社等に十分働きかけて、可能なのかどうか検討をしてまいりたいと考えております。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"平日、月曜日から金曜日までは役所も動いております。土・日の対策について特に重点を入れているようなお考えは、行政の話の中でおありになるのであれば教えてほしいと求めました。","respondent":"山口交通安全担当課長","answer":"土曜日についても撤去作業は行っておりますが、委員ご指摘のとおり、今後とも土曜日、日曜日、交番等もありますので、荏原警察署に合わせて取締方の強化をお願いしたいと思います。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"次に、「一般の交通の用に供される公の施設であり、常に良好な状態に保つことが必要であります」と書いてあります。私がお伺いしたいのは、行政側はどのようにお考えになるか、ご見解をお願いしたいと思います。","respondent":"山口交通安全担当課長","answer":"放置自転車、バイク等、私道にあっても、一般の交通に供される場合は道路交通法でも違反駐車等を取り締まる場合がありますけれども、そのような状況があれば、付近の私道関係者の了解を得て、放置禁止区域に指定可能であれば、したいと、今のところ検討をしています。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問・要望","question":"非常に取締りの難しい地域だと思いますので、そこのところご斟酌の上、施策を講じていただけるように要望します。三ブロックの地域の方の協議会が平成１５年に約４回ぐらいにわたりまして協議会が行われましたけれども、教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"平成１５年度に沿道の区民の方を対象にしまして、約３０名程度の方にお集まりいただきまして、基本計画まで作成をいたしました。これは協議会ではございませんので、基本計画を作成するまで区民の直接の参加でつくり上げたというものです。","id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"以降、平成１６年は開かれなかったのかを１点お伺いしたいのと、開かれた結果のほうは、地域の方への周知のほうはどのような状態になっているのか、お尋ねします。","respondent":"岩田管理工事課長","answer":"ワークショップにつきましては、基本計画は昨年の２月末ぐらいでまとまりましたので、その後つくり上げました基本計画につきましては、沿道の町会の回覧板を通じまして皆さんにご周知を願ったところです。","id":"exchange-009"},{"speaker":"大沢委員","kind":"意見","question":"急に線路から歩道になったがために、土地の形状は変わりませんが、家の建っている形が変わってきた。防犯を非常に懸念されるところですが、そこらの取扱いをどのようにされるのか、お尋ねいたしますとの意見を述べました。","respondent":"岩田管理工事課長","answer":"これをたたき台にしまして、来年度詳細設計委託に出しながら、今度は具体的に直近の方や町会の方を対象とした住民説明会を開催していく予定です。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"私もワークショップに出させていただきました。そしてなおかつ緑の多い、きれいな緑道ができることを望みまして、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"２７７ページ、都市景観形成事業、２８７ページ、木造住宅耐震診断支援事業、２点で行わせていただきます。それで、これまでの本区におきましての景観に対する取り組みを知らせてほしいと求めました。","respondent":"藤田都市計画課長","answer":"これまでの品川区におけます都市景観の取り組みですけれども、実施計画の中で位置づけられ、これまで進めてきてあります。今回、委員の区民公募を実施いたしまして、それをもとにこれまで３回の景観ガイドプランの策定の懇談会を実施してきたところです。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"今回の景観ガイドプランがそのスタートというふうに受けとりました。景観に取り組んでおられるわけですけれども、それでもなぜ今まで品川の景観行政がなかなか前進をしなかったのか、そこら辺の分析はいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"実施計画の中でうたわれている項目として実施できるところはやってきておりますけれども、具体的に品川区において条例等を定めてきたところではなかったということで、それに基づいて今後景観に基づくさまざまな施策を展開していきたいというふうに考えているところです。","id":"exchange-013"},{"speaker":"若林委員","kind":"意見","question":"例えば盛岡市で言いますと、昭和４０年代から景観に関して、今の景観法ができるずっと前から取り組んでおられる。そういう情熱みたいなところ、目標みたいなところがありましたら、ぜひお聞かせ願いたいと思いますとの意見を述べました。","respondent":"藤田都市計画課長","answer":"各地域においてそれぞれ地域において、地域の皆さんで具体的にさまざま検討をしていただくのが大切かなというふうに考えてあります。地域の方々が景観をこういうふうにしていきたいといったところに向けての区としては支援をしていくために、今回景観ガイドプラン。","id":"exchange-014"},{"speaker":"若林委員","kind":"提案","question":"たしか昭和６２年からでしょうか、私どものほうで提案をして、品川百景というものがあります。こういう百景の見方、核づくりという点で、もう一言お願いしたいと思いますとの意見を述べました。","respondent":"藤田都市計画課長","answer":"その中で百景も大きな役割を果たしているかなというふうに考えてあります。ただ、どのように生かしていくか、そういったことを具体的に今後検討していく必要があろうかなというふうに考えてあります。","id":"exchange-015"},{"speaker":"若林委員","kind":"確認","question":"昭和５６年５月末以前に建築確認を得て云々の木造戸建ての品川区における住宅数をお知らせ願います。それから、今年度初めて創設をされたわけですが、４０件で、現在何件まで申請がきているのか、お知らせを願いたいと思います。","respondent":"片田建築課長","answer":"平成１３年度の土地利用現況調査に基づきまして、これは住宅以外の建物を含みますけれども、約６万棟強の棟数があるということで認識しています。もう１点の、これまでの実績ですけれども、本事業につきましては、昨年の４月から事業を開始しています。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"大ざっぱに聞きますが、これを例えば区としての耐震化の目標数値というのはどのように設定されているんでしょうか。２万棟強のうち何％を、今の時点でございましたら、お聞かせ願いたいと思います。","respondent":"片田建築課長","answer":"二、三件の耐震改修についての実施設計といいましょうか、設計を行いたいといったような相談がきているというような話は聞いてあります。特に防災都市づくり推進計画の中で、危険度、現時点で何棟を最終的には目標とするという数字のところまでは想定してございません。","id":"exchange-017"},{"speaker":"若林委員","kind":"確認","question":"国土交通省のほうでは９０％に達するように、あと１０年ぐらいを目処にという数値目標が出されたように伺っております。施行する人の意思によって図面が幾らでも変わってしまうというような恐れがありますので、その点だけ今後の取り組みを確認させて下さい。","respondent":"片田建築課長","answer":"国土交通省、あるいは耐震診断のシステムマニュアルといったような参考図書をベースに診断を行っているというような状況です。どこを補強したらいいかといったような流れを含めて、ご相談者のほうには逆に区のほうから診断の中でご提案をしているというような状況です。","id":"exchange-018"},{"speaker":"川西委員","kind":"質問","question":"短い期間で枯れてしまうものなどの点検などは、委託の中の条件に入っているかどうかということを伺います。公園管理についても区民参加ということを区が進めておられるので、そういうものもこれからどういうふうに考えていかれるのか、伺います。","respondent":"松代道路公園課長","answer":"利用される方々のいろいろな窓口等の対応、それ以上に民間に移りましてサービスが向上したというような利用者からの声をいただいているところです。こういったものをさらに進めていきたいと考えています。","id":"exchange-019"},{"speaker":"川西委員","kind":"質問","question":"歩道橋の管理のことだけで追加しますが、夢さん橋と大森歩道橋は管理委託先は、エスカレーターの管理が中心のような会社なのか、その辺の中身についてちょっとだけ伺います。","respondent":"松代道路公園課長","answer":"歩道橋の管理は、機械本体の安全性をきちんと常に確保するという意味の整備、点検、また、その周辺の清掃、あそこはドーム型になっておりますので、窓をふいたり、日常気持ちよくご利用いただけるような管理内容で委託しているものです。","id":"exchange-020"},{"speaker":"川西委員","kind":"質問・要望","question":"一つは、工作物移設等助成金、奨励金ということで、これは何なんでしょうかということです。最初の計画の緑道計画というのが２０年も３０年も前からあったんですが、それは断念して、その辺を伺います。","respondent":"片田建築課長、岩田管理工事課長","answer":"建築課のほうで特に私道、公道を問わず、建築の機会を捉えてセットバックをしていただくといったような制度になってあります。工作物等の撤去費の助成、そういう事前協議をさせていただいた中で… 基本的には払い下げ処分を順次行っていくということで進めておりまして、具体的に毎年二、三路線ずつ売却予定の計画は持ってあります。","id":"exchange-021"},{"speaker":"川西委員","kind":"質問・要望","question":"今の最後のご答弁ですが、まだ全然お話が区にないということで、これはお答えはいいです。中身をご説明いただきたいのは、２８１ページの大崎駅周辺地区コーディネート業務委託、この中身についてご答弁を下さい。","respondent":"上野都市開発課長","answer":"それに要する費用、それから、西口のまちづくり協議会の運営に要する費用です。それから、散水に関する費用につきましては、これは御成橋から散水施設で放水いたしていますけれども、その使用料に要する費用です。","id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"建築物の解体に係わる問題ですけれども、平成１５年の決算特別委員会のときにこの問題のお聞かせを願いました。その検討の状況と、結果どうなっているのか、その辺をお聞かせ願いたいと思いますとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"庁内論議が整っていないですので、今後ともすぐに庁内で手法等について相談をしながら、決めてまいりたいというように考えてあります。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、もう２年以上の歳月が過ぎているわけですけれども、ぜひ急いでいただきたいという思いがあります。ですから、その辺の考え方というのをもう一度ご答弁願えればというふうに思います。","respondent":"浜脇住環境整備課長","answer":"今アスベストの話が出ましたけれども、そういったものに注意をしておれば、そういったものは自己が責任を持ってやっていくです。私どものほうが考えているのは、そういったことを中心に説明をするですので、もう少しこれは検討の余地があるのかなというふうに思ってあります。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"最もアスベストが使われた時代の建物が大量に解体をされるという時期にきているわけですから、これをどうやって建設業者、事業主に。こうした状態を長期間放置しておくというわけにはいかないと思いますけれども、もう一度ご答弁をお願いします。","respondent":"片田建築課長","answer":"４品目になって、あるいは規模によって、大気汚染防止法等の法律があります。区のほうとしては環境課のほうにきちっと報告を出すようにというような形での指導をしているというような状況です。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"ですから、床材などは歩くたびにこすれれば古くなっていけば飛散をする。２年近くかかっているわけですから、いつになったらこれが終わるのかということもお知らせを願います。","respondent":"金井環境課長、浜脇住環境整備課長","answer":"今後につきましては、確かにこれは潜伏期間が非常に長いということでありますけれども、これは相当程度１人の暴露量が多い場合です。そういうことも含めまして、広報ですとかホームページも活用して… 私どもは当初、建築紛争の最初の火種になるということで、ちょっと騒いでおったものですから、先ほどこういった化学的なことについては若干検討が薄かったわけですので、今後そこも勉強して、早急につくってまいりたいと考えています。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問・要望","question":"ですから、実際にそれに反応するという体質を持っていれば十分にどんな状態でも発病していくというふうになると思います。きっちり法規どおりに守られてこれが解体をされているか、ここを確認をするという体制づくりまで必要ではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"具体的に２８３ページに出てくるりんかい線のお話を聞かせてほしいと求めました。４００億円と増えた場面もありましたけれども、区全体の経済としてその辺つかんでいらっしゃる部分で結構ですから、教えて下さい。","respondent":"藤田都市計画課長","answer":"委員ご指摘がございましたとおり、あるいは活気のある街並みができたということになってきたかというふうに考えてあります。言い替えれば、りんかい線が開通したことで経済効果は上がってきているというようなことで判断しています。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"なぜなのかという、それではこういう手を打っていけば、商店街に潤いが出てくるはずだということを検討する必要があるんだろう。その辺を少し聞かせてほしいと求めました。","respondent":"日下部産業振興課長","answer":"これはやはりポテンシャルが上がってきた成果だと思います。具体的に、具体的にどういう形で把握をしていったらいいのか、今後検討をさせていただきたいというふうに思います。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"モノレールまで一緒にしてしまうぐらいですから、きちんとつかんでいく努力はすべき、わからないというのは違うと思いますよ。ですから、その辺をぜひお願いしたいんですけれども、続く話にも関係してくる。","respondent":"藤田都市計画課長","answer":"ここの短絡線の部分に限って申しますと、その十分な説明、あるいは話し合いはＪＲのほうに行ってほしいといったことの申し入れも行ってあります。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"意見","question":"やっぱりこういうことがＪＲにとっては必要なんだというのを出してきてほしいと思いますし、品川区としては、さっき言った。お願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"２８７ページの木造住宅耐震診断事業と、２６９ページの細街路拡幅整備事業についてお伺いします。初めに、木造住宅耐震診断ですが、予定件数が４０件と、発生の予定が５件とプレス発表に出ていますが、この理由をご説明下さい。","respondent":"片田建築課長、阿部住宅課長","answer":"４０件の理由ですけれども、実は平成７年の阪神・淡路大震災以来、他区のほうとしてもいろいろな支援制度を策定してきたというような状況があります。区としても今回立ち上げる中で… あっ旋の５件ですけれども、４０件の中で耐震診断を受けた中での想定です。他区の状況を見ながら、５件を想定したです。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"プレス発表で「中越地震に学ぶ」という項目から出ているんですけれども、中越地震で何を学んだか。それと、中越地震が起きた後に耐震の診断をする件数というのは増えたか、教えて下さい。","respondent":"片田建築課長","answer":"経過といたしましては、昨年の１１月の時点では概ね１０件から１１件ぐらいの申請件数というような状況がございました。３月８日には、４２件ということで、そういう形にはなったということで私どもは評価しています。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"これから答弁いただきたいんですが、こういうふうに助成しますよ、どんどん受けて下さい。別に考えなくてはいけないんですけれども、どんな形で行政として耐震診断をアピールしているのか、そこのところをお聞かせ下さい。","respondent":"片田建築課長","answer":"先ほどもご説明をさせていただきましたように、他区の実績等を含めて４０件を出したといったような経過があります。それを活用していただくということが先決かと私は思っていますので、その件数の様子を見て検討はしていきたいと思ってあります。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"続きまして、細街路拡幅事業ですけれども、しなければいけない道路、品川区に物凄い距離があると思うんですが、現時点でどのぐらいの達成率をしているんか尋ねました。","respondent":"片田建築課長","answer":"平成１５年度の成果の中での考え方としては、拡幅延長としては約５.１km、４,０００m2弱といったような状況になってあります。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"２７６ページの公園管理費、２６１ページの放置自転車対策で、使用料などの収支のほうから伺っていきたいと思います。先ほども質問がありまして、３回の懇談会が行われたということですけれども、今後の公表のスケジュールを教えて下さい。","respondent":"藤田都市計画課長","answer":"これまで３回の懇談会を開催していますけれども、今週末に第４回目の懇談会が予定されてあります。懇談会のほうから提言をお受けする予定になってありますので、製本、平成１７年度早い時期に公表していきたいというふうに考えてあります。","id":"exchange-036"},{"speaker":"井上委員","kind":"意見","question":"同じ２７７ページの下のほうに、区民の自主的なまちづくりへの支援という項目があるんですが、これとは何か関係があるのかというところをお聞かせ下さいとの意見を述べました。","respondent":"藤田都市計画課長","answer":"各地区の中のモデル地区的な扱いの中で景観計画等の策定のためのさまざまな事業を展開していきたいというふうに考えてあります。通常ですと、実際には景観づくりを進めたいといった、そういったところにも併せて周知を図っていきたいというふうに考えてあります。","id":"exchange-037"},{"speaker":"井上委員","kind":"意見","question":"この懇談会の公開をするか否かの検討がされたのかどうか、今は非公開になっているわけですが、その辺の理由をお知らせ下さいとの意見を述べました。","respondent":"藤田都市計画課長","answer":"懇談会の中では、もともとの出発点が自由な発想で、自由な議論をして，景観づくりのための議論を重ねていきたいといったような発想がございました。公開をすることで、委員の皆さんのご意見もございまして、懇談会の中で仕切る中で公開はしないというような形になったものです。","id":"exchange-038"},{"speaker":"井上委員","kind":"意見","question":"自分たちの意見をどう発言をしていこうかということで、そういう公開の原則というものを持ってほしいという声があるということをひとつお伝えして。","respondent":"榎本行財政改革担当課長","answer":"附属機関の公開、非公開につきましては、今までもそうですけれども、審議する機関の中で決めていくということを基本方針にしております。公募委員も含めて集まっているわけですが、その姿勢をきちんと決めた上で審議会を進めているというのが実情です。","id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"審議会の中で設置要綱に原則公開とするというような項目が設けられている会もありますので、積極的にそういった公開を進めていってほしいと思います。ぜひ出前講座的な制度を設けてほしいと思いますけれども、特にここではまちづくりですけれども、そういうふうな方針はいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"今回のガイドプラン、景観に係わる部分で申し上げますと、今の段階で区民の皆さんは知らないといったこともあろうかと思います。地域の皆さんが、私どものほうとしてはそういうご依頼を受ければ、説明に伺うということも当然あろうかなというふうに考えてあります。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"まちを知りたいという方たちにも積極的に出ていっていただけるような何らかの仕組みをぜひつくっていただきたいということを要望して、次にいきます。２７６ページの公園管理費ですけれども、今一番問題になっているようなことがあれば、ご紹介をほしいと求めました。","respondent":"松代道路公園課長","answer":"私どもは２１５カ所ほどの公園を管理しておりますので、あとは公園の利用にあたっての細々したこと、そういったものが分類としてはあるように感じてあります。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"昨日も地域猫ということで質問が幾つか出ておりまして、こういったものに何かご感想があれば、お伺いできますか尋ねました。","respondent":"松代道路公園課長","answer":"私ども地域猫というような認識ではなく、今一番の問題は、そういった猫が増えているということが問題です。地域猫という言い方は、地域の方も一緒にその問題を考えていただく、我々も取り組んでいかなければならない問題だというふうに考えておるところです。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"そういう活動をしている方たちもいるというような、文章を変えていくような改善ができるのかどうか、その辺はいかがか尋ねました。","respondent":"松代道路公園課長","answer":"ただ、やる側にも、地域の方にもご理解いただけるような看板等の内容にしてもらえないかというようなお話を聞いてあります。私どももなるほどそういう点では少し改良の余地があるかと思いますので、今後そういった形での改良等をしてまいりたいと考えているところです。","id":"exchange-043"},{"speaker":"井上委員","kind":"質問","question":"今回飼い主のいない猫にも手術費用がついたということでは、道路公園課と健康課と関係する部署が一緒になって地域住民の方との意見交換の場の運動を持っていかれたらいいかと思いますけれども、その辺のお考えをお聞せいただきますか尋ねました。","respondent":"松代道路公園課長","answer":"おっしゃるように、今までも保健所、また健康課と連携をしてやってまいりました。さらに、看板等一つとってみても、いろいろな点でこれからも連携をとって対応をしてまいりたいと考えています。","id":"exchange-044"},{"speaker":"井上委員","kind":"質問","question":"私が計算したところによりますと、撤去するだけでなくて、維持費とか、委託とかするともう少し多くなるのではないかと思うんですが、３,９００万円ぐらいということでいいんか尋ねました。","respondent":"山口交通安全担当課長","answer":"現在の見込額での計算ですので、ご了解をいただきたいと思います。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"先ほど大沢委員からも駐輪や対策に対しての住民の協議会ができるということだったんですけれども、自転車利用者を入れ込んだそういった協議会も必要だと思うんですけれども、その辺はいかがか尋ねました。","respondent":"山口交通安全担当課長","answer":"関係者ばかりでなくて、利用者、確かに予定は大井町のほうも、これからできます武蔵小山も自転車利用者を入れて、ご意見を伺って、また、学識経験者もできれば予定をしています。","id":"exchange-046"},{"speaker":"武内委員","kind":"質問・要望","question":"２７７ページの公園・児童遊園の維持管理費と、２６９ページの道路バリアフリー事業の側溝段差解消というこの辺をやらせてほしいと求めました。現在の区の考え方として、公園・児童遊園の中に犬を入れるというのは禁止されていると思いますが、その辺の確認をさせてほしいと求めました。","respondent":"松代道路公園課長","answer":"先日もお答えしましたように、原則として禁止をしています。しかしながら、実際犬を連れて入られているという状況は、ほとんどの公園でそのような状況にあると認識しております。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問・要望","question":"その中で、昨年の１１月に世論調査の結果をいただきまして、この中で公園と犬ということで、何点かアンケートをとられています。ある程度の条件を満たせばいいんじゃないかという方が６割近くいらっしゃるという中で、また、お知らせほしいと求めました。","respondent":"松代道路公園課長","answer":"これまでもいろいろと検討をしてきたんですけれども、どう考えていらっしゃるのか、今回世論調査でお聞きしたところです。それともう一つは、マナーを守ってもらうような手当ても考えていかなければいけないと、こういうようなことを今考えているところです。","id":"exchange-048"},{"speaker":"武内委員","kind":"質問","question":"区内で１人で犬を２頭、３頭と飼っていらっしゃる方もいると思うんですが、教えて下さい。","respondent":"松代道路公園課長","answer":"正確な数字は後ほどお答えするとしまして、今ペットブームでございまして、非常に増えてあります。従前からしまして３倍、４倍増えているような、非常に増えているというような状況にあります。","id":"exchange-049"},{"speaker":"武内委員","kind":"質問・要望","question":"私自身も犬はどうかと言いますと、それほど好きではないですけれども、決して排除するものではないというふうに感じております。好きな人もいれば、先ほどある程度答弁をいただきましたけれども、前向きに検討いただけるのかどうかを含めて確認をさせてほしいと求めました。","respondent":"松代道路公園課長","answer":"これはもちろん保健所と連携をしながらですけれども、西大井広場、東品川海上公園の大きな公園等で試行的にやっていきたいと思ってあります。","id":"exchange-050"},{"speaker":"武内委員","kind":"質問・要望","question":"次に先ほどのバリアフリーのところでお聞きしたいと思います。こういったところに対しての助成というのは今はなされていないかと思うんですが、その辺の理由がありましたら、教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"私道整備条例に基づいて助成をさせていただいておるわけですけれども、この場合、区で助成できる範囲が制限列挙をされております。現存する階段の補修、新たに設置する手すり等、こういったものも補助対象になってあります。","id":"exchange-051"},{"speaker":"武内委員","kind":"確認","question":"整備条例でそういう形でというのは確認させていただきました。バリアフリーということで、段差解消という部分では対象になっていないんじゃないかと思うんですが、その辺のご認識をお知らせ下さい。","respondent":"岩田管理工事課長","answer":"これは東京都の福祉のまちづくり条例でスロープ勾配を５％以下にしなさいという基準がありますので、現存の階段延長の何倍ものスロープをそこに設置をするということになりまして、現在の助成制度の中では難しいです。","id":"exchange-052"},{"speaker":"武内委員","kind":"質問・要望","question":"個別にご相談をさせていただいた件についてちょっと伺った感じなんですが、１０段以上あるような階段のところで、六百万円かかるというんですね。介護の方とかいらっしゃって、ぜひそういった部分で個別の配慮ができないのかどうか、その辺のところを教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"２ｍ５０cm以上の幅員があって、エレベーターのような機械式の昇降装置を付けるとなりますと、これは条例にはなじまないと思います。","id":"exchange-053"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中で、品川区内は６路線がこの中で示されておりますが、もの申す部分というのは含まれているんでしょうかということがまず１点です。建築指導費の関係ですが、その中で、ケーブルテレビを建築指導の中でどういうふうに捉えているかということの点についてお聞きしたいと思います。","respondent":"藤田都市計画課長、片田建築課長","answer":"ただいまご質問の区部における都市計画道路の整備方針ですけれども、東京都と２３区合同で策定してきたものです。あるいは交通量が多い場所… 品川区全体の中でまだ視聴が困難だという箇所が地域ごと約１,３００世帯強ほどあるということで聞いてあります。","id":"exchange-054"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"個別に区からも要望しているという中で、補助２８号線、青物横丁のところがこの中に含まれました。区としてケーブルテレビをどういうふうに捉えているか、部署が違うと思うんですが、もう一度お聞きしたいと思います。","respondent":"藤田都市計画課長、榎本行財政改革担当課長","answer":"昨年３月にこちらの整備方針のほうが発表された後、まずは品川区で１回お話をしようということで、説明をさせていただきました。そのときには整備方針のほうが平成２７年までに整備または完成をさせる路線というようなことでご理解を得… 区民チャンネルの視聴可能世帯数が７割に近くなっているという中で、実際に地域メディアとしてのそういう活用を考えていくということで、魅力ある地域メディアとして育てていきたいというふうに考えております。","id":"exchange-055"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それがどっちがいいかというのは、これからの細かい判断も出ると思いますが、その中で、その辺も考えておいてほしいと求めました。そういった新しい部分の建物にもケーブルテレビというのは入っているものですか、その辺答えが分かるかどうか、お聞きしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"住宅につきましては、建設型の区民住宅には全部入っております。それから、それぞれのところを解消してもらうと同時に、その建物についてもＣＡＴＶを入れていただくように協力を要請しています。","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先般業者と話したときに、ケーブルテレビが入るんですかと言ったら、「いや、考えていない」と言われました。新築のときだったら、その時点で建築のほうで付ければすべて入ってしまうと思うんですが、その辺についてのお考えをお聞きしたいと思います。","respondent":"浜脇住環境整備課長","answer":"私どもは中高層の建物ができた場合には、今のところＣＡＴＶの建物にしなさいとか、対策をＣＡＴＶにしなさいとかといったことは言ってございません。かなりお金もかかるということで、強くは言ってございませんが、こういうものがあるということは口頭では伝えてあります。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうじゃなくて、今の答えは答えとして分かりますけれども、これからそこに住んでもらう人に対して、区としてそれでいいんですかと。お金がかかるから付けてもらえないで済ませてしまっていいのかなというところを感じているんですが、この辺についてお答えをいただけないか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"実際に集合住宅のほうにもかなりの戸数がＣＡＴＶに加入していただいておりまして、都営住宅等も全部加入をしていただいております。確認がとれてからということですけれども、そこに住んでいるなるべく多くの方に見ていただくという姿勢には変わりございません。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何回も繰り返しになってしまうんですけれども、中古のマンションだと、新規加入は１００万円ぐらいと出ていたかな。個別は個別に入るんでしょうけれども、ケーブルテレビの本の中にはそんなふうに出ていたような気もするんですが、その辺数字は分かりますか尋ねました。","respondent":"中尾根企画部長","answer":"個別住宅の加入の予定が約２,０００、電波障害が７００ということで、年間６,７００ぐらいの加入目標の計画になっております。それが強制になるようなバックはありませんので、その辺のところは根気よく話を建設主にして、了解をいただいているという現状です。","id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これで最後にしますが、区のメディアという意味でのその辺をこれからも考えていただきたいなということで、お願いします。今まで八潮と不動前に放置された自転車の処分について、どのようにしているのか、その点から教えて下さい。","respondent":"山口交通安全担当課長","answer":"撤去保管した自転車については、返還引き取りに来たものについてはもちろん渡しておりますが、残ったものについてはリサイクル、海外供与、それでも使えないとか、残ったものについては廃棄処分をしております。","id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"廃棄処分の件ですけれども、区のほうからお金を払って廃棄しているという部分をちょっとお聞きしました。オートバイも廃棄にかかっているということなんですけれども、廃棄の方法が考えられないかなということでお聞きいたします。","respondent":"山口交通安全担当課長","answer":"廃棄については、年間３５０万円程度廃棄の費用がかかっておりますが、新年度から売却を検討したいと思っていますので、併せて資源の有効活用、また、二輪車についても資源の有効活用ということで売却を検討課題とさせていただきたいと現在のところ考えております。","id":"exchange-061"},{"speaker":"本間委員","kind":"意見","question":"２８３ページ、２６７ページ、簡単にやりとりをしていきたいというように思います。日曜日も含めて、そして作業時間帯はどうなっているのか、簡単にお願いしますとの意見を述べました。","respondent":"山口交通安全担当課長","answer":"作業時間帯については、午前７時から午前９時、午後３時から午後６時等、平均しますと、概ね午前中３時間、午後３時間等を予定しております。日にちについては、月２８日を計算しております。","id":"exchange-062"},{"speaker":"本間委員","kind":"質問","question":"午前中も質問の中に出ておりましたように、その辺が盲点にならないような形でお願いしたいというふうに思います。複数回撤去された人がどれだけいるとかというふうな部分を、実際にいるんだろうと思いますが、およそのことでお分かりか尋ねました。","respondent":"山口交通安全担当課長","answer":"２８日は、新年度から武蔵小山を強化する意味で２８日ですが、ほかのところは２０日を予定しております。勘弁してくれないか」という電話を受けたことは数回あります。","id":"exchange-063"},{"speaker":"本間委員","kind":"質問・要望","question":"一時的、便宜的なということでなくして、きちっとしていただけないかなという要望にとどめておきたいと思います。この二つの観点から、特に補修工事の部分は、どこを、どのようにされようとされているのかお聞かせ下さい。","respondent":"矢部下水道河川課長","answer":"右岸合わせて約９０ｍですが、大潮のときに顔を表すような部分で、鋼管矢板がちょっと腐食しております。ひどいところは穴があいたりしておりますので、そういうのが判明いたしましたので、今回緊急に補修をするものです。","id":"exchange-064"},{"speaker":"本間委員","kind":"質問","question":"品川区の対応ですか、地域と品川区とのすみ分けをどういうふうにしているのか、品川区の役割分担はどうなっているのかについてお聞かせ下さい。","respondent":"松代道路公園課長","answer":"しながわ花街道のご質問ですけれども、平成１４年１０月ぐらいに発足しまして、第１回の花植えということで、今年３年目に入ってまいります。土壌の改良等も私どもが協力してやって進めているところです。","id":"exchange-065"},{"speaker":"本間委員","kind":"質問","question":"それから、通常、１年を通じてでは、犬の糞の後始末とか、夏になると、今度は夜の花火の打ち上げ等々の後始末等々の部分が出てきます。この辺の部分につきましてはどのようにお考えか尋ねました。","respondent":"松代道路公園課長","answer":"桜の剪定、また害虫等の駆除、日常のあそこのところの通りの清掃等は地域の方々が花植え等を含めてやっていただいているです。糞とか、花火等の管理も私どもが責任を持ってやっているところです。","id":"exchange-066"},{"speaker":"本間委員","kind":"質問","question":"これから花街道が次から次へと新しいイベントを繰り出してくると思いますけれども、あそこの水辺を使う行事がありますね。この水辺を使う行事では、この辺の許可といいますか、使い勝手という部分はどのように捉えているのかを教えて下さい。","respondent":"松代道路公園課長","answer":"しながわ花街道でいろいろと花植えに合わせてイベントが計画されております。水上警察と協議をしまして、水上警察も港湾局のほうも比較的協力的でございまして、イベントが成功しているというふうに地域から聞いてあります。","id":"exchange-067"},{"speaker":"本間委員","kind":"質問","question":"しかし、これからの部分で地域の皆さんとのトラブルのないような形でご配慮をお願いしたいというふうに思います。それから、その関連ですが、立会川の護岸の緑化についてどのようにお考えでしょうか、お答えをお願いします。","respondent":"松代道路公園課長","answer":"川沿いに緑化をしていきたいという考えを持ってございまして、今地域のほうで護岸の柵にプランター等をやっていただいています。管理も含めていいものがあるのか、話をしながら、緑化を進めていきたいと考えています。","id":"exchange-068"},{"speaker":"本間委員","kind":"提案","question":"市街地再開発事業補助金等々、広町地区開発構想策定云々とありますが、大井町西地区の件についてお尋ねします。そして第一種市街地再開発事業の決定等々を骨子としたものを提案するというふうなことを、今後の行く末について見通しをお尋ねしたいと思いますとの意見を述べました。","respondent":"上野都市開発課長","answer":"これまで地元の再開発準備組合によりましてまちづくりの検討が行われてまいりまして、地元の権利者の方々から、区に対してご要請がございました。来年度組合設立、平成１８年度着工、平成２０年度竣工に目指して詳細の検討を進めていくという予定です。","id":"exchange-069"},{"speaker":"本間委員","kind":"質問・要望","question":"これが、ともすると補助１６３号線の拡幅のみに事業が進んで、どうかその辺の部分も含めてこれから地域の皆さんの要望を取り込んだ形の中で。この部分は補助１６３号線の道路拡幅と、将来をにらんでの電線の地中化等も頭においてのことでしょうか、お聞かせ下さい。","respondent":"藤田都市計画課長","answer":"現在新たにつくる都市計画道路につきましては、すべて電線共同溝にしていくといったような形の国の方針が示されてあります。そうした中で補助１６３号線、現在用地買収をどんどん進めておりますけれども、補助１６３号線の中に電線共同溝を入れていくための設計の準備です。","id":"exchange-070"},{"speaker":"本間委員","kind":"質問","question":"そうしますと、同じ２６７ページのところに補助１８号線にもそのような部分が載っておりますけれども、まちの景観、将来のまちづくりの発展につながる部分として、電線の地中化ということを念頭に入れての予算計上、いわゆる設計委託だというふうに考えてよろしいか尋ねました。","respondent":"藤田都市計画課長","answer":"委員ご指摘のとおり、都市計画道路を進めていく中で、景観にも配慮したまちづくりを進めていこうということで、こういった形で載せさせていただいているものです。","id":"exchange-071"},{"speaker":"本間委員","kind":"意見","question":"それから、すでに話が立ち消えになっているかもわかりませんけれども、補助１６３号線の拡幅に伴って、従来のバス路線の変更について、どのようなお話が地域で出ていたのかについて分かる範囲でお聞かせ下さいとの意見を述べました。","respondent":"藤田都市計画課長","answer":"現在、補助１６３号線は用地買収等を進めてありますけれども、補助２６号線のほうについても事業がどんどん進捗してきてあります。骨格の道路ができてまいりますので、東急電鉄があたってありますけれども、その辺にも要望を出しています。","id":"exchange-072"},{"speaker":"本間委員","kind":"質問","question":"一度出かかった話が、補助２６号線、補助１６３号線の進捗状況に合わせて東急電鉄と現在折衝中であるというふうなことでよろしいでしょうか。地域の声を区政に反映して頑張ってまいりますので、皆様方もよい仕事をしていただきますように心から希望いたしております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問","question":"私は、２８７ページの耐震診断と改修工事について伺いたいと思います。現実から見なければいけないと思うんですけれども、そういう目標を考えて、つくっていくというお考えはどうか尋ねました。","respondent":"片田建築課長","answer":"公的補助制度の見直しとか、あるいは税制面での優遇制度といったようなことの検討に入るといったような状況を確認しています。そんな中で、今後の状況を踏まえて、その辺は検討する課題だと私は考えてあります。","id":"exchange-074"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ぜひ目標を、国のほうもいろいろ検討を始めているようですので、実態に合わせた目標、計画にしていただきたい、このことを強く求めたいと思います。当時働き盛りで、こういうところの方々にどういうふうに対応するのかというふうに思うんですけれども、そこのところの考え方はいかがか尋ねました。","respondent":"片田建築課長","answer":"建て替えが進んできているということを考えると、少なくとも２万二、三千棟からは若干は少なくなってきているのではないかなと思ってあります。","id":"exchange-075"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私は、そこのところの、実際に今必要とされている、昭和５６年以前の建物ですから、高齢者が多く住んでいるだろうと。ですから、融資を受けられないだろうと思われる方々の対応というのを改めて求めたいと思うんですけれども、その考え方をもう一度お願いしたい。","respondent":"阿部住宅課長","answer":"もう１点、現在耐震診断を受けた方の平均が大体１５０万円ですので、今回の耐震改修についても一応１５０万円を想定しております。それを本人負担が０.９％の利率で貸し付けるという考えです。","id":"exchange-076"},{"speaker":"宮崎委員","kind":"質問・要望","question":"改修のほうは大体１５０万円という予想だということであれば、ここで補助制度をつくれば、これが呼び水になって進んでいくというふうに思います。ですから、このことを強く要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"築舘委員","kind":"質問","question":"２６１ページの交通安全対策費と、２７６ページの公園管理費について質問をいたしたいと思います。シルバー信号機とか、そういうようなこととかいろいろあると思うんですが、今の現状を説明して下さい。","respondent":"山口交通安全担当課長","answer":"参加体験型については大井競馬場で３００名ほど参加していただき、いろいろな体験をして、事故防止に努めておるところです。今後の対策については、少人数の出前型の安全教育をこれから警察と日程を調整しながらかみ合えば実施していきたいと考えております。","id":"exchange-078"},{"speaker":"築舘委員","kind":"質問","question":"着用している人の１７.３倍も死亡率が高いというようなことも、飲酒運転の事故も大分減ってきているんじゃないかと思うんですが、その辺の傾向を教えて下さい。","respondent":"山口交通安全担当課長","answer":"本件につきましては、警察と協力して安全教育を行うとき併せて引き続き携帯電話の使用禁止等を呼びかけていきたいと考えています。私だけは別だと、取り調べなどでも、そういう言葉を聞く機会が結構多うあります。","id":"exchange-079"},{"speaker":"築舘委員","kind":"意見","question":"自動車の駐車違反も、これから民間に委託されるというようなことも言われているんですけれども、その辺は今後どういうふうになるかということ。区役所通りなど大井の交通安全協会の皆さんが月４回、警告をしているということですが、その駐車違反対策をお願いしますとの意見を述べました。","respondent":"山口交通安全担当課長","answer":"駐車違反の関係、民間委託というお話ですが、これも道路交通法改正で、来年の６月からの実施の予定です。２点目の違法駐車防止指導員の関係ですが、月４回活動をしておりまして、今大井町駅前、東急前のところにカメラを設置する予定です。","id":"exchange-080"},{"speaker":"築舘委員","kind":"確認","question":"先ほど川西委員からも質問が出ておりましたけれども、その辺の、どういう形の仕事の内容をしていくのか。その辺をちょっと確認しておきます。","respondent":"松代道路公園課長","answer":"そうは言いましても、１２haの公園の管理ですので、今までの技術職の体制４名を５名にして管理をしていこうと考えています。今後の管理等につきましては、行く行くはすべて民間委託で管理運営をしていくというような形にしていこうと考えているところです。","id":"exchange-081"},{"speaker":"築舘委員","kind":"質問・要望","question":"１００名から３０名にということで、質の選択といいますか、そういうのをしっかりしていただきたいなというふうに思います。１年以上経って、その点を１年経って、しながわ中央公園のボランティアのことをお願いします。","respondent":"松代道路公園課長","answer":"は３連休などのときには連休の合間に来て水やり管理をしていただく、いい状態が続いている、これは大変いいことだというふうに感じてあります。","id":"exchange-082"},{"speaker":"築舘委員","kind":"意見","question":"今度北側の老朽化したフェンスも撤去して、屋上緑化を増やすということですけれども、その点どんな形にするのか。そして、８階の会議室の温度が２.５度下がったというような、その点ご説明願いますとの意見を述べました。","respondent":"鷹倉経理課長","answer":"壁面の部分を生かした形で、あらゆる緑化の方法を展示し、区民にアピールしていきたいなというふうに考えてあります。床面につきましても、健康的なことが何か工夫できないかとか、あるいは視界がいいような形で工夫ができないか等の検討を今重ねているところです。","id":"exchange-083"},{"speaker":"嶋委員","kind":"質問・要望","question":"私は、２番目は２６５ページの交通安全施設整備事業、これは信号機についてお伺いします。私は、思いやり信号をずっと要望をしてきたこともございまして、あとどのぐらいで赤になってしまうかという信号機が大分設置をされております。","respondent":"山口交通安全担当課長","answer":"今後とも違法駐車、放置駐車をしないように巡回し、撤去に努めてまいりたいと思います。駐車場の設置の関係ですが、駅前等は設置の台数が、駐輪場の設置までは至っていないのではないかという印象を受けております。","id":"exchange-084"},{"speaker":"嶋委員","kind":"質問・要望","question":"やはり釣り堀ですから、釣れないと楽しめないし、きっと利用されている人数が減少していると思います。これはどういうふうにして管理を、魚がある程度、そこら辺のお考えをお聞かせほしいと求めました。","respondent":"松代道路公園課長","answer":"そのときの状況かと思うんですが、私どももなるべく釣れるような状態で、気持ちよく帰っていただけるのが基本かなと考えています。委員のご指摘ですので、ちょっとその辺も少し調査をしてみたいと思いますが、楽しんで帰っていただけるようにしてまいりたいと思います。","id":"exchange-085"},{"speaker":"嶋委員","kind":"質問・要望","question":"区民の切ない楽しみといいますか、ぜひそこら辺をご配慮いただけたらと思います。それから、水処理施設の改修工事の５,８００万円の内訳をお聞かせほしいと求めました。","respondent":"松代道路公園課長","answer":"立会川のほうに放流して、きれいな水を浄化すると、そういうような埋め立ての条件と合わせた施設の目的があります。それらをつくった当時からかなりの年数が経ってきておりまして、施設の老朽化に伴う改修です。","id":"exchange-086"},{"speaker":"嶋委員","kind":"質問","question":"そういうこともあって、この５,８００万円の中に入っているのかという希望で、お聞きをいたしました。もう一度今の埋め立てのことを詳しく教えていただけますか。","respondent":"松代道路公園課長","answer":"平和島側と立会川のほうに埋め立ての下にカルバートボックスというものを２本設けまして、その水を取り入れて浄化して、かつ立会川のほうに流す。加えて水族館のほうのイルカプール、そういったところにもそこで浄化した水を供給する、そういった目的です。","id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、品川区の葬祭場の設置に関する環境指導要綱のことについてお聞きをしたいと思います。品川区のように要綱をぜひつくってほしいという住民からの運動や、議会からの要請があって、幾つかの区が……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この問題について説明をするように指導をしていただきたいということが１点ですけれども、住民が説明会を求めていることは伝えましたと。","respondent":"浜脇住環境整備課長","answer":"その要綱に基づきまして業者のほうは２回の説明会を行ったですので、業者は説明をしようと思った部分があるわけですけれども。それを私どもとすれば、準備して行ったものができなかったですので、これについては説明をする意思があったというふうに判断しています。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この視点で、区として住民がこれだけ求めているわけですから、毅然とした態度で指導をしていただきたいというふうに思っているんです。建築確認申請が出されたという状況になりましたけれども、そして、地域の方はがっかりしたというのが正直なところです。","respondent":"中谷まちづくり事業部長","answer":"説明会につきまして不足であれば、このようなご説明を、住民の皆さんの前でおっしゃったわけです。区のほうはもう一度住民に説明をするよう、区のほうは十分に間に立って説明をさせるということの指導を続けるつもりですので、ご理解下さい。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"交通面でも大変なというふうなところに葬祭場をつくるというふうな状況になっているわけですから。一つは、住民が求めるところで理解を得るように努めるというふうな立場で説明会を開いていただきたいということと、いかがか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"要綱の件ですが、業者のほうから言わせますと、すでに区に出して１０日以上過ぎても要綱の許可を出さない……。","id":"exchange-091"},{"speaker":"須藤委員","kind":"質問","question":"品川区が要綱をつくった理由を今部長が少ししゃべられて、時間がなかったので、そのことをご説明願いたいのと、それから、他の区で要綱をつくっていますけれども、品川区はそこと接道する部分が４ｍという数字を出していますが、他区ではどのくらいの広さで接道しているか、そのあたりを教えて下さい。","respondent":"中谷まちづくり事業部長","answer":"そして一定の建物との距離をつくる、あるいは緑化を行い、駐車場を確保する等の規定が定められているところです。杉並区、足立区等の例を見ますと、前面道路幅員が６ｍになっているというところが品川区と違うのかなというふうに考えております。","id":"exchange-092"},{"speaker":"須藤委員","kind":"質問","question":"トラブルがないようにということで要綱をつくっていただいたわけですから、まだトラブルが続いているわけですから、接点というか。いかがか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"６ｍ以上ありますので、今の要綱が４ｍになっているということでは、これの改正等につきましては検討をしてまいりたいというふうに考えております。区のほうもできる限り両者の接点に立ちまして、今後とも話し合いが続くような努力を続けていきたい、かように考えております。","id":"exchange-093"},{"speaker":"伊藤委員","kind":"質問","question":"２７９ページの水族館に関連をして、それから２８３ページ、東京臨海高速鉄道に関連して質問をいたします。地上部分で、事故等の状況等をＰＲしたほうがいいのではないかということの質問をして、どういうふうな動きをしているかということをお聞かせ下さい。","respondent":"藤田都市計画課長","answer":"設置する場所が駅の構内のＪＲ、あるいは東急電鉄と交錯していることから、詳細の協議をこれまで重ねてきたといったことで確認しています。","id":"exchange-094"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この電車ができることによってさまざまな効果が出つつあるということを答弁としてもいただきました。結果として多くの皆さんにつながっていくわけですから、もう一つ答弁をほしいと求めましたが、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"東京臨海高速鉄道の会社のほうとしては必要性を感じており、そういった方向で調整をするといった形で言ってあります。相手があることですので、そうした関係の中から、区のほうからも一日も早く設置ができるように要望をしてまいりたいというふうに考えてあります。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"確認","question":"前に何回か質問がありましたけれども、そういうことにならないように考えながら私どもずっと言ってきたわけでありますので、何点か質問をします。まず、確認だけしたいのが、しながわ水族館をこれからどういうふうにしていこうかという大きな基本的な考え方をお聞かせ下さい。","respondent":"松代道路公園課長","answer":"約６割の方がご利用いただいているということを踏まえて、その中では文化、これからも運営をしてほしいというようなご意見がございました。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"提案","question":"三提案ですけれども、そういうところへのこの水族館の売り込み、ＰＲをどうしているかということ。いろいろな方法で経営の方法を考えていかないといけないと思うんですが、いかがでしょうか、ご見解をお聞かせ下さいとの意見を述べました。","respondent":"松代道路公園課長","answer":"そういったものも検討していきたいというふうに考えておりますので、ご提案があった件も含めて、今後検討をしたいと思います。そういった魅力あるようなセット券、そういったものをサンシャインシティと今後検討を重ねて、提案をしていければと考えています。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問・要望","question":"うれしいことに、この間行ったときにもたくさん来られておりました。ですから、将来構想をお聞かせほしいと求めましたが、いかがか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"品川区のまちづくりを進めていく上で一番重要なのは、地域にお住まいの方たちのご意見をいかに反映していくかということが重要だと考えています。今後とも区民の皆さんから見えるまちづくり事業、こういうことを肝に銘じて進めていきたいというふうに考えておるところです。","id":"exchange-098"},{"speaker":"土井委員","kind":"質問","question":"２７７ページの従前居住者用住宅管理費、当然関連するのが２８３ページの密集住宅市街地整備、この辺についてお伺いしたいと思います。補助１６３号線については、残りのところは進捗を含めてどのような方向になっているのかというところをお伺いをしたいというふうに思います。","respondent":"岩田管理工事課長、藤田都市計画課長","answer":"これは地方公共団体です品川区が品川区全域を行うということで、現在の計画では約５０年を費やして実施をしていこう。ここを０.１ha、旗の台四丁目の０.１ha… 現在、事業中です補助１６３号線のほうが平成２０年度までの事業認可になってあります。その辺の進捗と合わせて、委員ご指摘の補助１６３号線のほうにつきましても事業を進めていきたいというふうに考えているところです。","id":"exchange-099"},{"speaker":"土井委員","kind":"質問・要望","question":"もう設計してあったわけですから、だれもが聞きたがっているものですから、その部分であります。それから、どういう状況にあって、どういう状況になっているのかということをちょっとお聞かせをいただきたいというふうに思います。","respondent":"矢部下水道河川課長、浜脇住環境整備課長","answer":"２番目の損害という話ですけれども、今回、設計変更ということで約１億２,０００万円減額補正をしております。どれぐらいのプラスアルファの損害というか、プラスアルファの費用が出るかというのは、今の時点では申し上げられません。 住宅については、まだ密集事業を今後とも展開していく予定があります。荏原北地区は今年度で終わりますけれども、来年度は２地区の継続、今後とも密集事業のために使っていこうというふうに考えてあります。","id":"exchange-100"},{"speaker":"土井委員","kind":"質問・要望","question":"建設工事ですから、図面が直されていればどうということはなかった話ですから、もし違ったことをやられたと。いろいろと利用したらいかがでしょうかということもいろいろ提起をされてきて、ぜひその意味では、ぜひ促進をしていただく意味も含めて。","respondent":"矢部下水道河川課長、浜脇住環境整備課長","answer":"昭和４０年代というのはまだそれほど技術的に確立されていない時代なのかなという形の中で、これは私自身の感想としてちょっと考えています。竣工図も、職員に対してはこういうことを一つの教訓として… それについては、予算書にあるとおり、建て替え等を積極的に進めたいというふうに考えてあります。そうすれば、この事業もまた進展していくのではなかろうかと思って頑張ってあります。","id":"exchange-101"},{"speaker":"土井委員","kind":"質問","question":"それで、事前のいろいろな調査、地質調査、土質、そういうものも含めた埋設物等々の検査をする手法というようなものはないんでしょうか。とてもということなのかどうかも含めて、こんなふうに思うんですけれども、そこら辺のご見解をお伺いしたいと思います。","respondent":"矢部下水道河川課長","answer":"基本的に埋設物の深さが浅い、１ｍとか１ｍ５０cm程度のところにつきましては、実際に掘さくをして、位置を確認するというのが基本です。ですが、今回の下水管は土被りが５ｍ程度ありまして、今５ｍまで調べる技術はございません。","id":"exchange-102"},{"speaker":"中島委員","kind":"質問・要望","question":"どのような連携があって、後の補修がされるのか、この点を１点お伺いしたいと思います。そういうことから、あのときはまだ緩和したばかりなのでということで、ご答弁をいただきましたが、再度ここで要望とともに、質問をします。","respondent":"松代道路公園課長、岩田管理工事課長","answer":"そういったときに極力予定がないところの企業でも、工事をし終わった後、仮舗装をします。それを少しでも期間を短く、なるべく利用者にご不便をかけないように短縮を図ったり、いろいろと調整をしています。滝王子通りの避難道路の機能強化の検討経費ですけれども、将来的にはその南に計画されております補助３１号線が完成した場合には。","id":"exchange-103"},{"speaker":"中島委員","kind":"質問・要望","question":"温かいご配慮をされているということで、今お伺いしました。もう一度これは要望しておきたいと思いますので、最後に要望して、これを終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問・要望","question":"都市開発費でしょうか、武蔵小山駅東地区まちづくりの予算がどこに入っているのか教えていただきたいのと、この点で伺います。都心共同住宅のところは、この事業の総事業費と、補助金額、補助率、そして今後この事業がどのように進んでいくのか、お教え下さい。","respondent":"浜脇住環境整備課長、上野都市開発課長","answer":"都市計画的なこと、あるいは近隣との説明会等々がまだ終わってございませんので、最終的な図面がまだでき上がってございません。１０月ごろ解体をしてやると、補助金の額というのは、ここでは現在把握していないという状況です。 都市開発費と武蔵小山駅東地区の予算がどこに計上されているかですが、２８１ページ、２８３ページには該当はございません。２８５ページの事務用経費の中に、地元協議会のまちづくり補助金を１０万円計上しています。","id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問","question":"都心共同住宅のところは、まだ現在総体を把握していないということですけれども、現段階で推測して入っている金額なんですか。この五千某が何にあたるのかなというところをひとつ教えて下さい。","respondent":"浜脇住環境整備課長","answer":"一部もしかすると着手するかもしれないというので、共同施設整備費が入れてあります。先ほど言ったように、額が決まった後で、３月３１日にこれだけできますよと言ったときにお支払いをするという仕組みになってあります。","id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問","question":"基本的なことをお伺いしたいんですが、今回の都市計画３.１haの範囲の地権者の数と、３.１haでの同意率を教えて下さい。２点目は、整備地区計画にかかっている０.８haの部分の地権者数と、借家、借間人の方の世帯数と、ここの同意率をもう一度教えて下さい。","respondent":"上野都市開発課長、浜脇住環境整備課長","answer":"その方々の同意率が今のところ約８割となっています。世帯数につきましては、地区全体といたしまして９.１haにつきまして約五百数十世帯です。 私どものほうにきています都心共同住宅供給事業の権利者数は３９名でございまして、アパートの数が６１、店舗数は１５というふうに聞いてあります。なお、同意率につきましては、１００％同意しているというふうに聞いてあります。","id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問","question":"地区計画がかかった３.１ha全域に対して、今回都市計画にかかっている素案をもとにきちんと説明をされているかどうかを知りたいんです。この間１２月と１月に素案ができてからの説明会を２回していますけれども、ここに関して何割ぐらいの方が参加しているのかをお聞かせ下さい。","respondent":"上野都市開発課長","answer":"今回の都市計画につきましては、主に昨年１１月、１２月以降地元協議会におきまして精力的に合意形成を進めてきているところです。その合意形成の過程で都市計画素案を添付してこの整備計画区域内の地権者の方の同意を取得しているというふうに聞いてあります。","id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何とか同意をしてほしい」と、６０ｍ、ショックを受けたという話を何件からか聞いているんです。私はぜひ話し合いをこれからもきちんと指導していただきたいと思うんですが、この点いかがか尋ねました。","respondent":"上野都市開発課長","answer":"計画の内容につきましては、都市計画に先立ちます街並み再生方針の地区の指定のときから区も含めて地元に将来像のご説明を含めてしています。地元協議会におきまして、将来のまちづくりについての内容を示しながら、合意形成を進めてきたです。","id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういうところでは、凄く行き違いがあるし、１００％同意ですよというところで、そうですかとは、とても受け止められないなと思うのが１点です。こういったまちづくりに対して、区はどう考えているのか、この２点をお答えほしいと求めました。","respondent":"浜脇住環境整備課長、上野都市開発課長","answer":"これは一般質問でもあったとおり、私どもはそのことに対して支援をしていくというのは当然だろうというふうに考えているところです。それから、この辺については当然私どもに申請がある前にそういうことは整理して… 返送用封筒にて、各権利者の方々から同意書を署名捺印の上返送をしていただいているという状況でございまして、その結果が先ほど申し上げたような同意率というふうになってあります。","id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問・要望","question":"合意形成に関してはすべて郵送で取扱っているということですか。私は、都民というところは、広くそこに生活をする人、営業をする人すべてが含まれると思うんですが、その点はいかがか尋ねました。","respondent":"上野都市開発課長","answer":"それに基づき調査、検討を進め、今の都市計画の段階に至っているものです。その中で住民の方々の主体的な取り組みによってここまで進んできたというふうに理解しています。","id":"exchange-111"},{"speaker":"飯沼委員","kind":"意見","question":"今開発の話が進んでいる、１９階建て、Ｄ地区はまさに目の前です」この話を聞いたのは、幼稚園に通っている子どものお母さんです。どうして１９階建てなんて、区はどう捉えていらっしゃるか、お聞かせ下さいとの意見を述べました。","respondent":"上野都市開発課長","answer":"まちづくりを進めるにあたりましては、さまざまなご意見があろうかと思いますが、先ほどもございましたように、地元の方々の主体的な取り組みに基づいてこのまちづくりは進めてきているところですし、今回の都市計画法の手続きに基づいて粛々と手続きを進めているところです。","id":"exchange-112"},{"speaker":"須貝委員","kind":"質問","question":"街路灯についてちょっと質問なんですけれども、大概室内は、ビルなどは電源が落ちても非常灯がつきますよね。その辺街路灯は電源が全部東京電力から送られなかったら全く機能しないんでしょうか、その辺お聞かせ下さい。","respondent":"松代道路公園課長","answer":"基本的には東京電力からの送電が止まれば消えてしまいますけれども、一部ハイブリットもしくは、そういったときの防災用の照明というものを、これはまた公園のほうの設置段階ですけれども、そういったものを今設置しつつある状況にあります。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問","question":"そういうのを、例えば街路灯に１００ｍ間隔でもいいし、３００ｍ間隔でもいいんですけれども、そういうのは設置できないんでしょうか、それだけちょっとお答え下さい。","respondent":"岩田管理工事課長","answer":"先ほど道路公園課長がお答えしましたけれども、街路灯は大体２００Ｗから１５０Ｗの電球を使いますので、いわゆる可動式のものではないんですね。原則として、１系統が遮断されても、基本的には停電にはならないという形をとっております。","id":"exchange-114"},{"speaker":"須貝委員","kind":"質問・要望","question":"ところどころそういうふうに、電源がおりたら自動的につくようなシステムをつくれるといいなと、要望します。外はお子さん連れ、またご年配の方が歩いているんですけれども、なぜ数十ｍにわたって両側は低いのか、その辺をお答え下さい。","respondent":"松代道路公園課長","answer":"私どもあそこを昨年の４月にオープンして、広くご利用いただいております。今委員のご指摘のとおり、横方向の部分は３ｍぐらいの低いフェンスですので、そのように確認しています。","id":"exchange-115"},{"speaker":"須貝委員","kind":"質問・要望","question":"次に、しながわ水族館、今回リニューアルで７億３,８００万円の費用を使うわけですけれども、これは水族館のみでしょうか。周りの植栽を含めて、リニューアルというか、替えるような方向性はあるんか尋ねました。","respondent":"松代道路公園課長","answer":"そういう中で、ご覧いただければ分かると思うんですけれども、あそこは非常に植栽が多うあります。海の周りの松の手入れとか、ほかの施設は計画的に改修等をやりながら、いい形でご利用いただけるようにしています。","id":"exchange-116"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこはもちろん歩かれては困るんでしょうけれども、ちょっとそういうことも要望をします。せいぜいずれても１ｍぐらい、ですから、結局どんなところでも、どんな乗用車でも何でも死角というのは出ます。","respondent":"山口交通安全担当課長","answer":"取り締まり、交通整理等を含めて、今後とも継続して対応していきたいと考えています。この場で５ｍまで下げても構いませんとは、なかなか即答はできませんので、警察を通じて可能なのかどうか確認をしたいと思います。","id":"exchange-117"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、２６７ページの都市計画道路に関連しましてお伺いをしたいと思います。それぞれの路線が早期完成をしていただくことを願う次第ですが、そういう立場に立ちながら、幾つかお伺いをしてまいりたいと思います。","respondent":"藤田都市計画課長","answer":"現在３件まだ用地のほうが残っているというふうに聞いてありますけれども、今手続きを進めているというふうに聞いてあります。現在、平成１７年度には詳細の設計を行い、外築の築造のほうに入っていくというふうに聞いてあります。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"放射２号線にも、それらとの両者の兼ね合いというんでしょうか、どちらを優先するのかと。計画線を引くにあたって、こういったものを避けることができないのかどうかも含めて、それらに対する考え方をお聞かせほしいと求めました。","respondent":"藤田都市計画課長","answer":"補助２６号線の関係ですけれども、こちらにつきましては、当面の間児童遊園として使うということで設置されているものです。両者、広い観点の中ですみ分けをしながら、まちづくりを進めていくべきというふうに考えてあります。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"その場所を使うべきなのか、結果が出たのか確認をしないので申し訳ございませんが、どちらを優先するのか。私権を制限すべきなのか、私はそこまではすべきでないと思っているんですが、公共の福祉を増進させる上での考え方をお聞かせほしいと求めました。","respondent":"中谷まちづくり事業部長","answer":"戦後の民主主義社会におきましては、各公共事業者同士で話し合いを行い、都市計画をかけているです。こういうふうに融合を図りながら、両方の話し合いによりまして、それぞれすみ分けをしながら進んでいる事例もあります。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"神明児童遊園方式というんでしょうか、これは線ですから、タコ公園のような児童遊園を早い段階から整備していくということが考えられないのかなと。これは平成６年にできたというふうに書いてございましたが、東京都からもらうのではなくて、その辺の考え方をお聞かせほしいと求めました。","respondent":"中谷まちづくり事業部長","answer":"まちづくりを進めるためには都市計画決定を行い、事業認可を取得した上で、事業を行うというのが正規の方式だと思います。これは補助２８号線の用地にかかるところですが、そして有効利用をしているという箇所もありますので、このように考えているところです。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう視点でぜひお願いをしたいと思います。今、東京都に対する主張の中の考え方としてそういう手法をとるお考えがあるかどうか、財政的な面からの視点をお聞かせほしいと求めました。","respondent":"市岡企画財政課長","answer":"区が固定資産税や都市計画税、都市計画交付金の場合は直接は都市計画税になりますけれども、固有の税として充てていくべき事業であります。","id":"exchange-122"},{"speaker":"藤田委員","kind":"質問","question":"先ほど来出ております２７９ページのしながわ水族館運営費に関する質問、その辺に関する質問、堤防についてお伺いをしたいと思います。新たに６億４,３００万円、総事業費が８億２,０００万円をかけてアザラシ館をつくっていくということですが、その辺をお伺いしたいと思います。","respondent":"松代道路公園課長","answer":"これは開館して１５周年ということで、平成１８年に合わせて今から計画を進めていくものです。もしくはファミリー層が来やすいという観点もありますので、そういった点は十分今後も引き続き継続していきたいと、このように考えているところです。","id":"exchange-123"},{"speaker":"藤田委員","kind":"質問","question":"ちょっと写真を撮ってきましたけれども、どうしてアザラシがよちよち歩きなのかということを全部説明しているんです。ですから、その辺の職員の皆さんとどういう話し合いがこれから行われようとしているのか、お伺いしたいと思います。","respondent":"松代道路公園課長","answer":"これは職員が日ごろから考えていた、その動物本来の特徴を飼育員の方がよくご存じで、それをなぜ見せないのかというようなことだったと思います。","id":"exchange-124"},{"speaker":"藤田委員","kind":"質問・要望","question":"水族館と区民の皆さんがつながるのではないかと私は思うので、これは時間の関係で、要望しておきます。こうしたコミュニティ道路というのを今考えていらっしゃるのか、それをお伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"旗の台地区で設置しました道路は、そこの中では通常道路管理者の許可にならないようなさまざまな対策を打っております。ですから、他の地区であの道路と同じような構造の道路をつくるというのは現段階では不可能です。","id":"exchange-125"},{"speaker":"藤田委員","kind":"質問・要望","question":"１００ｍおきにずっと道路に植え込みをつくっておりまして、スピードが出ないようにつくってあるんです。後ほど写真を見ていただきたいと思うんですけれども、お考えがあれば、お伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"さまざまな面で検討の素材にしますけれども、植え込みを道路の部分につくるというのは、旗の台地区でも今後やっていく予定にしている方向です。ですから、住民の方の利害調整がうまくいけば、さまざまな方法もとれると考えております。","id":"exchange-126"},{"speaker":"藤田委員","kind":"質問・要望","question":"ぜひ検討をしていただきたい。これを何とかまちの一つの景観上もっとグレードアップしてもいいんじゃないかなと思うんですが、いかがか尋ねました。","respondent":"松代道路公園課長","answer":"グレードアップというところでは、現在進めております目黒川でありますと、壁面緑化等をしておりますし、大崎地区では、道路と護岸の間に地域の方と花づくり、花壇等をつくりまして、歩く方、もしくは目黒川沿いに散策される方に潤いを持てるような形で今つくっているところです。","id":"exchange-127"},{"speaker":"藤田委員","kind":"質問・要望","question":"これはなかなかいいなというふうに感じてきましたので、ぜひそういう楽しい堤防づくりに取り組んでいただきたい。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"西本委員","kind":"確認","question":"午前中に藤原委員が質問をしました２６９ページの細街路拡幅整備事業について確認をします。そうすると、約１９％ぐらいの達成率という計算になると思うんですが、これは区としてどのような評価をされているのか尋ねました。","respondent":"片田建築課長","answer":"ただ、区としても何とかそれを法律の実効性を高めるということで、事業として助成をしてくるといったような考え方できているものです。","id":"exchange-129"},{"speaker":"西本委員","kind":"質問","question":"結局拡幅ですから、家を建て直すというところでは非常に時間がかかる事業ではあると思うんです。手法的にそういうものが利用できるのかどうか、早期に達成することができるのかどうか、その辺はいかがか尋ねました。","respondent":"片田建築課長","answer":"委員ご視察の中野区の事例等々については、防災生活圏とか、密集関係の中の一つの事業としてそういう整備をしてきているということで認識しています。","id":"exchange-130"},{"speaker":"西本委員","kind":"意見","question":"非常に長い計画ではあると思いますので、なるべく早く達成できるように今後もよろしくお願いしたいと思います。次に２７６ページの都市計画総務費ですが、どうして総務費という部分をつくってまとめられているのか、考え方をお知らせ下さいとの意見を述べました。","respondent":"市岡企画財政課長","answer":"今回幾つかの款で、その款の全体、あるいは項の総括的な目をつくっております。例えば景観ですとか、自主的なまちづくりの支援などというのはいろいろな事業に絡むけれども、自主的なまちづくりの支援をする総括的な経費ですので。","id":"exchange-131"},{"speaker":"西本委員","kind":"質問","question":"区民の自主的なまちづくりへの支援というのはここに入ってきているんですが、景観のほうは新しい事業として全体に係わるということは理解がある程度できるんですが、自主的なまちづくりへの支援というのがここに入ってきたというのは何か理由があるのか尋ねました。","respondent":"市岡企画財政課長","answer":"この自主的なまちづくりへの支援は、それぞれ区民の方が自主的な意欲で進めていく事業について支援をしていこうということですから、こういう総括的な予算科目のところにあったほうがいいだろうというような考え方です。","id":"exchange-132"},{"speaker":"西本委員","kind":"質問","question":"それとの関連性がどうなっていくのかな。どういう関連があって、そういう雰囲気もあるんですが、考え方はどういうふうに考えていけばいいのか尋ねました。","respondent":"市岡企画財政課長","answer":"それで、まちづくりの一番全体的なことについての項が都市計画費で、さらにその総まとめの目が都市計画総務費ということになります。いろいろな形態のまちづくりにも可能性のある支援の補助金ですので、こういう考え方ですので、よろしくお願いいたします。","id":"exchange-133"},{"speaker":"西本委員","kind":"質問","question":"それはどういうふうな絡みになっていくのか。地域住民たちの手によってまちづくりをつくっていきましょうというところの絡みがどうなっていくのかなというところはいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"一つのエッセンスが景観というような形で、モデル的な事業で次年度以降実施をしていこうというような観点から計上させていただいているものです。","id":"exchange-134"},{"speaker":"西本委員","kind":"質問","question":"可能性があるのかどうかをお聞きしたいんですが、モデル地区をつくって、今建築紛争とかが結構あると思うんです。この地域は商店街があって、それによって８階建てとか建たないように規制がかけられるものとしてできるのかどうかというところはいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"ただ、景観という観点で申しますと、皆さんいろいろな観点をお持ちの方がいらっしゃいます。その辺のことがありますので、まずは地域の方々で皆さんでどういったまちをつくりたいか、それを考えるのがまず第一歩だというふうに考えてあります。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"こういう景観法を使うことによって、ある程度の住民の合意は必要になりますけれども、それを規制することができるという大きなメリットがあるというふうに認識してよろしいということになるんか尋ねました。","respondent":"藤田都市計画課長","answer":"色ですとか、そういったものも皆さんで合意する中で、方向付けを示していくことはできます。そうした中で、何を皆さんがよろしい景観と考えるかといったところが一番ネックになってくるのかなというふうに考えてあります。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"私はちょっと確認だけをさせていただきたいんですが、それをどういうふうに今後変えられるのか、変えられないのか。は２６７ページに書いていないものも、その辺をまとめて簡単で結構ですので、お願いします。","respondent":"藤田都市計画課長","answer":"それ以降変更したものもありますけれども、基本的にはそのころに定められたものです。ネットワークといった観点から、それに基づいた、昨年３月にも優先整備路線をどこにするかといった形の発表をしたところです。","id":"exchange-137"},{"speaker":"西本委員","kind":"質問","question":"今６１％ということは、１００％になるためにはあと５０年、６０年かかるということになるわけですね。１０年後という形で毎年されていると思うんですが、例えば本当にこの道が必要なのかというところの議論はどの辺までいっているのか尋ねました。","respondent":"藤田都市計画課長","answer":"その中で、今回の見直しの中では、本当に都市計画道路として必要なのかどうかといった観点も含めながら検討をしています。大きな道路ネットワークといった観点では、平成３７年に概ね完成をさせたいといった観点から、今回の整備路線の考え方が示されたものです。","id":"exchange-138"},{"speaker":"西本委員","kind":"意見","question":"これも私たちは生きていないぐらいのときまでかかってしまうと思うんですが、ただ、地域住民の方たちに非常に影響のあるものですので、ぜひ時代に合わせた見直しをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"石田委員","kind":"質問・要望","question":"私は、２６１ページ、駅周辺等放置自転車対策と、先ほどちょっと話があったので、中高層の建築の開発指導の話の確認をしたいと思います。やっていかないのかわからないけれども、そんなような発言があったので、もう一回説明をしてほしいと求めました。","respondent":"浜脇住環境整備課長","answer":"既存の建物があった場合には解体の説明を義務付けたらどうかということで、内部で検討しておりますと、こういうことです。","id":"exchange-140"},{"speaker":"石田委員","kind":"意見","question":"建物のないところに中高層をやろうといったって、これは簡単に言えば、それの搬入、搬出、期間、こんなものしか言えないと思うんです。それが実効性があるかというと、私はあまりないところにそれを言うのもどうかと思うんだけれども、そこら辺の考えを聞かせて下さいとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"今委員がおっしゃったように、私どもは既存の建物の解体という意識があります。検討はしていますけれども、この跡に中高層の建物が建つならば説明をしていただこうと、では本当に一々それを説明をするのかとなると。","id":"exchange-141"},{"speaker":"石田委員","kind":"質問・要望","question":"そういう要望だけをしておきます。非常に難しかったんだろうと思うけれども、そこら辺の難しかった理由とかありましたら、お願いします。","respondent":"山口交通安全担当課長","answer":"法律的には自転車も駐車違反として車両ですから、交通切符で対応できるわけですが、現実には対応をしていないという現状です。現場の対応は、１人だけが取り締まっていると、あれもあれもと始まってしまうんですね。","id":"exchange-142"},{"speaker":"石田委員","kind":"確認","question":"これでいいのかどうかという確認と、今私が思っているのは、その際の負担金ということは、これは返還する人ですね。そこら辺の、登録証の部分と、その部分をお伺いをします。","respondent":"山口交通安全担当課長、中谷まちづくり事業部長","answer":"返還率が今のところ５４.１％ぐらいです。防犯登録をする場合は車体番号も一対になっておりますので、その特定をする場合は車体番号を追及すれば出てくるという形になっております。防犯登録の件ですが、昭和５６年に改正自転車法が施行された際に、施行される前の論議の中でも、かつての自治省の中でもこれは随分論議されました。","id":"exchange-143"},{"speaker":"石田委員","kind":"質問・要望","question":"品川区はそういう政策を打っているんですよ、その部分を逆にお金を取りますよ、取ったっていいじゃないですか。犯罪の部分にもう一回手を入れるとか、そういう部分の検討というのはぜひしていただきたいと思うので、もう一回考えがあればお聞きしたいと思います。","respondent":"中谷まちづくり事業部長","answer":"広域的な対応をしませんと、全く実効性が上がらないということになって、品川区の営業活動に支障が出るというおそれも出てきます。鉄道事業者の付置義務のほうがもっと自治体としては重要な問題ですから、そういう問題も含めまして、今後とも検討をしてまいります。","id":"exchange-144"},{"speaker":"沢田委員","kind":"意見","question":"２７６ページの都市計画費に関連しまして、中央環状品川線の現状についてお尋ねしたいと思います。その負担割合はどうなっているのか、住民合意はどこまで進んでいるのか、その３点についてまずお尋ねしますとの意見を述べました。","respondent":"藤田都市計画課長","answer":"そのときにも意見交換をしておりますけれども、今後も私どものほうとしては引き続き行われるのかなというような認識です。東京都のほうで２,０００億円負担をするといった形になってあります。","id":"exchange-145"},{"speaker":"沢田委員","kind":"意見","question":"なぜ都民の税金２,０００億円も投入することになったのか、東京都がその半分を出すというやり方にそもそも大きな問題がある。そこで、ちょっとお尋ねしたいんですが、どんな予測手法、シミュレーションをしたのか、その手法を聞きたいと思いますとの意見を述べました。","respondent":"藤田都市計画課長","answer":"条例の中で環境影響評価をするための技術的な指針が定められてあります。そうした中でそれらの基準に基づいて評価をしているというふうに聞いてあります。","id":"exchange-146"},{"speaker":"沢田委員","kind":"質問","question":"風速４.６ｍ、５０ｍ以上になると、下にべたっとくることがある。やっぱりこの問題の支援にならないんじゃないかというふうに思うんですが、区はアセスメントの問題についてどう思っていらっしゃるのか尋ねました。","respondent":"藤田都市計画課長","answer":"都市計画決定の手続きの中でも意見を申しています。東京都のほうでは一応十分だというような説明はされてありますけれども、区のほうといたしましては、これまで進めてきているところです。","id":"exchange-147"},{"speaker":"沢田委員","kind":"質問","question":"私は訂正してほしいと思うんです。改めてアセスメントには問題がある、そこを突き詰めたいという立場をとってほしいと思うんですが、いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"アセスメントの手続きを進めていく中では、事業者が自ら行って、事業者が判断して皆さんの前にご提示をしているだけではございません。私どものほうとしては、さらにもう一歩進めた環境対策をぜひとも東京都のほうに行ってほしいといった要望をしているものです。","id":"exchange-148"},{"speaker":"沢田委員","kind":"質問・要望","question":"そういう追加の要望をするというのは、アセスメントは平成２６年になれば、１１町会の皆さんは納得していないんですよ。はっきり説得力のある資料を出してほしいと、そういう立場を改めて東京都に働きかけてほしいと思いますし、お答え願ればありがたいと思います。","respondent":"金井環境課長","answer":"影響を及ぼすおそれのある事業を実施するときに、予測、評価を行う。あるいは環境大臣の意見等も踏まえて実施をするということになっておりますので、この努力はやっていきたいというふうに思っております。","id":"exchange-149"},{"speaker":"沢田委員","kind":"質問","question":"それほどの人たちが不安を持っているんですから、答弁をしましたけれども、それを生かしてほしい。たくさんのアセスメントの結果に対して問題点があるということを主張し、ぜひ斟酌いただいて対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-150"},{"speaker":"三村委員","kind":"確認","question":"先ほど東京都のほうで行われた環境局での会議の話が出ておりましたけれども、そちらの議事録等はとられているのか、お聞きをしたいんです。その対応というか、意見を評価をする場があったかと思うんですけれども、そちらの会議の内容等を確認しているか尋ねました。","respondent":"金井環境課長","answer":"それは私どもも把握しております。そのほか東京都では環境審議会といった中でも審議をされております。","id":"exchange-151"},{"speaker":"三村委員","kind":"質問・要望","question":"ほかの区に比べて、今回のアセスメントというのはあまりにもひどい、ずさんなものだということが再三再四指摘されていたんですね。ちょっと確認をとって、その辺のところを把握してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-152"},{"speaker":"高星委員","kind":"質問・要望","question":"２７６ページになるんでしょうか、都市計画の関係になるんでしょうか、区民の自主的なまちづくりの関係だというふうに思います。でき上がるころの工程というのは一番最初に聞いておったんですけれども、それは現在どうなっているのか、ちょっとお聞かせほしいと求めました。","respondent":"山口交通安全担当課長、上野都市開発課長","answer":"防犯登録の関係ですが、現在警察署の防犯登録については１０年間保存ということになっております。１０年間という、若干の余裕をもって１０年以上１１年とか、そういう中で資料があれば照会できるような形になります。 東急電鉄、ＪＲ線それぞれの交通機関が入ってございまして、今事業者の間でその調整をやっているところです。その辺の詳細もかなり時間がかかるというふうに聞いてありますので、その辺の調整を今じっくりやっているです。","id":"exchange-153"},{"speaker":"高星委員","kind":"質問・要望","question":"そういうことがありますものですから、しかるべき区政協力委員会も含めて、この辺のところの考え方をもう一度お聞かせほしいと求めました。どのような団体から、どのような要望があるのか、具体的に聞かせていただければありがたいと思います。","respondent":"山口交通安全担当課長、上野都市開発課長","answer":"撤去の葉書による通知ですが、可能な限り所有者に連絡をするように葉書による通知は現在も実施しております。できる限り交通配置等にご協力をいただけるように、可能かどうか警察署と相談しながら実施していきたいと思いますので… 大きく２点、特に浅草線に関しまして、もっと駅に近いところにエレベーター昇降口を設けてほしいというご要望が１点。五反田駅周辺の全体のまちづくりを考えて、バリアフリーを取り込んでもらいたい、そういう要望が出てあります。","id":"exchange-154"},{"speaker":"高星委員","kind":"質問","question":"３年間過ぎたものについては、葉書も出していないんじゃないかなというふうに思っちゃったものですから、申し訳ないなというふうに思います。あそこは大崎第１地区ですから、３１町会ほか地元の商店街の方々とか、代表者の名前がみんな載っている。","respondent":"浜脇住環境整備課長、岩野まちづくり事業部次長","answer":"一部の方が相談には来ましたけれども、まちづくりの派遣はまだ行ってございません。 若干今の答弁に補足をします。これからの将来のまちづくり、皆さんが考えることがあれば、その手助けができるものがあればということでもって私どもは考えてあります。","id":"exchange-155"},{"speaker":"高星委員","kind":"質問・要望","question":"いずれにしても、地元住民の要望の強いエレベーターですので、できるだけ親切丁寧にクリアしていっていただきたい。お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-156"},{"speaker":"堺委員","kind":"質問・要望","question":"２点目が、本来は２４３ページの４款の衛生費でお尋ねすべきかと思いますが、大崎短絡線との関連についてお尋ねをしたいと思います。最近踏切のそばに、３月２９日から４月１日にかけて線路工事を行う、この工事の内容について聞いておられればお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"踏切内に段差ができているということで、つまづいたりしやすいということで、以前から委員からご指摘をいただいておりました。区からＪＲのほうに改善方要請をしてまいりましたところ、今般３月２９日と３１日の深夜にすりつけ工事を行うということになりました。","id":"exchange-157"},{"speaker":"堺委員","kind":"質問","question":"ようやく我々の願いが聞き届けられて改善されると、このように理解をしてよろしいんでしょうか。あそこの舗装材の木の踏切ですか、そこはやったけれども、その前後の道路の段差の部分は未改修でそのままになっていた。","respondent":"岩田管理工事課長","answer":"そのとおりです。","id":"exchange-158"},{"speaker":"堺委員","kind":"質問・要望","question":"２点目に移ります。これは今回６００万円計上させれておりますけれども、この事業の目的、事業の内容についてお聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"特にアスファルトは夏場の一番暑いときには４０度を超えるような暑さになりますので、そういう面で温度を低下させる方法をいろいろ研究してみたいと。","id":"exchange-159"},{"speaker":"堺委員","kind":"質問","question":"今お答えがなかったんですが、調査検討をする場所が明示されておりますね、案として出ておりますが、どこか尋ねました。","respondent":"岩田管理工事課長","answer":"プレス発表の時期に戸越の今年度早期発注で発注する工事箇所を考えておりましたけれども、今場所を変更して考えております。１日中朝から晩まで日があたるところで、障害物がないところで、一番実験に適当なところということで、今変更場所を検討しています。","id":"exchange-160"},{"speaker":"堺委員","kind":"質問・要望","question":"２１番先、２路線、ちょうど大原小学校をはさんでいる。ちょうどいい場所ですから、ぜひ検討をしてほしいと求めましたが、いかがでございましょうか。","respondent":"岩田管理工事課長","answer":"ご趣旨は十分理解できますので、ただ今回は試験舗装ということでやりますので、規模的には小規模です。この成果をもちまして、その折には近隣の学校や、そういった教育活動にも使えるような形でやってまいりたいと思います。","id":"exchange-161"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひこの未整備区間の拡幅のときには、いつごろこの未整備区間については着手するんですか、このことを前回お尋ねをさせていただきました。そのときに一本橋通りのほうが目処がついた段階で進めていきたい、このようなご答弁を当時いただいているんですが、それは変わりないのかどうか。","respondent":"藤田都市計画課長","answer":"この優先整備路線につきましては、平成２７年までに整備または整備に着手をするといった路線になってあります。延長１km強ありますけれども、委員お話のとおり、その辺の進捗を見極めながら事業化について考えていきたいというふうに思っております。","id":"exchange-162"},{"speaker":"堺委員","kind":"質問・要望","question":"前後だけされているから、未整備区間についてはいつごろどう始まるか全く今はわからないんですよというふうに理解しなさいということですか。したがって、私は理解をしたいと思うんですが、その辺のところをもう一回教えてほしいと求めました。","respondent":"藤田都市計画課長","answer":"現在、事業認可を取得して事業を進めてありますので、同じ路線の中で２カ所の事業の進捗が終わりが見える段階でないと事業認可の取得ができませんので、そういった中でその辺の進捗を見る形での事業の進め方をしていきたいというふうに考えてあります。","id":"exchange-163"},{"speaker":"堺委員","kind":"意見","question":"整備はしないんですよということならそうかもしれませんが、補助１６３号線という一本化された中で、やっぱりこれは僕は整備が必要である。どうか適切な時期に予算計上をしていただいて、近隣住民の人は大変安心をするんですが、その辺はいかがでございましょうかとの意見を述べました。","respondent":"中谷まちづくり事業部長","answer":"補助１６３号線の一本橋区間の整備がある程度目途が立ったのが見えた段階で次の着手を検討するですが、この考え方には二つあると思います。これが区民の皆さんにとって喜ばれることなのか、また合意形成が図れるのかという観点から、今後検討をすることになろうかと存じます。","id":"exchange-164"},{"speaker":"堺委員","kind":"質問・要望","question":"従来より環境が悪化する、こういうことで反対しているというか、心配をしているというんでしょうかね。そのように十分住民に説明するように、行政のほうからも強くＪＲ側に要請をしていただきたいと思うんですが、この点についてはいかがか尋ねました。","respondent":"藤田都市計画課長","answer":"その中では計画の見直し等について検討をしてほしいというような話がございました。環境面でも最新の技術を駆使してほしいというお願いをしています。","id":"exchange-165"},{"speaker":"堺委員","kind":"質問","question":"今申し上げましたように、その辺ぜひひとつお願いします。もう１点、さっき申し上げた補助１６３号線と短絡線との絡みで、補助１６３号線に支障は出ないのかどうか、その辺いかがか尋ねました。","respondent":"藤田都市計画課長","answer":"現在高さの関係で若干影響があるかもしれないという話は聞いてあります。ただ、具体的な提示がないので、その辺については今後も協議をしていきたいというふうに考えてあります。","id":"exchange-166"},{"speaker":"原委員","kind":"質問・要望","question":"昨日ちょっとお話を伺いましたら、未契約が１２件残っているですので、今後の見通しについてはどうなっているのか。昨年だったと思うんですが、電線の地中化についてももうお話をされていたんですが、これは今回のこの予算とは全然関係ない話だったんか尋ねました。","respondent":"山口交通安全担当課長、藤田都市計画課長、岩田管理工事課長","answer":"なお、自転車の事故防止に関しては、警察署と今協議中ですが、免許証制度的なものを検討しています。今警察署のほうでＰＴＡとか… その見通しですけれども、現在交渉を鋭意続けているところで、一つの目処として平成１７年度ということで考えてあります。… その中で地元の滝王子通りに面した商店街から細かい内容を説明してほしいということで、参りまして、ご説明をさせていただきました。ただ… なお、先ほど予算の関係は特になしとお答えしましたが、ちょっと補足をします。","id":"exchange-167"},{"speaker":"原委員","kind":"質問・要望","question":"地元の要望等々もいろいろあるようですので、その辺も勘案しながらやっていただきたいんですが、実はここは森下町会なんですね。片方はシールドか何かで掘っていくんでしょうし、いろいろな形があると思うので、考えていらっしゃれば教えて下さい。","respondent":"山口交通安全担当課長、藤田都市計画課長、矢部下水道河川課長","answer":"４０％程度ですが、すべて軽傷となっております。負傷部位等については、細かくはとっておりませんが、都内の件数を見ると… 町会費の関係ですけれども、なかなか困難な問題かなというふうに考えてあります。事業が進んでいき、大変な効果が期待されると考えていますので… 現在なぎさ会館で掘さく工事をやっておりまして、今年の秋口からシールド工事を発進するというふうに聞いております。","id":"exchange-168"},{"speaker":"原委員","kind":"質問・要望","question":"１件や２件でないわけですから、今度調べていただきたいなと思うんですが、要望だけしておきます。最近補助２０５号線ができて、電柱と家の間の隙間が多いものですから、次につなげてほしいと求めました。","respondent":"山口交通安全担当課長","answer":"実は２月２５日、浜川幼稚園で保護者を含めた５０人程度のヘルメットの安全教室を実施したところです。５０名中３５名の回答がございまして、この中でちょっと気になる回答で、指導啓発のほうを重点にこれから推進していきたいと考えています。","id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/330368?Template=document&Id=848#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":124266,"voices":394}},{"id":"h17-20050316-3","meetingId":"h17-c-budget","date":"2005年3月16日","dateIso":"2005-03-16","committee":"予算特別委員会","time":"午前１０時０５分～午後６時０５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件整理しています。","topics":[{"id":"topic-01","title":"平成１７年度品川区一般会計予算","agenda":"平成１７年度品川区一般会計予算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私は２９７ページ、小中一貫校、時間があれば３１１ページの学校改築推進経費の２点、お伺いをします。教育的な背景、世の中の背景、ご説明をお願いします。","respondent":"中島指導課長","answer":"総合的な学習の時間、十分にその目的を果たしているかという点につきましては、こちらも課題を残しているところでございました。市民科は、これらの内容をより目的を達することができるようにするために、統合、発展させた教科として位置づけたものという形です。","id":"exchange-001"},{"speaker":"大沢委員","kind":"質問・要望","question":"背景としまして、子どもの学ぶ意欲の低下とか規範意識、公共心の低下、基本的生活習慣の乱れ等々が挙げられました。今私がお話しをいたしました公民的分野の公民、または倫理社会と違いがあろうかと思いますので、違いを教えてほしいと求めました。","respondent":"中島指導課長","answer":"主体的に取り組む中で、さまざまな活動を展開するところで主体性を育んでいく、社会性を育んでいくというようなねらいがあります。教科と領域とのねらいが、このような形で分離しています。","id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"学問というのは生活に結びついていなければいけない、それはもう言うまでもありませんし、皆さんも十分おわかりだと思います。今、子どもたちに市民科という学問を、子どもたちの勉強という範囲に占める位置を教える方策をお持ちであれば教えてほしいと求めました。","respondent":"中島指導課長","answer":"学んだことの活用実践、体験活動、日常的な活動の場というものを考えていく必要があるだろう。その中で、さまざまな資質を身につけていって、実践を日常的に行っていくと、こういったような体験的なプログラムを考えているところです。","id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"今、課長は市民性とおっしゃいましたが、市民という言葉は市民権とか市民性とか市民意識、また共同の社会性、そういう意味合いで市民というものをとらえてよろしいか尋ねました。","respondent":"中島指導課長","answer":"主体的に社会に係わることができるような力をもって、自らも社会的に有為な存在として意識しながら生きていこうとする、こういったような姿勢というふうにとらえてあります。","id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"次に、３１１ページの学校改築推進経費について、簡単にお尋ねをいたします。これに関して、現在までの進捗状況をお伺いいたします。","respondent":"市川庶務課長","answer":"昨年の７月から学校関係者、それから町会など地元関係者と検討会を組織いたしまして、これまで都合７回にわたって検討会を開催してまいりました。先般、学校関係者と地元関係者のご意見を伺って、現在基本設計をまとめる作業をしている状況です。","id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"まとめの作業にあたりまして、意見を集約するわけですけれども、そこの点で特に留意して作業をされることがありましたら、１点お伺いします。","respondent":"市川庶務課長","answer":"何と言いましても、できるだけ短い工期で新しい校舎を完成させる。このことに、最大限配慮を払ってまいりたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"ぜひ、いい改築ができますように、よろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"若林委員","kind":"提案","question":"確か提案があったと思いますけれども、８時から８時半、外に出て掃除をする。まず先生たち、この学力低下ということについて、どのようにお考えを持たれているかお聞かせ願いたいと思いますとの意見を述べました。","respondent":"中島指導課長","answer":"それから計算練習の時間をやっていくとか、そういったような取り組みを教員のほうで企画をして取り組んでいるというような状況はあります。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"同じく学力低下につきまして、保護者、また地域の方々の学力低下に対する思い、感想というのは、教育委員会としてはどのように把握されていますか尋ねました。","respondent":"中島指導課長","answer":"例えば小中一貫教育の説明会をしていく中では、保護者の方のご意見をいただくような場面などがあります。ただ、その中で本区ではご承知のように外部評価者制度も実施しておりますので、学力低下についての論議を学校ごとにしていくような状況はあります。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"もう１点、教えられる側の子どもたちはこういうことをどのように子どもたちは感じているのか、あったら教えてほしいと求めました。","respondent":"中島指導課長","answer":"例えば、保護者の方からは、８０％を超える方々に「そう思う」「強くそう思う」というような答えをいただいております。学校なり私どももそうですが、保護者や子どもとこういう情報の確認をしながら、実践をしていくということが重要なことと考えています。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問","question":"２００２年から現在の学習指導要領になりまして、当然いろんな大合唱というんでしょうかありました。こういう急激な転換に対して、品川区としては方向転換をしようという動きに対してどのような理解をされているんか尋ねました。","respondent":"中島指導課長","answer":"もともとプラン２１という施策を進める中で、個性伸長、こういったようなものを目指してきた経緯があります。これは今、基礎学力を定着させるために私どもが取り組んできた方向と決して異なるものではないと、このように考えております。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"これが社会に蔓延していると言われている無力感というものを、一つは象徴する言葉かなというふうに思っております。それから生きる力の低下、それが学力低下につながっているんだというような分析に対して、どのようなご感想をお持ちか尋ねました。","respondent":"中島指導課長","answer":"私どもで設けた９年生までが一連の流れの中で、こういった子どもたちの姿勢をつくっていく義務があるのではないかと考えております。先ほど来、議論になっております市民科などは、その具体的な場として考えているところです。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"ぜひプラン２１、小中一貫校に象徴されるような教育をぜひお願いしたいと思います。教えていこう、教育委員会また先生方につくっていただきたいなというのが、。","respondent":"中島指導課長","answer":"同じような質問をしても、子どもたちの考えは３５通りある。そういった中で、さまざまな指導形態を取り組む中で、一人ひとりを大切にした授業を目指してまいりたいと考えております。","id":"exchange-013"},{"speaker":"木下委員","kind":"質問","question":"３００ページの学校管理費、この３点について質問をさせていただければと考えています。今まで努力されてきた経緯ですとか、これからどういう形でやりたいのか、展望ですとかいろいろお聞かせ願えればと思います。","respondent":"中島指導課長","answer":"どのように子どもたちに課題認識を持たせて意欲的に授業に取り組ませるかという視点で、さまざまに取り組まれていたような状況がございました。","id":"exchange-014"},{"speaker":"木下委員","kind":"質問","question":"なぜかといいますと、集団生活に対応仕切れていないということで、問題を解決するために幼稚園からということを考えていらっしゃる。幼稚園、小中学校だけではなくて高校もあるわけですから、お聞かせ願えますか尋ねました。","respondent":"中島指導課長","answer":"は義務教育の小中一貫教育の実施、充実を図っていきたいと考えております。先ほど申し上げましたように、その中で幼稚園と高等学校のほうも、それぞれの課題の解決を目指して取り組んでいこうと考えているところです。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"私のほうから２９３ページの安全管理に関することかと思いますが、寝屋川での事件との関係でお聞きしていきたいなと思います。事件以後ですけれども、この辺を品川区ではどのような論議がされて対応していこうとしているのか、この辺をお聞かせ願えればと思います。","respondent":"中島指導課長","answer":"その中では、例えばまず教員が対応するにしましても、主事が対応するにしましても、単独での対応はしない。必ず複数で対応するようにしましょうですとか、玄関またはオーペンスペース等の広いところを活用して対応をするようにしよう。","id":"exchange-016"},{"speaker":"菊地委員","kind":"質問","question":"「犠牲者が出るまで警備員を置かないんですか」という発言をしていたというのが新聞に載っておりましたけれども、この直後の事件だそうです。今、区内の小中学校に何校ぐらい設置されているのか、そして今後の計画としてあるのかどうか説明を求めました。","respondent":"市川庶務課長","answer":"１６年度ですけれども、通用門への電気錠の設置を試験導入をして、既に数校で導入しています。その結果を受けて、来年度予算にまず全小学校に同種のものを導入するということで予算計上させていただいているところです。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"防犯カメラをつけても見る人がいません」と、こういうコメントがあるんですが、こういう状況下にあるということでしょうか。今、そういう状況下ではモニターをつけてもあまり意味をなさないというものになりますけれども、この辺の状況をお知らせください。","respondent":"市川庶務課長、中島指導課長","answer":"外来者が見えたときにはこういう対応をしましょうと、こういう対応が適切だというような現場の意見が上がってきて、それを実践しています。こういったことで、一定の効果が見込めるということで予算計上したものです。 ソフト面という形になっていきますけれども、すべての学校において、学校の防犯組織としての機能を高める実施訓練というものを実施しています。今後、学校を中心に、こういった態勢づくりを進めていきたいと考えているところです。","id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"それから、「トイレに行く時間もなく、こういう大変な状況の中で子どもたちを成長させることに取り組んでいるわけです。警備員の配置というのは最大限進めるべき内容ではないかというふうに思いますけれども、この点でもう一度お願いいたしますとの意見を述べました。","respondent":"中島指導課長、市川庶務課長","answer":"そういった場合の防犯訓練等を実施している状況です。こういった教員のその場の対応もそうですけれども、先ほどお話しいただいた１日の中で５時までトイレへ行かない。警備員の配置をというご質問ですけれども、今指導課長がるる申し上げたように、校内態勢の確立をやるべきことだと思ってあります。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"もう１点のほうですけれども、２月２３日の国会の委員会だそうですけれども、文部科学大臣がこういう答弁をしているんです。これに沿って、やっぱり子どもたちの安全管理を含めて、もう一度この点からも考えていくべきではないかというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは教育総務費と学校教育費の中から質問をさせてほしいと求めました。こういうときの改修というのは、例えば当年度でやるとすると、学校改修費の中で十分対応できるのかという点を、まず１点お聞きしたいと思います。","respondent":"谷田部学務課長","answer":"学校選択制の関係と、それからそのときどきの区域内の子どもの数によって、予定する学級数が不足するというような状況はあります。学級数が増える見込みが立った段階で、新年度の４月にあわせて改修をし、それからまた空調機を設置する準備をしているという状況です。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校の中で設備を整えてもらいたいという思いと、例えば給食室の上に追加すれば教室がつくれるのではないかという雰囲気のところも聞いています。今後、増えてくることによって、そういう対応は考えられるのかどうか、その辺もお答えをほしいと求めました。","respondent":"谷田部学務課長","answer":"それから希望する子どもの数との関係の中で、さまざまに検討させていただいて、何学級まで受け入れ可能だということを推計して出しています。戸越台中学校のように、かつて普通教室だったという想定ではつくってございませんので、許容量の中での受け入れを今後もしていくです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その辺で、できる限り要望にうまくこたえていただきたいなという思いで、この部分は終わります。小学校という考え方なのか、そこに私立幼稚園も入っているのかどうか、その辺をまずお聞きしたいと思います。","respondent":"中島指導課長","answer":"現在、検討会を進めてきているところですけれども、極力そろえることができるようにしたいというような強い願いを持っております。今、ご質問がございました私立保育園・幼稚園も全部含んだ形で考えていきたいと、このように考えております。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"やっぱりそれは区立幼稚園と小学校だったので、既に連絡が取られていたというお話を伺いました。現状のお話しを伺いましたけれども、これから課題としてどういうふうに考えていくのか、その辺がございましたら教えてほしいと求めました。","respondent":"中島指導課長","answer":"今後の課題といたしましては、全区的な連絡会の実施に向けて、一つは来年度の体制をつくっていくこと。教育要領に基づいて保育の内容等を実施しているわけですけれども、それと保育園等、また私学等で実施しております就学前の教育の内容。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２年生、３年生になったときに、子ども１人だと状況がつかめない。先ほど市民科の中に入れていくという部分、どのような考えか、もうちょっと細かく教えてほしいと求めました。","respondent":"中島指導課長","answer":"基本的には中学校２年、３年の段階における進路指導という形で、こういった形でやっているのが現状です。市民科におきましても、自分たちの将来をどのように考えるかという部分と、子どもたちの資質の育成に取り組んでいきたいなと考えているところです。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"校長先生ということではなくて、一般の先生方が品川区の学校を定年になって卒業した後、どういう形で現状お勤めになっていらっしゃるのか。職員だと６５歳まで再任用という制度がある中で、先生方はどのように対応なさっている方が多いのか、その辺を説明を求めました。","respondent":"中島指導課長","answer":"５名以内だったのではないかなと、年度によって違いますが、１名とか２名の年度もあります。それから図書館で業務に就くですとか、コンピューター室で指導にあたるとか、そういったような役割をいただいている状況はあります。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"学校の先生ではなくて塾へ行ってしまったほうが、東京都の職員から外れても、そういう方もいるという話を伺っております。学校の先生はすぐに見つけられているのかどうか、そういう指導をしていらっしゃるのかということをお聞きしたいと思います。","respondent":"中島指導課長","answer":"体育ですとか、夏のプールですとか、そういったところでわかる場合もありますし、健診といった場面もあります。の連絡を取って、そういった状況を教師が直接確認できるような体制を取るよう指導しています。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"万が一のようなことがないように、ぜひその辺のチェック体制をこれからも強めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"私は３０７ページの給食調理業務代行委託と２９７ページの教職員証作成についてお伺いします。給食調理代行についてお伺いしますが、どういう評価をしたのか、それとこの３校を新たに始める目的を説明を求めました。","respondent":"谷田部学務課長","answer":"区の公務員の８時間勤務の職員をそこに張り付けているという状況がございまして、ある面では労働集約型の業務だというふうに思ってあります。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"課長のご答弁を伺っていますと、財政的にもよくて、質の向上にもなる、いいところばかりだと思うんですが、実はそう答弁されていても、怖い食材の大量購入、献立の簡素化になって、給食内容の低下が実は心配されるのではないか尋ねました。","respondent":"谷田部学務課長","answer":"調理作業を行う区の職員から民間の調理代行会社にかわるだけと、いわゆるつくり手がかわるだけというようなご説明をこの間しています。そういう面を考えた食材を購入いたしますので、従来どおり献立、食材については学校のほうで行うです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"では、法的に区の栄養職員が一般社員に指導はできないというふうに、私はある新聞に入っていたチラシを見て今質問をしているんですが、できないんか尋ねました。","respondent":"谷田部学務課長","answer":"学校と調理代行の職員との間に雇用関係はありませんので、直接指示はできないだろうというような主張をするという方がいらっしゃいます。ですから、全く指示ができないというのは、ちょっと私どもは観点が違うというふうに思ってあります。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"答弁を伺いまして、逆にこのチラシ自体が法的に問題がありますよね。行政として、このチラシに対してどのような措置を取っていくのか尋ねました。","respondent":"谷田部学務課長","answer":"もう既に、今年度も残すところ２週間でございまして、４月１日には調理代行が始まります。始まった後、また各学校では試食会を考えているですので、それはそれで調理代行を導入する目的は達せられたというふうに思ってあります。","id":"exchange-032"},{"speaker":"築舘委員","kind":"質問","question":"情報化時代でもありますし、私なんかは５０代を少し出ていまして、なかなか時代についていけるかどうかという悩みを持っているところであります。それからインターネット活用教育推進事業の現状と、特に力を入れるということがあるのかどうか、そこを説明を求めました。","respondent":"中島指導課長","answer":"小中一貫教育の中での英語科という位置づけになってまいりますので、すべての学校で小学校１年生から取り組んでいくという想定を考えてあります。平成１８年４月から、その移行に取りかかっていく予定です。","id":"exchange-033"},{"speaker":"築舘委員","kind":"質問","question":"私はインターネットができないほうですから、どんな情報が入っているかさっぱりわからない。その点、やはり学校できちんと教えていくところは必要じゃないかと思うんですが、そこの点の学校教育でのインターネットを説明を求めました。","respondent":"中島指導課長","answer":"こういった情報教育に係わるインターネットを利用する際でのさまざまな事例、対処法といった形での研修会を実施してきてあります。より教員のコンピューターの活用なり、こういった情報ツールの活用という意識を高めながら、質を高めていきたいと考えているところです。","id":"exchange-034"},{"speaker":"築舘委員","kind":"意見","question":"その辺、しっかりとお願いしたいと思います。かなり効率をよくしていこうということと、サービス向上を徹底させようということだと思うんですが、今の現状を説明を求めました。","respondent":"古里品川図書館長","answer":"今年度４館モデル的に実施いたしまして、所定の目的を達した業務委託の形態が実現できるというふうに判断をいたしまして、今年度残りの６館の民間委託をすべて行っていくということにしています。","id":"exchange-035"},{"speaker":"築舘委員","kind":"意見","question":"民間の会社がしっかりやっていただくようなことも頭に入れてお願いしたいということとそれから、いろんな情報がやり取りできるということですけれども、その辺はどういうふうに活用していくのか説明を求めました。","respondent":"古里品川図書館長","answer":"私どもが運用しています公共図書館用のコンピューターシステムが相互に連携して動けるような開発をしていく予定です。そういう意味では、区立図書館と学校図書館の双方の資源が、子どもたちのために十分役立てられるようなシステムということで考えてあります。","id":"exchange-036"},{"speaker":"築舘委員","kind":"意見","question":"これは読む機会が増えるということと、関心が増えるということだと思います。若い人たちが本を借りるということに関しての数が相当増えているのか、それから影響というのがどういうふうに出ているかというのを聞かせてくださいとの意見を述べました。","respondent":"古里品川図書館長","answer":"あるいは視聴覚資料を提供したりしながら、図書館へ足を向けさせるという努力はしていますけれども、なかなかこの辺が効果が上がってまいりません。","id":"exchange-037"},{"speaker":"武内委員","kind":"質問","question":"私は４点、同じく２９５ページの子どもへの暴力防止対策（ＣＡＰ）事業、３０１ページの学校環境整備事業をお願いしたいと思います。２９３ページの学校職員被服貸与費ですけれども、また何人分ぐらい貸与されていて、１着どれぐらいの金額なのか説明を求めました。","respondent":"市川庶務課長","answer":"用務の職員が１年を通して行うさまざまな職務に対応したいわゆる業務服に始まりまして、長靴、防寒用上着等々です。冒頭申し上げました用務職についてはおよそ１万５,０００円程度、給食調理の職員についてはおよそ２万円程度、そのような経費の額となっています。","id":"exchange-038"},{"speaker":"武内委員","kind":"質問","question":"実際には１年間使われるのかどうかわからないんですが、毎年貸与という形で予算が盛り込まれているのか、何年ぐらいで変わるのか。実際に着てしまいますと、汚れてきたときには返却という形にならないかと思うんですけれども、その辺のところも説明を求めました。","respondent":"市川庶務課長","answer":"種別によって多少の違いはありますけれども、基本的には３年に一度の貸与期間ということで設定しています。やむを得ず棄損等をした場合には、随時の対応をしています。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問・要望","question":"スクールカウンセラーを１校新たに追加されて費用だというふうに伺いまして、私ども党として何回となくスクールカウンセラーを要望してまいりました。私も昨年の第２回定例会の一般質問で、小学校への適切な配置ということで要望してまいりましたので、この辺の経緯を説明を求めました。","respondent":"中島指導課長","answer":"この中で、周辺の小学校にも行きまして取り組んでいるといったような状況の中で、２人目といたしまして大井地区にということで考えました。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問","question":"そうすると、大井第一小学校を中心に、ある程度大井地区の中学校を担当されるというか、そういう認識でいいのかどうか。これで荏原地区と大井地区に１校ずつ配置されましたけれども、予定というか、その辺がありましたら説明を求めました。","respondent":"中島指導課長","answer":"は大崎地区、あとはマイスクールにも１人臨床心理士がおりますので、バランスを取りながら大井地区に設置させていただきました。今年度の実施状況、またさまざまなニーズ等を踏まえて、検討していきたいなと考えております。","id":"exchange-041"},{"speaker":"武内委員","kind":"確認","question":"できればそういった状況を踏まえながら、来年度以降、スクールカウンセラーを増員していただければいいなというふうに思っております。その辺の確認と、なぜ小学校３年生なのか、その辺の理由を説明を求めました。","respondent":"中島指導課長","answer":"私どもでは、来年度は、このＣＡＰをすべての小学校の３年生に実施していきたいと考えています。最終的には、３年生での実施という体制を組んでいきたいと考えているところです。","id":"exchange-042"},{"speaker":"武内委員","kind":"質問","question":"１年生、２年生だとまだ理解というか、そういうことがあるのかどうかということ。非常に専門的なプログラムだということで、どういった方がやられるのかということと、そのグループにされた理由がありましたらお教えください。","respondent":"中島指導課長","answer":"それから、このプログラムの実施にあたりましては、現在ＮＰＯ法人がさまざまな形で提供しているという現状があります。ＮＰＯとの連携の中で、ともに子どもたちの指導にあたるという体制を、来年度組んでまいりたいと考えております。","id":"exchange-043"},{"speaker":"武内委員","kind":"質問・要望","question":"これは子どもの実施の前にやって、しっかりその後のフォローもするということだと思うんですけれども、その辺のところの状況を教えていただきたい。それから、不登校とか非行の対策になるのではないかというふうに認識しているんですが、その辺の見通しとあわせて説明を求めました。","respondent":"上川内生涯学習課長、中島指導課長","answer":"保護者に対するＣＡＰの取り組みですが、ＰＴＡの活動支援事業の中で、家庭教育の委託学級という形で保護者の方にＣＡＰの体験をしていただきます。これは全校、小学校の全ＰＴＡ４０校に家庭教育委託学級ということで… それから、これが児童虐待等への対応の一助になるのではないかというご指摘ですけれども、その要素はかなりあるのではないかと思います。","id":"exchange-044"},{"speaker":"武内委員","kind":"意見","question":"一応２４校分と聞いているんですが、先ほどのご答弁で、そうすると今の段階で小学校１６校はついているという認識でいいのかどうか。","respondent":"市川庶務課長、中島指導課長","answer":"現状は既に設置してある学校、それからこれから近時に改築する学校、それらを含めて１５校とカウントしています。残りの２５校について、来年度予算計上させていただきました。そこでモニターがありまして、声のやり取りと学校内部からその状況を見ることができるという形になります。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"テレビ局のアナウンサーの方が合格者に対して「今、一番何をやりたいですか」と次々に質問するんです。質問したいのは、こういう中学３年生の率直な思いに対して、大きな質問になりますけれども教えてほしいと求めました。","respondent":"中島指導課長","answer":"小中一貫教育を進める本区では、社会性の育成、この二つを大きな柱として取り組んでいきたい。１年生から９年生までの一貫の中で、人間性の育成に関しては、このように思っているところです。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"私もテレビの番組を見ていまして、何のために勉強しているのかわからない、学んだことが社会とどう係わっているのかわからない。なぜカリキュラムの前倒し、学ぶことが面白いと思える学校になるのかどうか、もう一度説明をほしいと求めました。","respondent":"中島指導課長","answer":"それぞれの考え方なりコンセプトを持って、それをすべて今この時間で説明すると、そういうわけにもまいりません。これまでもご説明しておりますけれども、そういったものをねらいとして、ここのところで時数増を図っている部分があります。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問","question":"その結果、授業時間も当然増えるわけですから、小学校５年生から７時間目授業が始まるんですね。７時間目授業を行うためどうするかと、僕も見て驚いたんですけれども、昼休みの２０分間を掃除の時間に充てる。","respondent":"中島指導課長","answer":"まず、国語の教科書で扱っていない漢字については、小中一貫教育の中でも扱ってはおりません。７時間目の部分につきましては、４５分の授業を１５分単位で組み直して、そういったような工夫を今後していくことを考えてあります。","id":"exchange-048"},{"speaker":"中塚委員","kind":"質問","question":"その３００字は、今の国語の教科書に入っているのかどうか伺いたいと思います。Ｉ二乗イコールマイナス１、これを中学校３年生に学ばせる教育的意義が一体どこにあるのかと思うんですけれども、いかがか尋ねました。","respondent":"中島指導課長","answer":"これを概念として、一律に子どもたちに教えることは考えてございません。子どもたちが意欲を持って、一斉にすべての子どもたちに指導することは考えてございませんので、ぜひご理解いただきたいと考えております。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"虚数の問題ですか、中途半端に中学校３年生に教えると、これが率直な現場の思いなんですね。一斉授業の中でやるわけですから、その学年になぜ必要なのかということが十分話し合われていないように、また発表もされていないと思います。","respondent":"中島指導課長","answer":"それから、漢字についてでありますけれども、１,９４５字の常用漢字がすべての教科書に、すべて同じように出てきているわけではありません。経済協力開発機構が行った２００３年の調査につきましては、記述式を中心に評価するものであると、このようにとらえてあります。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"ＯＥＣＤの東京センターが今年の１月２７日に講演会をやっておりますけれども、区教育委員会のどなたか参加されたのかどうか伺いたいと思います。品川区は、こういう教育を検証の対象にしないのでしょうか、説明を求めました。","respondent":"中島指導課長","answer":"それぞれの国のそれぞれの方針がある中で、日本はどうあるべきかということを、やはり考えていくのが重要ではないかなと、このように思っています。","id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのために毎週金曜日には時間割をつくらずに、１日中総合的な時間に充てていると伺いました。最後に質問したいのが、フィンランドの教育のモデルになったものは何だったのか、これを教えてほしいと求めました。","respondent":"中島指導課長","answer":"フィンランドの文献を幾つか読ませていただきましたが、それについては残念ながら私のほうでは存じあげてございません。","id":"exchange-052"},{"speaker":"中塚委員","kind":"意見","question":"フィンランドの教育の基礎をつくったのは日本の憲法であり、教育基本法であり、６０年代の日本の教育をフィンランドが基礎にして学んだそうです。私はＯＥＣＤ２００６年にまた行われますけれども、こうした結果を真摯に受けとめて研究をしていくべきではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"須藤委員","kind":"質問","question":"２９４ページの教育指導費に関連して、質問をします。将来に悲観的で自分の国に誇りが持てないというのが出されているんですが、こういうことに関して何かお考えがありましたら説明を求めました。","respondent":"中島指導課長","answer":"学ぶことは社会のために役に立つんだというような根本的な考え方を持てないということは、非常に憂うべきところではないかなと考えております。","id":"exchange-054"},{"speaker":"須藤委員","kind":"質問","question":"こういう社会の状況ですから。そういった中で、こういった今のまちの人に学ぶとか経済活動体験学習というのは、そういった意図があるかどうかお知らせください。","respondent":"中島指導課長","answer":"やはり考えて学んだこと、新たな課題を見つけていくという、こういうサイクルが非常に重要ではないか。そして社会性、人間性を高めていきたいと考えておりますので、この体験活動等の重要性は教育委員会も深く認識しています。","id":"exchange-055"},{"speaker":"須藤委員","kind":"質問","question":"というのは、今の少子化の中では、そうしたことがだんだん少ない状況になっている。ですから、いろんなことを教育委員会ではおやりになっていますけれども、今度は保育とか小さな子どもと接触する場面をつくることはいかがか尋ねました。","respondent":"中島指導課長","answer":"中学生の子どもたちが保育活動に参加して、そこで子どもたちと遊んだりお手伝いをしたりというような活動をいたしております。将来設計の部分で５・６・７年生を中心に、さまざまな将来に向けての学び、そして社会的な役割を認識させていこうというプログラムを考えてあります。","id":"exchange-056"},{"speaker":"須藤委員","kind":"質問","question":"そういうところに入っていく昔の時代と違った社会構成になっていますから、いいことをいい形で生かすような方策をぜひお願いしたいと思います。日本の子どもたちは和をもって尊しとすると、今の教育で正義というのはどういうことを日本の教育委員会では考えていらっしゃるのか尋ねました。","respondent":"中島指導課長","answer":"小学校１年生、２年生の段階では、その発達段階に応じた形で学んでいくプロセスが必要ではないかなと思います。世界に伸びていく子どもたちが、まずは日本の国の中で、社会における正義についてきちんと考えていけるようにしていくことが重要かなと考えています。","id":"exchange-057"},{"speaker":"須藤委員","kind":"質問・要望","question":"安全な社会、安全だというような。社会全体が非常に怠惰な状況になったり、嫉妬を求めたりというようなことになってくると思うんですけれども、その辺の考えはいかがか尋ねました。","respondent":"中島指導課長","answer":"子どもたちにとって勇気ある行動をスキルも含めて身につけて、実際に世の中でそれを役立てていくということは必要になってくる部分だろうと考えます。","id":"exchange-058"},{"speaker":"須藤委員","kind":"質問・要望","question":"子どもたちが変わっているのを現場で見ていますので、ぜひとも頑張って素晴らしい教育を続けていただきたいとお願いしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"井上委員","kind":"確認","question":"私からは１９２ページのすまいるスクールについて、３０１ページの心障学級経費、 ３０７ページの調理業務代行委託についてお伺いをいたします。ＣＡＰの質問がされましたけれども、決して先生が研修を受けてできるようなものではないと思うんですが、その辺を確認させてください。","respondent":"中島指導課長","answer":"教員もＣＡＰに対する研修が必要だということで、ＮＰＯの力を借りて教員対象の研修も実施いたします。教員の理解を深めた上で、ＣＡＰの方にお出でいただいて、そこで実施するです。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"先生が受けることは当然あってほしいことだと思いますけれども、そのようにしてほしいと求めました。今まで学童保育クラブに通っている養護学校の児童と私立・国立に通っている区内の児童は、その後どうなるのかということを確認させてください。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは平成１３年度から実施しておりますが、これまでは実施校の児童に限るということで事業展開をしてまいりました。これまですまいるスクールは実施校との強い連携のもと実施してきておりますので、小学校の校長会への十分な説明ですとか、平成１７年１月より。","id":"exchange-061"},{"speaker":"井上委員","kind":"質問","question":"今、１年から３年生に限るということは大変おかしなことだと、私立・国立に対して言えば６年生まで受け入れるべきだと思います。今、そこはちゃんと保障していかなければいけない問題だと思いますけれども、今後どのようにされるのか尋ねました。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは先ほど申しましたように、実施校との強い連携のもとにやってきております。そういった準備を重ねつつ、全校での展開がされていく中で、先の課題ということで検討してまいりたいというふうに思っております。","id":"exchange-062"},{"speaker":"井上委員","kind":"質問・要望","question":"今、いろいろ検討する余地はあると思いますので、ぜひそこのところはきちんと保障できるような仕組みをつくっていってほしいと求めました。それから、１,２４０万１,４００円ぐらい多くなっているんですけれども、この事業の内容で何か変わったところがあるのか尋ねました。","respondent":"谷田部学務課長","answer":"基本的に大きな変更はないんですけれども、予算の増額の部分での内容ですが、介助員の報償費で約１,０００万円ほど伸びを見込んです。特別支援教育検討委員会を来年度も引き続き実施するということで、今年度に比べまして実施回数、それから開催の仕方等を変えてあります。","id":"exchange-063"},{"speaker":"井上委員","kind":"意見","question":"それから、校内委員会を設置するとありますが、校内委員会というものはどういう役割のあるもので、メンバーはどういった方なのかということ。","respondent":"谷田部学務課長","answer":"１点目の特別支援教育検討委員会のメンバーです。来年度につきましても、同じような体制で特別支援教育検討委員会を開催してまいりたいと思ってあります。","id":"exchange-064"},{"speaker":"井上委員","kind":"意見","question":"東京都のモデル事業を行っている評価委員会では言われているんですけれども、もう少し詳しく校内委員会というものを、どう考えているかということをお知らせくださいとの意見を述べました。","respondent":"谷田部学務課長","answer":"ただ、私どもが考えていますのは、その子どもに対する手立てを確実にその学校がやりますというような体制をつくることが校内委員会だと考えています。こういう形のものをつくりますよというようなものは、それぞれの学校によって形はいろいろあるというふうに思ってあります。","id":"exchange-065"},{"speaker":"井上委員","kind":"質問","question":"始まったばかりで、これから検討をしながらということだと思うんです。今回、小中学校に１校ずつモデル校を選ぶということがありますが、ここの学校はもうお決まりなんか尋ねました。","respondent":"谷田部学務課長","answer":"３月２日に最終の検討委員会の中で、今年度の検討結果をまとめるにあたっては、呼ばれて行きましょうと。そうすることによって、巡回チームと検討委員会と学校との体制がうまく機能できるのではないかというようなことをしましたので。","id":"exchange-066"},{"speaker":"井上委員","kind":"質問・要望","question":"それから、時間がないので要望にとどめしますが、学校給食のところで、今回学校給食調整会議が行われるようになっています。私たちは一般質問でも言いましたけれども、現場の子どもたちの声を反映できる仕組みにしていただきたいということを要望させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は３００ページの学校管理費、２９４ページの教育指導費について、それから学校設備費についてお話しさせてほしいと求めました。目標に向かって進む向上心も必要ではないかと思うんですけれども、その辺、教育委員会としての見解を説明を求めました。","respondent":"中島指導課長","answer":"今、ご指摘のありました目標に向かって進む、向上しようとする気持ちを子どもたちが持って物事に取り組むということは、非常に重要なことではないかと考えています。","id":"exchange-068"},{"speaker":"須貝委員","kind":"質問・要望","question":"親からすれば、親がお金を出しても警備員を置いてほしいとか、そういう切実な願いがあると思うんです。目に見えるものが大切ではないかなと思うんですけれども、その辺のご見解を説明を求めました。","respondent":"市川庶務課長","answer":"例えばモニター付電子錠を設置したからといって、それですべてが解決するとは私ども一切考えてございません。ただ、安全確保ということで、少なくとも実効性を出す対策を今後も講じてまいりたいというふうに考えてあります。","id":"exchange-069"},{"speaker":"須貝委員","kind":"質問・要望","question":"次に、学校施設建設費についてお伺いいたします。区内有数の広い校庭を何で狭くしなければいけないのか、その辺の理由を説明を求めました。","respondent":"市川庶務課長","answer":"まちづくり広場の本来の設置目的である、常時校庭の門を開放するわけにいかないという、二律背反の事態が生じていろいろ調整をしてまいりました。その結果、調整がかなわず、今回まちづくり広場の本来の目的達成ということで、区切りのところに防球ネットの設置をするものです。","id":"exchange-070"},{"speaker":"須貝委員","kind":"質問・要望","question":"防災不燃化対策だったか、ちょっと忘れてしまったんですけれども、その優先地域にもなっております。あそこにたむろしている姿というの逆になくて、子どもたちの利益のために何とか守る努力をしていただけたらありがたいなと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"田中委員","kind":"質問・要望","question":"私は２９７ページのプラン２１関連事業のうち、同じ視点で質問をしてまいりたいと思います。今度新たに中学校２年生を対象にして経済体験学習が城南中学校で始まるですが、内容的に、まずお知らせをほしいと求めました。","respondent":"中島指導課長","answer":"その中で子どもたちが買い物をする中で、それぞれのブースでのお店経営を学ぶという視点で、小学校５年生を対象として実施しているものです。車を購入して、生命保険に入ってといった、自分の将来を見通したコンピューターによる仮想プログラミングを体験する学習となっています。","id":"exchange-072"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどのスチューデント・シティ、ファイナンス・パークというのは疑似体験でありまして、外に子どもが出ていくということは実体験であります。さまざまな形の相乗効果が出てくるのではないかという期待を持っているんですけれども、その辺のお考えをお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"その中で実際の経理まで全部子どもたちが係われるかというと、そこの部分は十分に機能できない部分があるのではないかと考えます。市民科ですが、先ほど私の説明が十分ではなかったかもしれません。","id":"exchange-073"},{"speaker":"田中委員","kind":"質問・要望","question":"その中で要望といいますか、小学校５年生だけ中学校２年生だけということですと、ちょっともったいないのかなと。より市民科の効果というものも十分発揮されるのではないかという思いがあるんですが、その辺のお考えをお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"ここに設置していますけれども、私どもが考えている中に、こういったものも位置づけていきたいと考えています。中学校１年生の段階では、一連の中で二つの体験学習がプログラムされているというふうにご理解いただければと考えております。","id":"exchange-074"},{"speaker":"田中委員","kind":"質問・要望","question":"将来の社会を構成する、やはり少しずつでもどこかの中に競争という意識を、健全な形で学習の中にも取り入れるべきなのかなと。そういった疑似体験があってもいいのかなというふうに思うんですけれども、そういった視点からの考えをお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"そういった中にも、子どもたちの経済の中での日本のあり方という部分をかいま見ることができるのではないかと、このように考えてあります。破産してしまうというような子どもも出てまいりますので、そういったようなさまざまな疑似体験がそこで実施できるものと考えています。","id":"exchange-075"},{"speaker":"田中委員","kind":"質問・要望","question":"仕組みができたら、教員の質の向上というのでしょうか、教師の先生方の質をいかに高めていくかということが大きな今後の問題ではないかなと思います。今はプラン２１ですから、仮に名前をつけるとプラン２２が仮にあるとするならば、その辺の考え方をお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"成果基盤型の学校づくり、世の中の当たり前の感覚で学校経営をしていこうという、そういった目的で進めてまいりました。地域との連携が、安全も含めまして地域とともに小学校と中学校の連携を考えることで、このように考えてあります。","id":"exchange-076"},{"speaker":"山村委員","kind":"質問・要望","question":"外国語指導助手の ＡＬＴのことに関してと、２９９ページの学校ＩＴ化推進費、時間がありましたら３０７ページの修学旅行費についてお伺いします。外国語指導助手のＡＬＴのことについてお伺いしますが、採用はどのような形を取られて採用されているのか教えてほしいと求めました。","respondent":"中島指導課長","answer":"こちらのほうは、委託という形で入札しています。","id":"exchange-077"},{"speaker":"山村委員","kind":"質問","question":"勤務態度が悪いような方がいらっしゃったことが品川区であるのかということと、まずジェットプログラム並みに質を維持されているのかということ。それと、１校１日分、大体幾らぐらいかかるのか説明を求めました。","respondent":"中島指導課長","answer":"それまで、若干苦情のようなものがございましたが、今年度につきましては、そういった苦情は教育委員会のほうに特に入ってきてございません。派遣の経費ですが、１日１人１万２,０００円です。","id":"exchange-078"},{"speaker":"山村委員","kind":"質問","question":"今まで寄せられた苦情等、何かありましたら教えてほしいと求めました。１日１万２,０００円は、２３区の平均というわけではないですけれども、なぜここまで安くできたのかということを教えてほしいと求めました。","respondent":"中島指導課長","answer":"昨年度の例になりますけれども、直前になってキャンセルが入って、予定したチーム・ティーチングができなかったというようなお話がございました。こちらの時間単価にすると、かなり低い額になっているのではないかと思いますが、それは派遣会社での対応という形になってあります。","id":"exchange-079"},{"speaker":"山村委員","kind":"意見","question":"価格を優先しすぎてもまずいような気がするんですが、その辺でもう一度、本当に質が保たれているのかどうかとの意見を述べました。","respondent":"中島指導課長","answer":"１単位時間の安いという形で、そこを選んで決定しているという状況ではございません。実際に本年度の実施の中では、それなりのものが確保されていると、このように考えているところです。","id":"exchange-080"},{"speaker":"山村委員","kind":"質問","question":"そうすると、ジェットプログラム並みの質は維持されているというふうに理解させていただいていいのかということを確約していただくのと、採用の方法ですけれども、入札よりプロポーザル方式に変えたほうがいいのではないかと思うんですが、そこに関して教えてほしいと求めました。","respondent":"中島指導課長","answer":"ＡＬＴの採用につきましては、入札の仕様書段階でかなり厳しく条件をつけてありますので、そういった質は担保されているものと考えております。プロポーザル方式につきましては、委託内容また契約等々との関係でできないという形になっております。","id":"exchange-081"},{"speaker":"山村委員","kind":"意見","question":"他区ではプロポーザル方式で採用されている現状のほうが多いと思うんですが、なぜ品川区ではできないのか、もう一度説明してほしいと求めました。","respondent":"鷹倉経理課長","answer":"指導課長から話がありましたとおり、仕様書の中で一定のレベルを確保すると。私どもも経理課サイドとして、一定の実績のあるところを選定しながら候補を指名していくですので、一定のレベルを保たれていると考えています。","id":"exchange-082"},{"speaker":"山村委員","kind":"質問","question":"私が質問をしたのは、プロポーザル方式になぜできないのかということを質問したので、必要ないと思われているなら必要ないんでしょうけれども、先ほどできないというふうに言われましたので。","respondent":"鷹倉経理課長","answer":"採用するに際して、プロポーザルをすることによって、一定の質が保たれるというような判断があれば、そういうことが選ばれるでしょうけれども、現在のところ、そういうことをしなくてもできるという判断があろうかと思います。","id":"exchange-083"},{"speaker":"山村委員","kind":"提案","question":"その割には、そういう意味では、研修体制とかそういうところまでちゃんと提案していく形で契約をされたほうがいいと私は思います。そういうノウハウ等が品川区のすべての小学校同士をつなぐことによって、情報を共有していくのかというところを教えてほしいと求めました。","respondent":"中島指導課長","answer":"１人１台配備いたしますパソコンにつきましては、また成績の処理をしたり、こういった教務事務に使っていく。それから、イントラですけれども、校内のイントラを設置することによりまして、その中での情報共有をグループウェア等を使って実施していく予定です。","id":"exchange-084"},{"speaker":"山村委員","kind":"質問","question":"そうすると、校内では情報共有していくということで、他校とは情報共有しないのかということ。それとも情報漏洩の観点から、インターネットにはつなげないのか、その辺のことを教えてほしいと求めました。","respondent":"中島指導課長","answer":"これらのパソコンにつきましては、学校の中でのイントラとしてつないでいる状況です。そして、インターネットへの接続等も、今後検討していきたいと考えているところです。","id":"exchange-085"},{"speaker":"山村委員","kind":"質問","question":"そういうものを自宅のパソコンに持ち帰ってやった場合、先生の自宅のパソコンから漏れるということはあると思うんですが、そういう意味での生徒の個人情報の持ち出し等はどのように監視していくのか教えてほしいと求めました。","respondent":"中島指導課長","answer":"ウイルスもそうですけれども、セキュリティをどのように組んでいくかというのは、非常に大きな課題だと考えております。情報の一元管理というような方法が考えられると思いますが、それをまた来年度の検討委員会の中で具体的に詰めていきたいと考えているところです。","id":"exchange-086"},{"speaker":"山村委員","kind":"質問","question":"そうすると、今年から導入するけれども、その検討は来年ということになるというふうに理解します。その小学校での児童の情報が６年間なら６年間あったとして、それとも小学校は小学校の内部だけで止めておくのか教えてほしいと求めました。","respondent":"古里品川図書館長","answer":"学校ＩＴ化検討委員会のリーダーをやっています関係で、私のほうからお答えさせていただきたいと思います。そういうこともこれから検討をする内容でございまして、学校の中で使っていくということを考えてあります。","id":"exchange-087"},{"speaker":"山村委員","kind":"質問","question":"修学旅行費のほうでお伺いしたいんですが、その辺のことをお聞きしたいのと、業者が大体そういう場合は固定されていたそうであります。その時に見積りか契約書か、それを出してもらっていないというようなこともニュースに出ていたんですが、この３点を教えてほしいと求めました。","respondent":"谷田部学務課長","answer":"２泊３日の行程で主に関西方面を旅行しますので、当然これは私費会計の部分もありますので、当然契約書を取り交わしてやっているという状況です。たまに業者を変えるとか、相見積りを取るとか、そのような形で公正にやっているというふうに話は聞いてあります。","id":"exchange-088"},{"speaker":"山村委員","kind":"質問","question":"当然、品川区ではこういうことがないというのはわかっておりながら質問をさせていただきました。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"３０５ページの学校図書館運営費と、３２３ページの図書館経費をお伺いします。それから、委託された方に直接指導できるかどうか、その辺を重点にお願いします。","respondent":"古里品川図書館長","answer":"それと、あるいはそこにおけるスタッフの業務の予定等をあらかじめ組んでおきまして、その中で業務を遂行していくということになろうかと思います。","id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問・要望","question":"窓口業務委託のところは、週２日というご説明だったんですが、やはり図書館を回していくためには毎日配置をしていただきたいと考えています。学校図書館というのは、日数の問題と学校との連携について問題があると思うんですが、どのように改善をしていらっしゃるのか尋ねました。","respondent":"古里品川図書館長","answer":"年間の運営予定、月間の運営予定をあらかじめ校長、話し合いをさせていただきながら進めていくということにしています。その中で、少しずつ学校図書館に子どもたちがなじんでいき、読書活動が活発化すればいいかなというふうに考えてあります。","id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして、１人当たりの貸出冊数が５年間トータルを取っているんですが、平成１５年は何と１年間で１人の子どもが１２７冊も本を借りている。以前からずっと要望しているんですが、品川区でもぜひ専任の司書教諭とか司書を配置していただきたいんですが、いかがか尋ねました。","respondent":"中島指導課長","answer":"司書教諭の設置につきましては、これまでも１２学級以上の学校に設置するということで設置してきてあります。図書のボランティア、また一貫教育の中で実施する読書指導の時間、総合的に子どもたちの読書活動を充実させていくことが重要と考えています。","id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問・要望","question":"再度、求めます。もう１点、区民の声をどこで受けとめていくのか、３点お伺いいたします。","respondent":"古里品川図書館長、中島指導課長","answer":"現在今年のモデル実施、当面この形で進めていきながら、あるいは効率的に進められるのかということを検討しながら進めていきたいと思いますが。職員自身が区民の皆さんと直接対応をさせていただいてご案内をする… １２学級以上の学校に配置される司書教諭は兼務という形ですけれども、新しい学校につきましては情報センターという形で図書館、より子どもたちのさまざまなニーズに応えられる体制をつくってまいりたいと考えています。","id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問・要望","question":"窓口業務のところですけれども、委託になった最大の問題点、私はレファレンスの問題だと思うんです。ぜひ、窓口のレファレンスの強化と専門性を高める努力をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"伊藤委員","kind":"確認","question":"約５,２００万円、確認したいのが、配付するパソコンの中に教材開発に係わるソフトが入っているかということ。これに伴うデータ管理とか、それからパソコン自体の盗難対策をどう考えていくのでしょうかということを説明を求めました。","respondent":"中島指導課長、古里品川図書館長","answer":"その中で、そういった教員にもパソコンに習熟して、高度情報化時代に相応しい指導力を高めていくことを目指してまいります。授業での活用の内容、場合によってはｅランニング… 来年度に十分検討していきながら、委員おっしゃるような高度な教材開発ができるような状況も、当然ステージとして考えてあります。","id":"exchange-095"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そのことについては、いろいろな議論があるからここではやりませんけれども、でもつながるわけですから。最後の部分は、できれば別のセクションから答弁をいただきたいんですが、いかがか尋ねました。","respondent":"中島指導課長、市川庶務課長","answer":"こういったような展開も、私どもの検討の中で想定しています。実際に、新しく改築される学校等におきましては、各教室にそういった設備を整えているところです。 教職員の出退勤を含んだ勤怠管理に将来的に活用してはですけれども、この件についてはこれまでも私どものほうから申し上げてきているところですけれども、環境が整い次第、実施する方向で検討しています。","id":"exchange-096"},{"speaker":"伊藤委員","kind":"確認","question":"初めて、受付で「どういうご用ですか」と、声をかけられた現状がありました。警察の方も入って、この学校の安全はこうしたらいいということを考えていく仕組みをつくってみてはいかがでしょうかということを説明を求めました。","respondent":"市川庶務課長、中島指導課長","answer":"今回予算計上させていただきました電気錠の設置をはじめとするハード的な手当ては、あくまでも私どもは学校の防犯対策の一つであるという認識。教員は当然ですけれども、保護者も含めて検討した上で工事の手続に入っていく… 地域、それぞれの小中学校が学期に１回ないしは年間２回というようなところを目安に、学校安全協議会を実施している状況はあります。","id":"exchange-097"},{"speaker":"伊藤委員","kind":"意見","question":"これは非常に有効な安全対策の一つと考えていますので、そのことについての将来的な構想をお聞かせください。それぞれの学校の地域特性に合わせて安全管理対策を十分に確保するべきと思いますが、いかがでしょか、答弁を説明を求めました。","respondent":"市川庶務課長","answer":"１点目の近隣セキュリティシステムの子機の活用につきましては、これをＮＰＯのほうで検討しているというふうに聞いてあります。学校の地域特性等に応じた今後の対応策については、そのような趣旨でこれからも進めてまいりたいと思います。","id":"exchange-098"},{"speaker":"伊藤委員","kind":"意見","question":"安全対策というのは、いろんな角度からいろいろ考えていくべきだと思います。ただ、ハード整備を十分考えるわけでありますので、ぜひともいろんな角度からご検討をしていただきますようにお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"嶋委員","kind":"質問","question":"３２３ページの図書館経費ですが、プレス発表されている学校図書館の整備拡充と子ども読書活動の推進についてお伺いをいたします。いよいよ１８日に中学校の卒業式を晴れて迎えることになりますが、受験真っ最中ですけれども、合格発表当日の学校の対応についてお伺いいたします。","respondent":"中島指導課長","answer":"都立高等学校等の合格発表ですけれども、子どもたちが受験した学校に行きまして、合格発表を見て学校に戻ってきて報告をすると、そういうような形式を大体どこの学校でも取っているかと考えております。","id":"exchange-100"},{"speaker":"嶋委員","kind":"確認","question":"午前中発表の場合と、そういう部分の学校の対応が私はいかがなものかなということがございましたので、ちょっとお聞きをさせていただきました。いいことも悪いことも報告を受けてほしいという、それが基本でよろしいでしょうか、確認をしたいと思います。","respondent":"中島指導課長","answer":"一つの受験合格というのも、進路指導の一コマですので、学校で教員がさまざまな子どもたちの実態に応じて励ます、または喜ぶ、指導すべきところであると考えております。","id":"exchange-101"},{"speaker":"嶋委員","kind":"質問","question":"やっと夕方「どうだった」と聞いたら、子どもが「お父さん、ごめんね」と言う内容なんです。少し親子の時間が取れるね」という父の励ましのそういう本を読んだばかりだったものですから、もしご見解があったらお聞きしたいと思います。","respondent":"中島指導課長","answer":"やはり担任と子どもたちが１６歳に向けての旅立ちを、非常に重要な、また細かい配慮が必要な場面だろうと考えています。まだ今後の自分の将来が決まっていない状況のある子どもたちも若干いると思いますので、学校のほうには指導してまいりたいと考えています。","id":"exchange-102"},{"speaker":"嶋委員","kind":"質問・要望","question":"金曜日の場合は、ぜひこういうことが二度とないようにご配慮をしていただきたいと考えていますので、よろしくお願いいたします。それが拡大できていけるのかお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"小学校との連携ということで、小学校のほうに出向きまして、小学校の給食を食べるような行事に取り組んでいる園もあります。こういったものが委員会の中で提案されたというような情報は、各幼稚園長のほうにはお伝えしていきたいというふうに思ってあります。","id":"exchange-103"},{"speaker":"嶋委員","kind":"質問・要望","question":"今、好ましくないというお話が出たので、ちょっと予定していなかったことなんですが質問させてほしいと求めました。もちろん衛生上は気をつけなければいけないことですが、やっているところがあるので、もう１回お聞きしたいと思います。","respondent":"谷田部学務課長","answer":"各家庭から持ってくる弁当と外見上同じではないかと言われましても、調理場で調理した給食というのは、弁当箱に入れても食べれば同じです。家庭で持ち込んだ弁当とは違うので、その辺の配慮は私どもしなければならないです。","id":"exchange-104"},{"speaker":"嶋委員","kind":"提案","question":"民間委託していく部分がありますので、いろんなケースがあると思いますので、また何かのときに提案させていただきたいと考えています。小学校で毎日、朝ご飯を食べてこない子どもをチェックをして、品川区のご見解をお聞きしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"嶋委員","kind":"質問","question":"では、ＰＴＡ地域健全育成運営協議会のことについてお伺いいたします。私はすごく感動してお礼を言ってまいりましたけれども、こういうものはほかの地域ではどのように進められているのかお聞きしたいと思います。","respondent":"上川内生涯学習課長","answer":"家庭教育支援ということで、今３回実施しているところが１４校、２回が４校です。集まる人たちも５０人のところもありますし、スクールカウンセラーからの話を聞いたりとか、さまざまな活動をしています。","id":"exchange-106"},{"speaker":"嶋委員","kind":"質問・要望","question":"それから、啓発事業を実施するとありますが、これもどういう角度でこういうものを選んでいかれるのかお聞きしたいと思います。そういう意味では、やっていないところの５００冊、やっていないところは、これに対してどのような反応があるのかお聞きしたいと思います。","respondent":"古里品川図書館長","answer":"あわせて同日、４月２３日は各図書館においてもお話し会等を実施したり、それからブックフェアをやったりという形で進めていきたいと思っています。実施校以外の学校からは、これは順次実施していくということの中で、各学校にご理解をいただいているというふうに感じてあります。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"午前中、藤原委員の質問の中で、給食調理代行について質問した件で、ちょっと確認をさせてほしいと求めました。２９７ページのすまいるスクール、３０３ページのほうに入るのでしょうか、介助員についてお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"先ほど来、この個別の問題について、どういう対応を取るのかというような趣旨の質問です。私どもしかるべき時期に、新年度の教育委員会の取り組みということで、広報紙を通じましてお知らせをしていく考えです。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"なおかつ中身をよくしていきましょうという趣旨のもとで拡大をしていくわけですから、きちんと子どもたち、それから親たちに周知徹底するように。共同的な対応ができているかどうかを確認したいと思います。","respondent":"富田教育改革担当課長","answer":"昨年１０月に開設した１２校について、これまでの教訓も含め、大きなトラブルもなく順調に経過しているということがよくご理解いただいております。ただいま保護者会が年２回の２回目をすまいるスクール実施校でちょうど行っているところですけれども。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"移行時期で、今年は２年目に入り、かなりいろいろと対応していただいているなという感じはいたします。それからどうしても学校の中で対処仕切れないという部分があろうかと思うんですが、今後どういうふうにしていかれようとするのか、いかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"すまいるスクールを実施しております学校に在籍する子どもにつきましては、現在でもできる限り利用していただけるように努めているところです。すまいるスクールの全校実施ですとか、実施校以外の子どもの受け入れなど、今後検討してまいりたいと考えています。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"数的にいうと、そんなに多くはないと思いますけれども、その辺は福祉も含めて考えますと、学校の中で全部抱えるということは難しいかもしれません。共同しながらどういうふうに放課後を過ごさせていくのかというところで、進めていってほしいと求めましたが、ぜひご答弁を。","respondent":"辻田児童課長","answer":"一つ障害を持っている方への対応ということが、今児童センター改革の検討の中で、具体的に今後どうするかということを詰めております。そういう中で、システムを今後十分詰めていきたいということで、今検討しています。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、いろんな子どもたちと係われるような、そういう対応を含めて、これからいろいろ検討していただきたいというふうに思います。ここは款別が違うんですけれども、センター機能をどういうふうに持っていったらいいのか、その辺はどのようにお考えになりますか尋ねました。","respondent":"富田教育改革担当課長","answer":"きちんと把握する必要があるのではないかというご質問ですけれども、この点につきまして、また改めまして児童課等々も含めて検討してまいりたいと考えています。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"部分的にでも構わないので、どういう動向があるのかというのを継続的に調べていって事業展開をお願いしたいと思います。すまいるスクールがある程度協力体制が取れるという可能性もありますので、その辺の動向についていかがか尋ねました。","respondent":"富田教育改革担当課長","answer":"やはり我が子が利用している事業である以上、もう少し関心を持っていただきたいなというのが、今現在正直に思っているところです。連絡協議会も課題であることは十分認識しておりますけれども、保護者の方にも、今後とも追及してまいりたいと考えています。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"中心は自分の子どもですから、ある程度関心を持っていただくような問いかけも必要ですし、いろんな関係をぜひつくってほしいと求めました。介助員についてお伺いいたしますが、報酬がどうなっているのか、それから介助員の仕組みがどうなっているのかお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"時間単価１,０００円で、１日の学校の時間を介助が必要な子どもだということで、要綱を持って運営しています。発達障害等で何らかの人の手立てが必要な子どもが入居しているという場合には、そのような形でつけるという制度になってあります。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"では、介助員を申請するのは、校長先生の判断で申請されると思うんです。具体的な介助員をお願いするのはだれなのか、その人を探すのはだれなのか、それはどうなっているのか尋ねました。","respondent":"谷田部学務課長","answer":"介助員を探すのは、学校のほうで介助員の方を探していただくということでお願いしています。ただ、なかなか見つからないというような場合については、教育委員会のほうでわかる範囲で手伝いするというような内容になってあります。","id":"exchange-115"},{"speaker":"西本委員","kind":"質問","question":"問題になっているんですが、介助員を必要としている数の推移は、ここ数年間どういうふうな動向があるのでしょうか。先ほど、１,０００万円増額したということになっているんですが、その辺の推移はどうなっているのか尋ねました。","respondent":"谷田部学務課長","answer":"１４年度からの３カ年の資料がありますけれども、通常学級で説明したほうがわかりやすいので、通常学級のほうで説明いたします。その年度によって、多少違いがあるという状況です。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"関連でお伺いしたいんですけれども、学童保育クラブに通っていた子どもがすまいるスクールになって通えないという状況はないのかどうなのか、その点についてお答えほしいと求めました。","respondent":"富田教育改革担当課長","answer":"すまいるスクールでも、保護者としては行ってほしいんだけれども、本人がなかなかというようなケースはないとは考えておりません。個別に担当指導員が相談を受けて、対応についてご相談に乗っていくというような対応をさせていただいているところであります。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何人ぐらいの子どもがすまいるスクールに移行したことによって通えない状況になっているのか、数字がわかったら教えていただけないか尋ねました。","respondent":"富田教育改革担当課長","answer":"通えないような状況になったという報告は受けておりません。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"３年になったら、特に１年生の子どもが十分な対応をされないために、いろんなお母さんから言われているんです。そういう状況をつかんでいないのか、ぜひ実態をつかむ調査を品川区としてもやるべきだと思うんですけれども、その点についてはどうか尋ねました。","respondent":"富田教育改革担当課長","answer":"ただいま、３１校ですまいるスクールを実施しておりますけれども、対応をしているものというふうに考えております。さまざまな相談、そういったものに丁寧に答えた対応をしていくことが大事であるというふうに話しをしているところであります。","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"わくわくプラザのほうでも、こういう形でしっかりと数字に表れているということで調査をしています。通えていない実態がないというのであれば、その実態を明らかにするためにも、ぜひ調査をしていただきたいというふうに要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"石田委員","kind":"提案","question":"再確認をさせていただきたいんですが、教育委員会である一定度の判断をして、それで提案をしていく。もう１点、ここの部分の提案をしなかったという部分も、まず説明を求めました。","respondent":"市川庶務課長","answer":"予算編成に先立ちまして、実施計画のローリングということが作業的にあります。教育委員会の考えはどうだったのかですけれども、今申し上げた実施計画の審議の段階で、変更なく結論が出されたものというふうに受け止めてあります。","id":"exchange-121"},{"speaker":"石田委員","kind":"確認","question":"後で答弁してほしいですが、そのときに当初４にいくのか５にいくのかという話もありましたが、計画的にというのはどういう計画なのかなと。そういうところの考え方というのか、今後それはちゃんとしっかりして出していきますというところなのかどうか、改めて確認をしたいと思います。","respondent":"市川庶務課長、中尾根企画部長","answer":"そういう意味で、これまで耐震診断を実施する中で、小山小学校の改築という新しい事業が出てまいりました。こういったものを見極める中で、１７年度については小中一貫校の建設計画を出さなかったです。当然ながら教育委員会で原案を考えまして、そして事業部経営会議等で計画に対する議論をして、そして決定していくという仕組みになっております。","id":"exchange-122"},{"speaker":"石田委員","kind":"質問","question":"それが事業部経営者会議だとなかなかそれを組み合わせて、どういう手を打つかというのが、私の感覚の中でちょっと後手に入るのかなと。もっと事前に、全体の周りの状況を把握しながらやっていくという部署があってもいいと思うんだけれども、それに対する考えがあったら説明を求めました。","respondent":"中尾根企画部長","answer":"もともと教育財産でもっているところのものの考え方と全庁的な財産、この考え方を突き合わせるという作業は当然しております。十分慎重に進めさせていただきたいということで協議をしているわけで、手順といたしましては、今委員がおっしゃられたようなことをきちんと踏んです。","id":"exchange-123"},{"speaker":"石田委員","kind":"質問","question":"隣の中学校だから父兄を含めて、子どもを含めて、前の学校でもこうだったと大きくなっちゃう。子どもも不幸だし、親も不幸だから、もうちょっと遠いところへうまく配置はできないのかなというのをお聞きしたい。","respondent":"中島指導課長","answer":"その具申に基づいて、教育委員会として全体の構想を都教育委員会に内申をするという形になっております。その段階で、今委員のご趣旨の状況は、それぞれの学校の状況を見ながら、総合的に判断できる部分ではないかと考えています。","id":"exchange-124"},{"speaker":"石田委員","kind":"意見","question":"今そういう状況であるならば、ちょっとそういう配慮をぜひしていただければなと思いますので、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"},{"speaker":"沢田委員","kind":"質問・要望","question":"それぞれについてお尋ねしたいと思います。この根拠について、述べてほしいと求めました。","respondent":"谷田部学務課長","answer":"現在、各小中学校にそれぞれ配置基準に基づきまして調理師が配置されているという中で、全体の平均的な給与ですね。５８校を全校委託した場合の経費と、当然その部分の経費の軽減につながるというようなことでお話しを申し上げました。","id":"exchange-126"},{"speaker":"沢田委員","kind":"質問・要望","question":"正規職員を民間委託してもいるわけですから、何で８５０円出てくるんだ。だって、トイレが必要ならつくればいいじゃないか尋ねました。","respondent":"谷田部学務課長","answer":"昭和６０年当時の文部省体育局長名の学校給食業務の運営の合理化について、それから高いコスト体質の学校給食を民間に調理委託するというものです。その辺は、私ども学ぶべき点が多くありますが、他の学校給食も運営していきたいというふうに思ってあります。","id":"exchange-127"},{"speaker":"沢田委員","kind":"質問","question":"それならばある事業者は、中学校の委託予定会社ですけれども、最近ＳＲＳＶ（ノロウイルス）の感染事故を起こしたことはご承知でしょうか。ちょっと、そのことを示してほしいと思います。","respondent":"谷田部学務課長","answer":"私ども、当初戸越台中学校、荏原第五中学校で予定していたある事業者は、社会福祉施設関係での食中毒の件があったということで聞いてあります。その食中毒事件があってすぐ、私どものほうに参りまして、事情の説明と４月からの契約は辞退したいというふうに自主的に申されました。","id":"exchange-128"},{"speaker":"沢田委員","kind":"質問・要望","question":"ずっと優れていると言ってきたけれども、あっという間に１０日ぐらい経ったら、この事故ですよね。私はこの業者に決めるときに、業者がこれまで出してきた営業停止や食中毒をどれだけ調べたか、ちょっと述べてほしいと求めました。","respondent":"谷田部学務課長","answer":"会社としては非常に申し訳ないということで、私どものほうにたまたま４月からの給食調理の業務を請け負うにあたっては、自主的に辞退したいです。出るとか出ないとか、そういう問題ではなくて、やはり細心の注意が必要だというふうに思ってあります。","id":"exchange-129"},{"speaker":"沢田委員","kind":"質問","question":"そこに委託しようとするのは、安全の点検をどのようにしたんでしょうか。例えば、業者選定をするときに、今までのこうした状況を調べたんでしょうか、どうか尋ねました。","respondent":"谷田部学務課長","answer":"私どもは実際に４月以降、沢田委員がおっしゃるのは、民間企業はこういう事故を起こすものだという前提でお話しされています。これは直営だろうが、委託だろうが関係ないです。","id":"exchange-130"},{"speaker":"沢田委員","kind":"質問","question":"もし、そういうふうに言うのであるならば、民間企業並みの保障をしたらどうですか。その上で、親御さんの意見も聞いて、今後どうするかということを決めるべきだと思いますが、いかがか尋ねました。","respondent":"古川教育次長","answer":"今回の事業者の事故につきましては、私ども大変残念なことだと考えています。このようなことからまた新たな課題なり、新たな教訓を学びながら進めていきたいと、このように考えてあります。","id":"exchange-131"},{"speaker":"塚本委員","kind":"質問","question":"こういう考え方で伝えるんだよということで間に合うかどうか、変えられるのではないですか、そういう考え方の仕分けが必要ではないか。その大きな仕分け、どうにか今までと違ったしつけの仕方をしようということになってきやしないかと思うので、この辺をまず伺いたいと思います。","respondent":"中島指導課長","answer":"市民科のプログラムを実施するそれぞれの学校は、同じテーマでもさまざま取り組みになっていくと思います。その辺で、お互いに役割を改めて認識して、より充実した取り組みにしていけるよう、１８年度からの移行に取り組んでいきたいと考えているところです。","id":"exchange-132"},{"speaker":"塚本委員","kind":"質問","question":"ですから、そこのところに関しては、こういう問題があって、私たちはこの部分だけを担いますからこうします。ここが問題なんだからこうしてほしいということを、何を言うか、自分たちはこの役割を負うんだという覚悟があるかということを聞いているんです。","respondent":"中島指導課長","answer":"協力というものが絶対に必要になってまいりますので、事あるたびに、私どももこれまでこのプログラムについては説明をしてまいりました。そして協力体制について説明をし、実施していく、そういうことが不可欠になってくるものと考えています。","id":"exchange-133"},{"speaker":"塚本委員","kind":"質問・要望","question":"その考え方が教える側にはっきりできているんですか、そっちのほうが問題ですね。そのことができていますかということを、まず問いたいと思います。","respondent":"中島指導課長","answer":"学校でできる範囲、市民科だけですべてが完結すると、このように考えているわけでもございません。全教育活動の中で実施、充実していくのは、もちろんそのとおりです。","id":"exchange-134"},{"speaker":"塚本委員","kind":"質問・要望","question":"いいんですか、視点が違ってやしませんかということを聞いているんですから、お偉い人のお答えを聞きたいと思います。市民科というのは、その辺はどの程度翻案しているか、どういう考え方を輸入しているかというようなことがわかれば教えてほしいと求めました。","respondent":"若月教育長","answer":"そうした上では、もうこれ以上私たちはこの状態を放置できない。それぞれのご家庭のお父さん、お母さん、こういうことをやっていますから、その方針に沿って、もう１回家庭教育を考えてみてください。","id":"exchange-135"},{"speaker":"土井委員","kind":"質問・要望","question":"だから、この辺をどうするのか、どう考えるのかということを、まずお伺いをしたいと思います。国、都支出金、ここのところに括弧付きでも書いておかなければいけない代物ではなかろうかと思うんですけれども、どうか尋ねました。","respondent":"市岡企画財政課長、中島指導課長","answer":"現実にこの予算書の中では、法令に基づく歳出科目、目的別の中での支出が現存しないものについては書きようがないということが現実です。決してそうではありませんし、論点を必要なところにはあらゆる場で提示をしていきたいと… 具体的にコンピューターを活用して、どういったような指導方法の工夫ができるか、こういったような取り組みを進めてきた経緯があります。","id":"exchange-136"},{"speaker":"土井委員","kind":"質問","question":"と同時に、それは先ほどの中でも、どうも品川の先生は都の先生みたいな話も出てきていたので、これは絶対間違いですから訂正しておいてくださいよ。教育委員会が都の先生だなんて言い出しちゃったら、ほかはだれが言うんですか、そのことを。","respondent":"中島指導課長","answer":"この職員証をそれぞれが学校で明示する中で、区の職員であるという認識をつくっていきたいとも考えてあります。その辺につきましては、区のほうに異動等の人事権をおろせというようなことは、これからもまた都のほうに投げかけていきたいなと考えています。","id":"exchange-137"},{"speaker":"土井委員","kind":"質問・要望","question":"品川の先生だ、そしてまた実際の人も持っていただけるようにしていっていただきたいという思いで申し上げたところであります。今回おくればせながらでもいきますから、今度と急速に進むようにお願いを申し上げておきたいというふうに思います。","respondent":"古川教育次長","answer":"しかしながら、ややもしますとときどき見えてきているのも事実でありますが、私どもは品川区が設置した学校で働く職員は品川区の職員であります。","id":"exchange-138"},{"speaker":"土井委員","kind":"質問・要望","question":"ぜひこれから急速に進めるわけですから、先生方の自己研鑽だけでよろしいということにならないはずですから、ぜひその辺も含めて対応していただくことをお願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"堺委員","kind":"質問・要望","question":"それから、それから３２１ページの文化センターの経費が出ておりますがそれに関連をしてということでお尋ねをします。最初に、現在の不登校の実態について教えていただきたいのと、それから適応指導教室の現在の状況につきましてお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"不登校につきましては、本年度１月末までの状況ですけれども、小学校全校で２９名、中学校では８７名の不登校が報告されてあります。","id":"exchange-140"},{"speaker":"堺委員","kind":"質問・要望","question":"今現在小学生が２９名、中学生が８７名ですか、いろんな事情等でそういう状態になってしまったのかと思います。初期対応を誤らないよう取り組んでいただきたい」、その辺についてもご見解をお聞かせほしいと求めました。","respondent":"中島指導課長","answer":"まれに親御さんとそういった対応についてトラブルになるケースもありますけれども、私どもも含めて細かく対応していきたいと考えているところです。これも委員ご指摘のとおり、大変重要な視点と考えて、実際に連絡会等を実施しています。","id":"exchange-141"},{"speaker":"堺委員","kind":"質問・要望","question":"それから幼稚園につきましても耐震補強工事が今回１園、２６０万円が出ておりますけれども、あと残りは何校になるのか。今回大規模改修等施設整備費約 ３,８００万円計上されておりますが、これはどこでどのような工事をされるのか、あわせてお尋ねをしておきます。","respondent":"市川庶務課長、上川内生涯学習課長","answer":"その意味では、申し上げた小中学校３２校、幼稚園８園、この中で補強の必要がないという耐震診断の結果が出たのがごく一部です。それから耐震補強の必要な幼稚園１園を除いた数が… 文化センターの工事ですが、主なものですと五反田文センターでバルコニーの改修工事、荏原文化センターではプールの消毒装置、旗の台文化センターではスポーツ室の屋上の防水工事、大きなものではそういうところです。","id":"exchange-142"},{"speaker":"堺委員","kind":"質問","question":"これはそれぞれあと何年かけて工事をやるんですか、それは計画ができているのかどうか。それはいかがか尋ねました。","respondent":"市川庶務課長","answer":"幼稚園につきましては、実施いたしました８園のうち２園については、補強の必要なしという診断結果です。その診断結果が出た時点で、全体の事業量がつかめますので、そこの時点でもう一度計画の組み直しをさせていただきたいと考えています。","id":"exchange-143"},{"speaker":"堺委員","kind":"質問","question":"いつ起きるかわからないというのが地震ですから、ちょっとご見解をお願いしたいんですが、いかがでございましょうか。耐震補強工事が今回入っていないんですが、こういうところは必要がないのでやらないのか、その辺の見解も教えていただけますか。","respondent":"市川庶務課長","answer":"耐震補強工事を行うときには、そういった諸工事とうまくタイミングを合わせて実施したいということが一つ。こういったことから、分散やむなしという考え方が現場サイドとしては持っているところです。","id":"exchange-144"},{"speaker":"堺委員","kind":"質問","question":"わかるんですが、いつ起きるかわからないのが地震ですから、速やかにという、この前提でよくとらえていただければと考えています。もし、そちらのほうに書類がありましたら、要するに品川区の教員の年代別の構成がどうなっているか、教えていただけますか。","respondent":"中島指導課長","answer":"中学校におきましては、４０代前半と４０段後半に大きな山があって、あとはそこから次第に少なくなっているというような状況にあります。全体といたしましては、４０代後半のところがピークとなる形で推移しているという状況があります。","id":"exchange-145"},{"speaker":"堺委員","kind":"意見","question":"つい最近の報道でも、文部科学省が２月１６日にこのようにおっしゃっています。今年ですと６０歳の定年を迎えた教員が約７,７００人、品川区では４０代後半がピークであるとありましたけれども、その辺についてお願いしますとの意見を述べました。","respondent":"中島指導課長","answer":"これが継続していける部分があろうかと思いますが、かなり大量の補強になっていく可能性があります。これは本区だけの問題ではなくて、全都的な問題でもありますので、都とも連携を図りながら質のよい教員の確保に努めてまいりたいと考えています。","id":"exchange-146"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひ、新たに採用するときは、質のいい教員を採用していただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"原委員","kind":"質問","question":"何にあたるんでしょうか、２９４ページなのか２９７ページなのか、要するに教育改革についてちょっとお伺いをします。いまだに、まとまりのつかない中での質問になってしまうんですが、教育委員会はどういうふうにお考えをお持ちなのか尋ねました。","respondent":"中島指導課長","answer":"子どもたちが学びの質を高めることができるだろうとそもそも考えられた部分が、このゆとり教育の原点であると考えております。理解だけではなくて、総合的な学びを実現していこうと、こういう連動するものであったと考えています。","id":"exchange-148"},{"speaker":"原委員","kind":"質問","question":"それを知識として身につけ、その知識を応用した新しいものを創造していく力を養うのが学力だと、こうなってくるわけです。そうすると、品川区の中において、学力は小中一貫の中でどういうお考えが基本になって進めようとしていらっしゃるのか、お伺いさせてください。","respondent":"中島指導課長","answer":"そして個性伸長、こういったものを進めるために、学校でやろうとしていることは簡単にできる内容ではございません。私たちも全力で取り組まなければならないと考えているわけですが、基礎的な学力の定着の部分と個性伸長、この二つを大きな柱と考えています。","id":"exchange-149"},{"speaker":"原委員","kind":"質問・要望","question":"その中でしっかりとしたものを養うには、この市民科の力が大きいわけで、それをもっと養っていかなければいけないと思うんです。私も代表質問の中で市民科についてお伺いをさせていただきましたけれども、ちょっとお伺いさせてほしいと求めました。","respondent":"中島指導課長","answer":"小中一貫教育の中では９年間という長いスパンの中で、子どもたちの発達段階に合わせて一体となった指導を進めていくことができる。単元としてつくっていく中には、今まで各学校が取り組んできた地域連携ですとか、今後内容の充実を図っていきたいと考えているところです。","id":"exchange-150"},{"speaker":"原委員","kind":"質問・要望","question":"基本的には、市民科の中には、人間としての心とか思いがしっかり入り込んでいなければいけないかと思うんです。これから教育委員会が１８年度に向かって、しっかりやっていただきたいというところを、最後にお話しをしていただければありがたいと思います。","respondent":"若月教育長","answer":"そして、私たち大人はあの風潮に対して、果たして私は教師としてどういう対応と主張ができたでしょうか。今までの経験を決して無駄にしない新しい教育の展望を開こうと、こんな決意でこれからも頑張ってまいりたいと考えております。","id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/330368?Template=document&Id=850#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":122101,"voices":341}},{"id":"h17-20050318-11","meetingId":"h17-cm03","date":"2005年3月18日","dateIso":"2005-03-18","committee":"自治制度特別委員会","time":"午後２時０３分～午後２時２３分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"附帯決議（案）","agenda":"附帯決議（案）","exchanges":[{"speaker":"南委員","kind":"意見","question":"ここのところを、句点を打たずにつなげたらどうかなと思っているんです。個々には、言葉の表現だとかはありますけれども、基本的にはいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"須藤委員","kind":"質問","question":"ですから、そこはまた分けておかないと、つなげちゃうと、何が何だかわからなくなっちゃうという流れ方になるんじゃないかと思うんです。そこは少しぼやかした感じというのを、ここは分けておかないと、全部が流れちゃうと違った意味になってきちゃうと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"高星委員","kind":"意見","question":"ほんとうに、そう思うので、私はこの案ですっきり通してもらいたい。そうでなくて、ぐずぐず言うんだったら、私だってほかのところでまた言いたいところはあるからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"藤田委員","kind":"提案","question":"正副委員長がまとめられた文面でいいと思います。もう一つは組織の肥大化ということで分かれているんじゃないかと考えていますので、提案のとおりでいいんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"本田委員","kind":"質問・要望","question":"その審議をもう一度お聞かせいただきたいのは、３番目、解散を含めて検討するべきである」と。その辺のところを、ちょっとお聞かせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本田委員","kind":"意見","question":"自治権確立という大きな観点から言えば、非常に重要な指摘ではありますので、その辺、ぎくしゃくしないような配慮をしながら、こういう文章をつくった、表現をしたということであれば、正副委員長のところで、それぞれ違ったお立場の正副委員長が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"須藤委員","kind":"意見","question":"直されちゃったら、逆に我々がおかしくなっちゃう。今、皆さん、これで結構ですというご意見なんでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"南委員","kind":"質問","question":"ようやくここに来て発展してきているということですから、皆さんと一致するところで、この決議を出していきたいということです。そういうふうに変えてもらいたいということですから、ぜひ、誤解なきように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918758?Template=document&Id=5564#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":5170,"voices":20}},{"id":"h17-20050322-3","meetingId":"h17-c-budget","date":"2005年3月22日","dateIso":"2005-03-22","committee":"予算特別委員会","time":"午前１０時０４分～午後９時０４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を140件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"財政調整をめぐる未完の都区制度改革についてお伺いをいたします。主要５課題、都から提出された大都市事務の内容と主張の違いが多数あると思いますが、改めてお知らせをほしいと求めました。","respondent":"市岡企画財政課長","answer":"これから検討するものも含めても８,４００億円弱が最大のところである、こういう反論を行いました。これからはまさに一つ一つの事務の内容を掘り下げて１つずつ都側に反論していかなければいけませんので、各事業部、このように考えているところです。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"そういう形の中で、そういう道州制、特別区の再編まで含めて議論をしていくべきだろうという質問も出ております。今現在どのようにお考えになっているか、そのお考え方、感想等をお聞かせ願いたいと思います。","respondent":"高橋区長","answer":"東京都が２３区の問題に対して、どれだけ真剣に取り組んでいるか、これが私は一番重要ではないかと考えています。かなり下、下といいますか、都の内部の中では検討がされているんじゃないかというような気がいたします。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"今後、現実的な落としどころはどこにお考えを持たれているのか、そこら辺の議論をしたいというように私はずっと答弁を読んできて思っております。今言いましたさまざまな５課題の落としどころの部分の解決策の中で、いないのか、そこら辺の３つの点をお聞かせ願いたいと思います。","respondent":"高橋区長","answer":"この２つの方法がこれからの課題だと考えています。１つは、先ほど申し上げました水平調整を区ができるかできないか。","id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"これが例えば今言ったポイントというかパーセントのもので５２をどうしていくか。何らかの方法、明確に我々もその部分についてもちろん後押しをしていくつもりでありますし、そういう形の部分の明確な答弁をほしいと求めました。","respondent":"高橋区長","answer":"ほんとうの財政調整、また２３区のほんとうの独立は私はないかと、そのような思いでこれからもやってまいりたいと考えています。よろしくご支援のほどをお願い申し上げます。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問","question":"平成１６年１１月に中央防災会議による首都直下地震の想定の被害建物、約８５万棟、経済損失は推定で１１２兆円と発表がありました。その評価と、今後の安心、安全に対する考え方をお知らせ願いたいと思います。","respondent":"山田区民生活事業部長","answer":"消防団などの皆さんの連携のもとに地区防災訓練の充実、体験を通じてリアルな対応力を身につけていただくというところで実施をしています。水の確保ということで、学校の受水槽の遮断弁を置くなどの実施をし、区民の皆さんの不安にこたえていきたいというふうに考えてあります。","id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"そこをどういうふうにとらえていくかという観点から質問をしていきますが、その対策として今耐震診断、耐震改修を行っている。ここら辺の部分は何が原因で、どのような形で進んでいないかと思われているかというところを教えていただきたい。","respondent":"中谷まちづくり事業部長","answer":"このことについては全国的な分析というものが正確になされていないというふうに認識しておりますが、１つ考えられますのは。このＰＲを今後行っていく予定ですが、今年耐震診断をされた方についてもアンケート調査を実施して、このように考えているところです。","id":"exchange-006"},{"speaker":"石田委員","kind":"意見","question":"そういうことをとらえるのであれば、今のお考えはわかるけれども、そこにもう一歩何か突っ込んで政策を打っていかないと、これは進まないと。そこら辺のところを突っ込んで、もう一段お考えがあれば、お聞かせ願いたいとの意見を述べました。","respondent":"中谷まちづくり事業部長","answer":"しかし、生命はみずからが守る、こういう区民の皆さんに対して側面的な支援をしていくということになるんではないかというふうに考えております。動機づけを行い、広域的なこうした取り組みが区としては必要ではないか、このように考えているところです。","id":"exchange-007"},{"speaker":"石田委員","kind":"提案","question":"これは区が認定するわけですから、例えば共済制度とか行政によるインセンティブ制度、こういうものを創設するべきだろうと私は思っております。こういうことはしっかり訴えていくべきだと私は思っておりますが、そこら辺の点についてのお考えを説明を求めました。","respondent":"中谷まちづくり事業部長","answer":"非常に掛け金が高くなるといったような問題があり、阪神・淡路大震災でも兵庫県が検討いたしましたが、やはり県単独では無理で。そういうことが肝要で、いわゆる役割分担を的確に行っていくということがこの事業の推進に役立つものというふうに認識しております。","id":"exchange-008"},{"speaker":"石田委員","kind":"意見","question":"だから、その保証枠でも例えば５０億円ぐらい積めば一歩前に出られるなという試算もしました。国だ、そこでやっているからといって、その点についてのお考えをもう１回お聞かせ願いたいとの意見を述べました。","respondent":"中谷まちづくり事業部長、高橋区長","answer":"やはり一定の広さの中でやっていかないと、品川区の中だけで考えていっても、なかなかそれが広がっていかないというような問題もあります。そういう意味では、区としては… そうすると、区の問題としてこれをどこまでやっていけるか、それはこれからの検討に値するものではないかと考えています。","id":"exchange-009"},{"speaker":"石田委員","kind":"意見","question":"ここは非常に自分の部分もありますが、これを言っていいのかどうかわかりませんが、政治家は票を持つ生き残った人に最大限気を使う。そこら辺の意識改革と考え方と、もう一度そういう意味で取り組んでいく決意がおありでしたら、その決意をお聞かせ願いたいとの意見を述べました。","respondent":"高橋区長","answer":"先ほど申し上げましたように、この問題につきまして早急に検討に入らさせていただきたいと考えています。その検討の結果、また議会のほうにご報告させていただきたいと思います。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういう見地から伺っていきますけれども、我が区では昨年品川区情報公開・個人情報保護条例というのを実施するようになりました。始まりましたコンビニでの収納のときの納付伝票というんですか、どうやって区として管理をしていくのか、説明を求めました。","respondent":"山田区民生活事業部長、古川教育次長、新美福祉高齢事業部長、小沼児童保健事業部長、中谷まちづくり事業部長","answer":"私のほうから区民保養所とコンビニ収納に関しましてご説明します。あくまでも番号、いわゆる納付番号だけがあるということで個人の特定はできないよ… あるいは学校における業務の家庭における継続、こういうことは一切ないようにという観点からあわせてこういう指導もしています。… さらに今回の条例改正事項につきましても平成１７年度の契約時に徹底をしてまいります。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"どうしても明日の朝までにはやらなきゃいけないというと、あるいは名簿管理ですから、どこでどういうふうに使うかわからないという部分がある。そういう出ていった部分はどういうふうにお伝えをしてお願いをする、そういうようなことを考えていらっしゃるのか、答えるよう求めました。","respondent":"中尾根企画部長","answer":"古い名簿と新しい名簿と差しかえる、こういうことを厳密にやるということが情報の管理の第一歩になっていくかというふうに思います。ここに１つの注意を払わなくてはいけない、この管理の徹底を今後十分していきたい、このように考えてあります。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それの外側ということになるとなかなか難しい、その辺もどういう方法があるのか検討を加えていただきたい。公開しなければいけない法の精神というのを一度お聞きしたいと思っていましたので、この際、説明を求めました。","respondent":"中尾根企画部長、山田区民生活事業部長","answer":"純粋な民間の場合は、今回の個人情報保護法そのものについては４月から全面実施されるわけですけれども、こういうことになるわけですね。それぞれの機関を通してこの法を訴えて… 特に４情報については個人の秘密に属する事項を含まれていないという解釈のもとに実施がされているというところです。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問","question":"今、個人情報はしっかり守らなきゃいけないというふうになってきたのに、なぜ行政として持っている個人情報、基本的な情報ですよね。その精神は何ですかというふうにお聞きしたんで、ちょっと一問一答みたいになりますけれども、もう一度お願いします。","respondent":"山田区民生活事業部長","answer":"いわゆる４情報、秘密に属さないというところでの解釈のもとに、これは経済的な活動の中のいわゆるマーケティングであるとか学術調査の中で提供できる範囲というふうに解釈をして提供しています。","id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そうすると、一般的な名簿はそんなようなものじゃないですか。１つお聞きしておきたいのは、評価はどういうふうにされていたのか、単に財源が来たからやったということでは済まされないのかなと。","respondent":"山田区民生活事業部長、中尾根企画部長","answer":"例えば民生委員であるとか私どもで持っております税情報の名簿とかいうことになると、そこに税がつく。いわゆる秘密が含まれているというふうな解釈のもとに名簿というような意味合いと変わってくるかというふうに考えてあります。 １次、２次の継続になりました。そのことに新たな人材を活用できたこと、これが残っているということが非常に大きな意味があったのではないか、このように把握しています。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"確かに２,５００人ということで効果も出たというふうに私たちも認識を持っていますけれども、事務事業評価という点ではされていないんでしょうか。これからどうしていくのか、この緊急地域雇用対策費の中で生まれた事業というのはどうこれから扱っていくのか、その辺を説明を求めました。","respondent":"中尾根企画部長","answer":"事業の継続のほうを先ですけれども、毎年度予算査定等の中で、継続すべきかどうかということを一つ一つの事業についてずっと行ってまいりました。","id":"exchange-016"},{"speaker":"林（宏）委員","kind":"提案","question":"１つ提案なんですけれども、プランを出してみなさい、その辺お考えをお聞かせいただければありがたいと思います。世界に発信をしていくというような、そんなシステムをつくっていくことも必要かなと思いますけれども、ご見解を説明を求めました。","respondent":"中尾根企画部長、山田区民生活事業部長","answer":"緊急地域雇用のほうの件ですが、どういう事業にふさわしいと考えるか、こういう現実的なやりとりをしてこれまで積み上げてまいりました。今後については… 特にベンチャー企業の誘致を含めて活性化に努めているところですけれども、工業系、今力点を置いて実施をしております。","id":"exchange-017"},{"speaker":"林（宏）委員","kind":"提案","question":"１つ提案なんですけれども、市、区で行われている産業見本市というのがあります。いきなりでは難しいかと思いますとの意見を述べました。","respondent":"山田区民生活事業部長","answer":"横浜市、いわゆる４都市共催による合同商談会、また東京都の主催しております産業交流展というものに各産業の方々が出店をしていく支援をしています。","id":"exchange-018"},{"speaker":"林（宏）委員","kind":"意見","question":"次に、環境問題について、２月１６日に京都議定書が発効いたしました。水道の問題、環境減税というようなものを品川区で打ち出せればと思いますけれども、お考えを聞かせてくださいとの意見を述べました。","respondent":"岩崎環境清掃事業部長","answer":"その中で、その中で自治体としても温暖化ガスの削減に取り組むような計画をつくるようになるというふうに考えております。その内容そのものは国がこれから発表するということでございまして、私どもとしましては、それをまず待ちたいというふうに考えているところです。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"品川区でもそういう強い意欲で、家庭にお願いをしていくということはできることなんですから、ぜひ進めてほしいと求めました。それからもう一つは生涯学習ということを確認をしていきたいと思いますけれども、７校、その辺の細かいところまでお知らせをほしいと求めました。","respondent":"古川教育次長","answer":"起債が約１割ちょっとですけれども、大体３分の１程度が基金からの繰入、このように考えております。８校のそれぞれの必要性を勘案しながら、それぞれ必要な改築を進めている、こういうところです。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"意見","question":"よその区ではだから学校を３つまとめて直せば１校分で済むというような短絡的な考えでしている地区も、地域もあるというふうに聞きます。どうぞ財源の見通しについて聞かせてくださいとの意見を述べました。","respondent":"市岡企画財政課長","answer":"今基金は１２５億円ありまして、これは実施計画は３年単位ですが、もう少し先まで私どもはきちんと財政計画上の裏打ちをしております。ここをしっかり都区間の協議の中で確保していくということが大事だというふうに考えてあります。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"生涯学習ということで伺います。生涯学習課、図書館とありますけれども、生涯学習課と学校教育というかかわりを説明を求めました。","respondent":"古川教育次長","answer":"確かに教育委員会の事務局の１課ですけれども、さまざまな部署で行っているそれぞれの施策、それぞれが事業として大きく成熟してきている。今回、学校図書館あるいは区立図書館というものを連携しながら、教育委員会における新たな１つの挑戦というふうに私自身は考えてあります。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"それから義務教育の６年、３年の小中学校、教育委員会として生涯学習というのをもう少し力をつけさせるべき。地域の中でどうやって子どもたちを育てるか、あるいは子どもたちが暮らすか、もう一度生涯学習についての教育委員会の力強いご答弁をお願いします。","respondent":"若月教育長","answer":"学校教育の充実を含めて、それをさらに充実させるということは国を挙げての課題であると、教育委員会といたしましても認識をしています。ご指摘のとおり、それを学校教育という子どもたちの段階からしっかり基礎づくりをしていきたい、こんなふうに考えているところです。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"金曜日に行われた中学校の卒業式で高橋区長の祝辞をお聞きしました。ぜひ職員の方々、この中学生のメッセージを職員という立場でお受けとめいただければありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"武内委員","kind":"質問","question":"この発達障害という言葉、そもそもこの発達障害とはどういうものなのかということについて、まずお伺いをしたいと思います。今回この法律が成立し、施行されるに至った背景についてあわせてお尋ねをいたします。","respondent":"新美福祉高齢事業部長","answer":"第１に、法制度もなく制度の谷間になっており、従来の施策では十分な対応がなされていないということが１つです。第３に、その結果、家族は地域での支援がなく大きな不安を抱えているという。","id":"exchange-025"},{"speaker":"武内委員","kind":"質問","question":"そこで、具体的な支援について次にお尋ねをしたいと思います。早期療育が非常に重要だというふうに言われておりますが、その理由について、お伺いをしたいと思います。","respondent":"新美福祉高齢事業部長","answer":"しかしながら、現状では放置される結果、不登校や引きこもりなどの２次障害を引き起こすケースが多いと言われております。","id":"exchange-026"},{"speaker":"武内委員","kind":"質問・要望","question":"今ご指摘いただいた２次的な問題、今の本区の取り組みの現状と、また発達障害の診断状況についてわかる範囲で教えてほしいと求めました。","respondent":"伊藤品川区保健センター所長","answer":"それから専門の小児科医による発達相談というものを同じ人を対象に１回こっきりでなく継続的にご相談に乗るということを実施しております。","id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"年間１００名から１３０名ということで、なかなか発見できない場合もあるというふうにも伺っておるんですが、どのように認識されていらっしゃるのか。今後早期発見をさらにしていく上での取り組みについてはどのようにお考えになっているのか、あわせてお伺いしたいと思います。","respondent":"伊藤品川区保健センター所長","answer":"それから、１回の健診の場面で疑うということがなかなか難しい障害であるということがなかなか難しい理由の幾つかということで挙げします。","id":"exchange-028"},{"speaker":"武内委員","kind":"質問・要望","question":"やはりいずれにしても早期発見については専門的知識を持った方々が非常に必要になってくるというふうに感じております。先ほどあった３歳児健診ぐらいの低年齢では、今後そういった形のものが有効だというふうに確認された場合に、あわせてご所見をお伺いいたします。","respondent":"伊藤品川区保健センター所長","answer":"いろいろな取り組みが現在なされているところですので、今後、各自治体の動向等を踏まえて対応をしてまいりたいと思います。療養支援体制を組み立てながら、そういうニーズを中心とした取り組みにしていくのかということについて、検討をしてまいりたいと考えています。","id":"exchange-029"},{"speaker":"武内委員","kind":"確認","question":"このことについてのご所見をお伺いするのと、これをどうするのかという、これも非常に大事であると思います。そうした意味で、この親への理解もどのようにしていくのか、お考えをお伺いしたいと思います。","respondent":"伊藤品川区保健センター所長","answer":"確かにおっしゃられますように、区の職員がこの障害に対しての正しい認識を持つということは大変に欠かせないと考えています。早期発見にもつながることであろうというふうに考えますが、これに取り組んでまいりましたが、研修を重ねていきたいと考えています。","id":"exchange-030"},{"speaker":"武内委員","kind":"質問・要望","question":"区市町村からの個別の研修の要望にも対応しているということで、ぜひその辺のところを大いに活用してほしいと求めました。来年度国で実施する予定の発達障害者支援体制整備事業、これがどのように区の支援と関連してくるのか、あわせてお伺いをしたいと思います。","respondent":"伊藤品川区保健センター所長","answer":"必要なお子さんには子育て支援センターですとか、それから児童学園ですとか、それから医療機関等へつなげるというふうなこともしております。","id":"exchange-031"},{"speaker":"武内委員","kind":"質問・要望","question":"これとの連携についてお尋ねをいたしたいと思いますが、ご要望してまいりましたが、これをどのように図っていかれるのかお伺いしたいと思います。","respondent":"伊藤品川区保健センター所長、古川教育次長","answer":"これは都道府県とか指定都市に発達障害の検討委員会を設置するということ、それから障害保健福祉圏域において支援の体制整備をモデル的に実施するということで、国の動向等を見ながら関連については検討をしていきたいと考えております。特別支援教育との連携の点ですけれども、私ども学校における特別支援教育の実施に向けた検討ということで、さまざまな角度で実施をしてまいりました。","id":"exchange-032"},{"speaker":"武内委員","kind":"質問・要望","question":"げんき塾で行っておりますが、こうしたものも今後発達障害者に対しても同じような支援を検討すべきと思いますが、いかがでございましょうか。東京都に対しても就労支援体制の整備を積極的に働きかけてほしいと求めましたが、それぞれあわせてご所見をお伺いします。","respondent":"新美福祉高齢事業部長","answer":"今回の発達障害者支援法の成立、どのような支援ができるか、対応を十分検討していく必要があると考えております。区といたしましてもさまざまな機会を通じ、東京都への働きかけを行ってまいります。","id":"exchange-033"},{"speaker":"武内委員","kind":"質問・要望","question":"区では今後、区民に対してどのような意識の啓発をお考えなのか、お伺いをいたします。昨年の第３回定例会での同僚議員の一般質問の際にもご要望させていただきましたが、改めまして、ご所見をお伺いいたします。","respondent":"新美福祉高齢事業部長","answer":"お尋ねの発達障害につきましての正しい理解の促進は、今後進めていく支援体制の整備に当たって不可欠の課題というふうに認識しております。現在家庭あんしんセンターで場の提供等の支援を行っておりますが、引き続き適切な支援に努めていきたいと考えております。","id":"exchange-034"},{"speaker":"武内委員","kind":"質問・要望","question":"資料を使ってお伺いしたいと思いますが、これをかけると、子どもの視野が体験できる。子どもの目線を意識しながらこれからも安全対策に取り組んでいただきたいというふうに思いますが、まずご所見をお伺いしたいと思います。","respondent":"古川教育次長","answer":"そういう観点から申し上げますと、私どもも学校という施設の中でのさまざまな事態に対処する上で、大人だけの考え方では十分とは思ってございません。","id":"exchange-035"},{"speaker":"武内委員","kind":"質問・要望","question":"子どもに象徴されるような社会的に弱い立場の方々、例えば高齢者や障害者など、こうした方々の目線にも通じると考えております。今後ともさまざまな施策を行っていただきたい、このように要望しますが、改めましていかがでございましょうか。","respondent":"古川教育次長","answer":"ただいまご発言ございましたように高齢者であるとか、あるいは障害をお持ちの方、さまざまな方々にさまざまな施策があります。それぞれ相手の立場に立って施策を組み立て、そして展開していく、これは基本であろう、こういうふうに考えております。","id":"exchange-036"},{"speaker":"武内委員","kind":"質問","question":"限られた時間ですので、今回は子どもの目線に立った学校の安全対策に絞ってお伺いします。このことについてのご所見をお伺いしたいのと、どのような指示を出されたのか、あわせてお伺いをいたします。","respondent":"古川教育次長","answer":"今回のように卒業生という中での極めて特定な事件とは思いますけれども、見知らぬ方との応対については必ず複数での対応を心がける。複数で対応する、さらには児童生徒の登下校のあるいは休み時間には安全確保のため、教職員が一定の巡回を行う。","id":"exchange-037"},{"speaker":"武内委員","kind":"提案","question":"私ども公明党も党を挙げてこれまでさまざまな視点から子どもの安全対策について人的配備も含めたいろいろな提案をしてまいりました。平成１７年度の文部科学省の予算には、実施をする予定と聞いておりますが、この事業の内容について簡単にお知らせくださいとの意見を述べました。","respondent":"古川教育次長","answer":"都道府県それから政令指定都市全部で６０になろうかと思いますが、それぞれが単位としてこれから申し上げる３つの事業を実施する。学校安全の体制の整備を推進する、これが文部科学省が平成１７年度に予定している事業の概要です。","id":"exchange-038"},{"speaker":"武内委員","kind":"質問・要望","question":"この辺のところがもしわかればお教えいただきたいのと、そのモデル地域に手を挙げることができるのかどうか、その辺も教えてほしいと求めました。","respondent":"古川教育次長","answer":"私どもはまだこれからのことですけれども、東京都から、この事業についての説明について来月お話を伺う。さらには東京都下でどういう形でこの事業の推進を東京都自体が考え、私なりの本事業の対応を検討してまいりたい、このように考えてあります。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問","question":"ぜひ積極的に手を挙げてもらえればと思います。ところで、現在本区では通学路の安全のために４２カ所で交通指導の委託を実施しておりますが、この辺の理由についてお伺いをいたします。","respondent":"古川教育次長","answer":"この事業につきましては、こういう観点から事業としては大変古うありますけれども、一時的には学童擁護員という形の常勤職員は対応してございました。","id":"exchange-040"},{"speaker":"武内委員","kind":"質問・要望","question":"具体的にどのような検討をされるのか、今ご答弁いただいたかもしれませんが、改めましてありましたら。検討の中で、これらを含めた安全対策への活用も視野に入れて検討すべきというふうに要望しますが、理事者のご所見をお伺いいたします。","respondent":"古川教育次長","answer":"そういう現事業と、そして学校におけるさらなる安全対策の向上という観点から何らかの活用策が少し検討できるのではないか、こういうことです。地域の方々のご意見等を踏まえながら、さらなる検討をしていく必要があるだろう、このように考えてあります。","id":"exchange-041"},{"speaker":"武内委員","kind":"質問・要望","question":"先日、安全のまちづくりを求める署名、大勢の方の思いを要望書として２月２８日には東京都知事とまた高橋区長にもお届けをさせていただきました。積極的に取り組む、また高橋区長からも要望の趣旨を踏まえて早急に検討するとの力強いお言葉をいただき、スクールガードの実現を要望しますが。","respondent":"古川教育次長","answer":"学校内における児童生徒の安全対策はまさに重要な課題ととらえてあります。学校における安全、安心の環境づくりをこれからも一層推進していきたい、このように考えてあります。","id":"exchange-042"},{"speaker":"武内委員","kind":"質問・要望","question":"子どもが危険にさらされているということは、私たちの地域や社会が危険にさらされていると言っても過言ではないと思います。ぜひ子どもの目線からの安全対策を重ねて強く要望し、私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"山路委員","kind":"提案","question":"平成２年にはごみ問題や資源リサイクルの促進、屋上緑化の助成等を初めとしてさまざまな提案を含め、質問をしてまいりました。そこで質問の第１点目は、この新規事業の内容について、具体的にご説明をほしいと求めました。","respondent":"岩崎環境清掃事業部長","answer":"これは以前から私どもが進めておりました推進会議という区民を含めた環境活動を実施している会議がございまして、こういう内容です。会議室等、庁舎の中で区民が具体的な目標を持って活動していくという新しい活動のスタイルというものをここでやっていただくです。","id":"exchange-044"},{"speaker":"山路委員","kind":"質問","question":"ただいま説明をいただきました環境情報活動センターの事業内容について、何点かお伺いいたします。土日を開館すべきだと考えますけれども、それについてはどのようにお考えでしょうか、お伺いいたします。","respondent":"岩崎環境清掃事業部長","answer":"区民が活動するということで仕事をお持ちの方が活動するわけですので、土日が主な活動時間になるというふうに想定もできます。そういう意味で、土日を極力あけておけるような体制をつくっておきたいというふうに考えております。","id":"exchange-045"},{"speaker":"山路委員","kind":"質問・要望","question":"ぜひその方向でお願いをいたします。あわせて、防災センターの土日の開館もご検討していただきたいと思っているんですが、お聞かせをほしいと求めました。","respondent":"山田区民生活事業部長","answer":"これは一時期大変来館者が多いということであえて土日をあけてということで実施をしてまいりましたが、一定の時期から大変人数が落ちてまいりまして、これもしばらく様子を見させていただきながら検討ということになろうかと存じます。","id":"exchange-046"},{"speaker":"山路委員","kind":"質問","question":"２つ目は環境情報の収集、発信についてであります。この情報はどのように収集されて、どのような形で発信されるのか、お伺いをいたします。","respondent":"岩崎環境清掃事業部長","answer":"私どもはグリーン化支援というふうなことを言っておりますけれども、現地に行って、そういうことを進めていきますと自然に情報も集まってきます。","id":"exchange-047"},{"speaker":"山路委員","kind":"質問・要望","question":"この募集というのはうちに来ていただきたいとか、どのようにお考えでいらっしゃるのか、お聞かせほしいと求めました。","respondent":"岩崎環境清掃事業部長","answer":"そういうことを教えてもらいたいと思っている方のところに出かけていって、教室ですとかワークショップなんかを開くというようなことを呼ぶわけです。","id":"exchange-048"},{"speaker":"山路委員","kind":"質問・要望","question":"３つ目は、環境学習講座、環境啓発事業の開催について、具体的にはどのような取り組みを考えていらっしゃるのか、お伺いしたいと思います。その辺も含めてどのような展開をされるのかお聞かせをほしいと求めました。","respondent":"岩崎環境清掃事業部長","answer":"学校のほうからアクセスして、この環境情報活動センターのホームページからノウハウをダウンロードできるというようなことも可能かと考えております。具体的に教室を進めていく中で、こういう情報発信についても考えていきたいと考えております。","id":"exchange-049"},{"speaker":"山路委員","kind":"質問・要望","question":"次に、４つ目は人材の育成についてお伺いいたします。このセンターを大いに活用して人材を育成してほしいと求めましたが、お考えをお聞かせほしいと求めました。","respondent":"岩崎環境清掃事業部長","answer":"これからも別のＮＰＯができるかもしれませんし、またＮＰＯの方々がどんどんお仲間を集めてきて人が増えるというようなことも予想しております。そういう意味で、どんどん人は活動センターを中心に集まってくるかなと、こういうふうに願っているものです。","id":"exchange-050"},{"speaker":"山路委員","kind":"質問","question":"５つ目は中小企業グリーン化支援についてでありますが、具体的にはどういうメリットや効果を挙げられる手段があるのか、お伺いいたします。エコタウンしながわや日本環境経営支援機構とはどのような連携をして中小零細企業を支援されるのか、事業の展開についてお伺いいたします。","respondent":"岩崎環境清掃事業部長","answer":"たまたま、私どもがそういうふうに考えていたところに、今着々とまずは供給側の企業をリストアップするという作業を既に開始しております。そういうホームページもお持ちのようですので、そういうところと連携して、区のグリーン化支援事業ということで専門家を派遣するような。","id":"exchange-051"},{"speaker":"山路委員","kind":"質問","question":"２つ目の質問にまいります。そうすることによってＣＯ２削減が着実に進み、今後どのような判断をされていくのか、お伺いをいたします。","respondent":"岩崎環境清掃事業部長","answer":"そういう文脈で考えますと、大分ＣＯ２問題は改善するのではないかというふうに思っております。いろいろな手法があるわけですけれども、東京都でも取り組もうとしているというところの段階です。","id":"exchange-052"},{"speaker":"山路委員","kind":"提案","question":"今ご説明がありましたことを前提として２つ目の質問はクリーンエネルギーの切り札としての燃料電池の導入についてであります。いろいろありますけれども、環境清掃事業部としてどのようにお考えでしょうか、ご所見をお伺いいたしますとの意見を述べました。","respondent":"岩崎環境清掃事業部長","answer":"実際にＣＯ２をこれも発生させるわけですが、電気と比べてはるかに、４割ぐらい削減できるとも言われております。どっちかというと設備の能力というようなことをよく見きわめないといけませんので、その辺を注目してまいりたいというふうに思っております。","id":"exchange-053"},{"speaker":"山路委員","kind":"質問・要望","question":"ぜひ研究してほしいと求めましたが、小泉総理も３月、新しい首相公邸に設置したということが新聞で報道されておりました。調査をして入れてほしいと求めましたが、この点につきまして、もう一度ご答弁をお願いいたします。","respondent":"岩崎環境清掃事業部長","answer":"今言われているのが１０年間のリース料が１００万円ですので、その値段がどのぐらい安くなるか、これを見きわめたいなというふうなところが正直なところです。","id":"exchange-054"},{"speaker":"山路委員","kind":"提案","question":"３点目の質問は幾つか提案も含めてお伺いいたします。新しい事業の中でこういうアイデアを生かした取り組みをしてほしいと求めましたが、どのようにお考えか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"今後検討してまいりたいと考えています。それから、そういうこともこれは何らかの意味で必要だろうということで心がけてまいりたいというふうに考えております。","id":"exchange-055"},{"speaker":"大西委員","kind":"質問・要望","question":"しかしながら、残念ながら昨年、年末１１月でしたでしょうか、起こりました品川の女子中学生２名が逮捕されるという事件が暴力のことでございました。およそ４年生ぐらいからですから、１０年後には間違いなく２０歳から２５歳ぐらいになるわけですけれども、まさしく日本の若者を代表する子どもたち。","respondent":"古川教育次長","answer":"このように考えてありますので、全小学校でこれを実施したい、こういうことです。小学校の３年生で実施したい、こういうことです。","id":"exchange-056"},{"speaker":"大西委員","kind":"質問・要望","question":"その考えを後でお尋ねしたいのと、それともう１点が、学校と地域が結びつくことが大変重要じゃないかなと。ここで学校の職員とそして親御さんが一体となって地域に働きかけていく、ぜひ地域の皆さんで子どもたちを守ってくれないですかというお願いをする。","respondent":"古川教育次長","answer":"なお、いすを使った防御ということを現在でも進めておりまして、必ずしもさすまたによらない対応があるだろうというふうに考えてあります。","id":"exchange-057"},{"speaker":"大西委員","kind":"質問・要望","question":"私は共通の価値観というんですか、これがいい悪いは、その学校での判断だと思います。しかし、この点に関してのご答弁をちょっとほしいと求めました。","respondent":"若月教育長","answer":"したがいまして、ああやろう、そうした短期的な対応がやがて中長期的な対応に関連づけてつながっていくようなものでなければ私はならないだろう。そのとき、そのときの対応で終わってしまうんではないだろうか、こんなふうに考えているところであります。","id":"exchange-058"},{"speaker":"大西委員","kind":"質問","question":"中学生から５０円ずつぐらいでしょうか、料金を取っているということになっていると思うんですけれども、この部分を私はぜひ無料にしてもらいたい。ぜひこれは条例を改正して無料化にしてもらいたいというふうに私は考えるところですが、ご見解をほしいと求めました。","respondent":"古川教育次長","answer":"今そういう形で実施しているわけですけれども、前の決算特別委員会でもお話ししましたとおり、子どもたちが必ずしも学校単位で行くとは限らない。常設展あるいは特別展を見、この免除規定によって歴史館のほうとしては対応いたします、こういうことでご説明いたしました。","id":"exchange-059"},{"speaker":"大西委員","kind":"質問","question":"そのような解釈をしていただけることは、子どもたちにとっては大きな財産に先々なってまいるものと思います。続きまして、不登校児についてのことですが、現在、品川区で小中学生における不登校児を何名ぐらいと把握されておりますか尋ねました。","respondent":"古川教育次長","answer":"不登校児の現状ですけれども、これは平成１５年度でとらえている中ですが、小学校３７名、中学校１３７名というふうにとらえてあります。","id":"exchange-060"},{"speaker":"大西委員","kind":"質問","question":"小学生３７名、この３７名および１３７名についての教職員の面談という点について教育委員会はどのような形で把握されているか、生徒の。この辺に関しては、いかがなものか尋ねました。","respondent":"古川教育次長","answer":"先ほど申し上げました不登校という形で、ご説明申し上げましたが、その内容はさまざまです。これは今までも行ってありますし、これからも進めていきたい、このように考えてあります。","id":"exchange-061"},{"speaker":"大西委員","kind":"意見","question":"私はそういう品川モデルといいますか、虐待予防電話といいますか、そういうものを品川区が２４時間態勢でも設置する。最近どうもあそこの子どもの様子がおかしい、気軽に電話できて、この点に関しての見解を聞かせてくださいとの意見を述べました。","respondent":"新美福祉高齢事業部長","answer":"既に虐待の疑いを含めて発見された方は、地域に配備しております在宅介護支援センターにご連絡いただければ、第１次対応をいたします。","id":"exchange-062"},{"speaker":"大西委員","kind":"質問・要望","question":"この部分に私は応分の負担を求めるべきじゃないか。今度花子と太郎ですか、何か猫が２匹ぐらいいるような公園のところに返還された駐輪場がありますけれども、見解のほうはいかがか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"そういうような運動にしていこうということで取り組み始めたところで、来年度、そういう意味では武蔵小山でも予定しています。そういう意味で今後もご提案にありましたような有効な放置自転車対策につきましては我々も十分勉強しながら行っていきたいと考えているところです。","id":"exchange-063"},{"speaker":"大西委員","kind":"質問","question":"まちづくり事業部長のこの駐輪場にかける意気込み、そして成果を高く評価いたしまして、また感謝申し上げます。小学校の配食は現在２食ですが、先般アンケート等を実施したと思いますが、このアンケートの結果についてちょっとご報告をお願いします。","respondent":"山田区民生活事業部長","answer":"地域総合支援活動の一環でありますこの地域食事サービスのアンケート、昨年の１２月に実施をいたしました。受給をされているすべての方に郵送で実施をいたしまして、６３０名中回答が４７８名ということで、７５％の回答をいただいたところです。","id":"exchange-064"},{"speaker":"大西委員","kind":"質問","question":"ちょっと私の質問の仕方が悪くて。２つのアンケートだったと思うんですけれども、受給されている方からの回答率ですね、これが何名あったかというのをちょっと説明を求めました。","respondent":"山田区民生活事業部長","answer":"お尋ねの受給をされている方は２８３名おりまして、そのうち１７８名の方、６３％の方のご回答をいただいているところです。","id":"exchange-065"},{"speaker":"大西委員","kind":"質問","question":"私はこの１００名の方々がなかなか回答する能力、いろんな面、要するに郵便局に行くだとかいろんな形でのものがないんじゃないかなと。これに対する対応というのは何かされているんか尋ねました。","respondent":"山田区民生活事業部長","answer":"現在、回答を郵送という形をとりました関係で、おそらくこれは低くなっているんだろうと思うんですね。ですから、あわせて回答をいただくという手もあったかなというふうには思ってありますが、これは１つ工夫ができるかというふうに思ってあります。","id":"exchange-066"},{"speaker":"大西委員","kind":"質問","question":"しかし、そしてまた回答を寄せていないという人たちにほんとうに要らないんですかということを聞く、その点での工夫をぜひお願いしたい。三鳥、四鳥にもなるんではないかと思うんですが、この点に関しての見解はいかがか尋ねました。","respondent":"山田区民生活事業部長","answer":"いわゆる通所型については保育園でふれあい給食ということで園児との交流をしていくということを週１回から２回、現在１２園で実施をしております。","id":"exchange-067"},{"speaker":"大西委員","kind":"質問・要望","question":"西五反田のさくらハイツでしょうか、自分で調理ができない、買い物に行けないという人に対しては２食であるという私は整合性がどうもつかない。そういう点での予想される数と、それに対応するキャパシティーの問題としてはいかがなものか尋ねました。","respondent":"山田区民生活事業部長","answer":"これについてはシルバーセンターや心身障害者福祉会館など畳があるようなお部屋のほうに移動していただくということも考えてあります。こういった方々を優先的にいわゆるそちらのほうに移っていただくことなども検討しています。","id":"exchange-068"},{"speaker":"大西委員","kind":"質問・要望","question":"総体数で私はどうも不安に思うのが、おそらくかなりの人数がいて、ぜひその点に配慮いただける施策を願えればと思います。そして、この庁舎の上に日の丸がかかっておりますが、この日の丸を掲げている意味というのをちょっとお聞かせほしいと求めました。","respondent":"本間総務部長","answer":"ご案内のとおり、平成１１年に国旗及び国歌に関する法律が施行されまして、現在ではこれを根拠にきちんと掲揚しているものです。","id":"exchange-069"},{"speaker":"大西委員","kind":"提案","question":"ブルーのリボンとともに日の丸をつけてほしい。その点に関して私は拉致被害者が全部戻るまで、いかがか尋ねました。","respondent":"本間総務部長","answer":"こういう庁舎に懸垂幕を掲げるという点につきましては、国政レベルに関する問題につきましてなじまないというふうに考えてあります。","id":"exchange-070"},{"speaker":"大西委員","kind":"質問","question":"日本国民の平和、ぜひそういう拉致されている方が今まだここに存在しているということを品川区も行政として考えてほしいと求めました。私の質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"そこで質問ですが、品川区の学校給食が民間委託でこそ担っていけると判断したその理由、根拠は何でしょうか、ご説明ください。質問の２つ目は、一度に大量の学校給食をつくるわけですから、何よりも安全であることが最優先です。","respondent":"古川教育次長","answer":"そもそも品川区における給食業務というのは、保育園と学校でそれぞれ実施しております。現在も実施しているわけですが、５年前に保育園において業務代行を導入いたしました。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問","question":"戸越台中学校にしても３００食つくるわけですけれども直接その子どもたちが口に入れるものですから。このことは款別審査でも伺いましたが、明確な答弁がありませんでしたので改めて伺いたいと思います。","respondent":"本間総務部長","answer":"私ども入札を行いまして、今回の品川区としての契約は辞退したいという申し出がございまして、私どもとしてこれを受理したわけです。これは法が認めた趣旨ですので、何ら問題はないと、かように考えてあります。","id":"exchange-073"},{"speaker":"中塚委員","kind":"質問","question":"なぜかというと、今年の４月で３校、今後７年間かけて区内の５８校すべての小中学校でこの委託を進めると伺っています。この業者のことを、今回の食中毒のことを品川区が知ったのはいつか尋ねました。","respondent":"本間総務部長","answer":"すべての契約を進める上で、東京都内の事故の情報に比べまして、東京都内の事故情報を中心に調査しているというのが実態です。それから、この事実を知ったのはいつかですが、本年の３月３日、品川区のほうに連絡がございました。","id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"そこで伺いたいのは、保護者に対して業者の選定をどのように進めていると説明したのかどうか、伺います。具体的には２月８日、戸越台中学校の学校だよりで業者選定の説明箇所がありますけれども、それをぜひ一度読み上げていただいて、説明をしてください。","respondent":"古川教育次長","answer":"戸越台中学校においては２月８日付の学校だよりで調理の業務代行についてお知らせをしたところです。安定した業務が円滑に行われるよう学校と教育委員会および受注業者や給食関係者との連携を図る仕組みを検討してまいりますということでありまして。","id":"exchange-075"},{"speaker":"中塚委員","kind":"質問","question":"でも実態は、今回の業者の件はどうですか。保育園給食でほんとうに安全、衛生面が向上してきたかということを伺いたいと思います。","respondent":"青山品川区保健所長","answer":"中延保育園で平成１２年１１月２日から８日まで起こりましたＳＲＳＶ、イコールとお考えください。各区における調査を待たなければ、軽々に食中毒であるか、感染性胃腸炎であるかの判断を下すことは避けねばならないと考えております。","id":"exchange-076"},{"speaker":"中塚委員","kind":"質問・要望","question":"中延保育園の説明がありましたけれども、私が先ほど説明した教育委員会の答弁がないので、それついてきちんと答えてほしいと求めました。教育委員会は、何をもって保育園給食を安全だと判断されたのかきちんと答弁してください。","respondent":"古川教育次長","answer":"ご質問ですけれども、そっくりそのままお返しいたしますと、何をもって保育園の給食が安全ではないというふうに、その根拠を私はよくわからない。この５年間大きな問題点はないという中で、学校における業務代行は自然のなりゆきだろう、このように考えてあります。","id":"exchange-077"},{"speaker":"中塚委員","kind":"質問","question":"今回の業者は辞退となりましたが、それでは、次はどこと契約を今結ぼうとしているんですか。それも選定理由はどういう基準とどういう調査をして、よしここならいけるぞと判断されたのか、あわせて説明を求めました。","respondent":"小沼児童保健事業部長、本間総務部長","answer":"今、これは私どものほうは平成１２年１１月２７日、厚生委員会のほうへきちっと報告させていただいてあります。これは、事実にかかわることですので、この際明確に述べさせていただきたいと思います。 それと、今回事態を受けまして、入札をやり直しています。入札を再度実施をいたしまして、別の業者に内定しています。","id":"exchange-078"},{"speaker":"中塚委員","kind":"質問","question":"じゃあ、区民には報告したんですか。具体的には区報には載せたんか尋ねました。","respondent":"小沼児童保健事業部長、本間総務部長","answer":"よくお聞きいただければと思うんですが、私は平成１２年１１月２７日に厚生委員会へ報告していますというふうに申し上げたわけです。国への報告云々というのはちょっと私は理解できませんので… 契約面でのご質問の部分にお答えを申し上げます。辞退いたしました業者の後に再度入札をして内定している業者ですが、全国的に見ましても非常に多くの学校現場での実績を十二分に持っている業者です。","id":"exchange-079"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、２３区の中で学校給食を委託する前、その決定を下す前ですね、２３区の中で一体幾つの区が検討委員会を設置したのか教えてください。さらに２３区の中で学校給食が委託された学校、栄養士の配置基準を説明を求めました。","respondent":"青山品川区保健所長、古川教育次長","answer":"これを広報に、要するに都に報告したとしましても、東京都はそこの場で広報することはありません。しかしながら、それぞれのところで次の起こさないための注意を喚起する意味で… ２３区のことを取り上げるつもりはあまりないわけなんですが、ほとんどの区では、多分検討委員会を設置したというふうに伺っています。こう思っていますので、それが学校でできない理由は１つもありません。","id":"exchange-080"},{"speaker":"中塚委員","kind":"質問","question":"そもそも教育次長は学校給食の状況をきちんとご存じなんでしょうか。熟練するには何カ月ぐらい必要だと思っていますか、説明を求めました。","respondent":"古川教育次長","answer":"保育園は、１日８時間を超える、場合によっては延長夜間保育も含めて十数時間にわたる中で食事を提供する。考えるまでもないわけでして、学校における短時間に労働力を投入するこの業務こそ民間への業務代行にふさわしい、私はそう思っております。","id":"exchange-081"},{"speaker":"中塚委員","kind":"質問","question":"なぜ品川区は栄養士を配置しないんですか。隣の目黒区に話を伺ったところ、委託が決定した１年前には栄養士を張りつけて、それで行っていると言いました。","respondent":"古川教育次長","answer":"検討委員会を設けるということは少なくとも保護者の立場の方からは１回も伺っていません。栄養職員については２校に１人の体制で何ら変わることなく今までと同じ安心、安全な給食は提供できる、このように考えております。","id":"exchange-082"},{"speaker":"中塚委員","kind":"意見","question":"戸越台中学校に至っては、２月に発表して４月に実施。なぜ子どもたちがおいしいと評判の学校の給食を変えなければならないのか、私は今までどおり直営を存続すべきだと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"南委員","kind":"質問","question":"国を挙げて法整備と、そして諸施策が取り組まれておりますけれども、私はその中の１つとして保育所の充実も欠かせない条件だと思います。そこでまず、品川区が保育行政を進めておりますけれども、保育園の役割というのは何と考えていらっしゃるのか、伺いたいと思います。","respondent":"小沼児童保健事業部長","answer":"日々保育にかけるお子さん、子どもを預かり、健全育成に努める。これが保育園の通例の一番の骨格です。","id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"しかも専門性が求められるというところは、そういう状況にもかかわらず、品川区は保育園職員を行革で削減し続けてきました。標準的な保育園で、職種ごとにどれだけの人数が減ってきているのか、そして区はそういう事態に対してどういう認識を持っていらっしゃるのか伺います。","respondent":"小沼児童保健事業部長","answer":"これはすべて正規の数でお考えいただければと思います。これにつきましては正規の職員が１９名というような状況ですので、その差が約９名ほど適正化している、こういうふうになってあります。","id":"exchange-085"},{"speaker":"南委員","kind":"質問・要望","question":"特例、長時間保育をやっているわけですから。そういうところをフォローするのに、どういう体制をとっているんか尋ねました。","respondent":"小沼児童保健事業部長","answer":"ものの一番の考え方と、今までのような形で必ずしもすべて複数担任あるいはそれに近い形というようなことをしてございません。まさに時代背景として生きた保育というようなことで実態に応じて職員を配置してこなしているというのが私が知る限りの実情です。","id":"exchange-086"},{"speaker":"南委員","kind":"質問","question":"そこは忘れてほしくないというふうに思うんですね。その点については、いかがか尋ねました。","respondent":"小沼児童保健事業部長","answer":"従来のような処遇のやり方あるいは育成の仕方と現実の保育園での子どもの処遇なり親への対応ではにっちもさっちもいかないというようなことで。","id":"exchange-087"},{"speaker":"南委員","kind":"質問","question":"それをフォローをするためにどういう体制をとっているかというと、答弁がありませんけれども、非常勤職員を多用しています。１日の保育時間の中で、どういう配置をしていくというふうに考えているんか尋ねました。","respondent":"小沼児童保健事業部長","answer":"〔「配置について答えてない」と呼ぶ者あり〕 ３時間のあるいは配置というのは各園の園長のほうがその現場の状況を見て配慮するわけですから。そういうことです。","id":"exchange-088"},{"speaker":"南委員","kind":"質問・要望","question":"聞いてもいないことを長々と答弁していただきましたけれども、児童保健事業部長のほうは、いいですよね、時間のカウントはないんですから。私は３時間の非常勤職員の配置について伺ったのは、そのことをちゃんと答えないと次の質問に行きませんのでお願いします。","respondent":"小沼児童保健事業部長","answer":"朝１０時半等々で一斉保育あるいは当日のものをするときに、入れる場合もあれば、それから午後の合間を見て入れる場合もある。その３時間非常勤をどう配置していく、現場の園長のほうの裁量に任されている、こういうことです。","id":"exchange-089"},{"speaker":"南委員","kind":"質問","question":"そして子どもの発達を保障するとしている品川区はそこをどういうふうに見たらいいんでしょうか。その点については、どういうふうに考えるのか、伺います。","respondent":"小沼児童保健事業部長","answer":"その辺のところはその辺のところで、やはりご評価いただきたいと思います。もしそういう点でるる問題があるということであれば、少なくとも私のところには、今委員がおっしゃられたような話というのは寄せられてございません。","id":"exchange-090"},{"speaker":"南委員","kind":"質問・要望","question":"児童保健事業部長はそこまでリサーチしていないんじゃないでしょうか。そういう点から、非常勤の職員配置では子どもの発達は保障できないということを強く申し上げておき、強く改善を求めたいと思います。","respondent":"本間総務部長","answer":"それから今回、７時間の非常勤を勤務時間が変わることに伴いまして、個別ご相談を人事課のほうで受けてあります。これは個々いろいろな事情を抱えておりますので、懇切丁寧にご相談あった方には応じているです。","id":"exchange-091"},{"speaker":"南委員","kind":"質問","question":"したがって、個別にとおっしゃいましたけれども、やはりきちんとフォローをしていけるように改善方お願いしたいと思います。品川区は３年間で２７％、これは撤回をするべきじゃないかなというふうに思いますので、改めてこの点についての答弁をお願いします。","respondent":"小沼児童保健事業部長","answer":"保育料の問題ですけれども、撤回については考えてございません。","id":"exchange-092"},{"speaker":"南委員","kind":"意見","question":"一緒に聞けばよかったんですけれども、定率減税が縮小廃止されることによって増税にならざるを得ない。これについては当然保育料は上がるわけですけれども、ここについてはどういうふうに考えていますかとの意見を述べました。","respondent":"小沼児童保健事業部長","answer":"私どもが今採用しております徴収基準の考え方ですが、今申し上げている定率減税の場合もあるということに結果としてはなります。ですから、その税制の転用をやめる、私どもは一番これがオーソドックスな公平性を担保する考え方だというふうに検討の結果としては出てありますので。","id":"exchange-093"},{"speaker":"南委員","kind":"質問・要望","question":"児童保健事業部長は国の動きを調査していらっしゃらないんでしょうか。さらに、品川区は１園また増設させるわけですから、こういう部分への負担軽減もするべきだというふうに思っておりますが、いかがか尋ねました。","respondent":"小沼児童保健事業部長","answer":"今の時点で別途保育料を補助するとか、それを別途私どものほうが負担するというふうなことは考えてございません。むしろ、私はそれが認証保育所なり、新しい保育所として、今後、不動磐石な経営基盤をつくるものだというふうに信じてあります。","id":"exchange-094"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、経済的負担をほんとうに区民の方々が軽減を求めていらっしゃる、ここにこたえているものだというふうに１つは思うわけで。区の認識は、さっき私はＭ字型というふうに申し上げましたけれども、どういうふうにとらえていらっしゃるか尋ねました。","respondent":"本間総務部長","answer":"女性の就労に対する意欲ですが、先般私どものほうで人権にかかわる意識調査を実施いたしました。２番目が結婚や出産にかかわりなく一生職業を持ちたいというのが２割５分弱、このような結果になってあります。","id":"exchange-095"},{"speaker":"南委員","kind":"質問","question":"品川区だって、そういう少なくとも４割になるように、区民を挙げてそういう体制をとるというのはほんとうに必要なんじゃないでしょうか。あわせてで伺うわけですけれども、今後の保育需要、そして待機児解消策を伺いたいと思います。","respondent":"小沼児童保健事業部長","answer":"ですから、そういうところを１つ見まして、保育需要をつかんで、的確に適正にやっていきたいというふうに考えてあります。保育所が必要であれば、それを呼びかけて誘導していくというようなところをミックスしながら待機児の解消には努めていく、こういう考えです。","id":"exchange-096"},{"speaker":"南委員","kind":"質問","question":"ですから、そういう子どもをいっぱい増やしてください。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"特に今回、それから本格的に教育改革について平成１８年度から一貫教育が始まるわけですけれども、これらについて総括的に質問をしたいと思います。今高齢化社会における中で、なぜこのように強気の予算化をされているのか、その辺をお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"この１０年ぐらいの間に人件費のほうでも先ほど発表になりましたけれども、８６％ぐらいから大体６６％までこういうふうに下げてきている。こういうようなことがありますので、一言で言えば、やる気に裏づけられた予算を今回も組んだ、こういうことです。","id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"保育の質というのはどういうことを見ていけばいいのか、職員数で保育の質が語られるのだろうかということが非常に疑問を持ちます。一体品川区で考えている保育の質、それから幼児教育という考え方についてご答弁をお願いしたいと思います。","respondent":"小沼児童保健事業部長","answer":"一番大もとになります保育所の保育指針あるいは幼稚園の教育要領の中で明確に質についての定義あるいは定めているのはございません。こういうことになろうかと思います。","id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"保育の質、この定義がなかなか難しいというところではありますが、ではこの品川区で行われている保育サービス、いろいろあります。先ほど言われました保育の質というのはどういうふうになっていくのか、保育の質に関しては多少の影響があるのかどうか、その辺はいかがか尋ねました。","respondent":"小沼児童保健事業部長","answer":"実は明日、文部科学省のほうで私どものほうの学務課長と保育課長が全国の講師になって、品川区の取り組み方をるる話す予定になってあります。","id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"保育の質も担保しているということのあらわれだと今ご答弁いただきましたが、それにあわせて今後幼保一元化という考え方が出てきました。品川区で目指す幼保一元化というものはどういうものなのか、品川区の子どもたちがどうあるべきなのかという視点についてはいかがか尋ねました。","respondent":"小沼児童保健事業部長","answer":"子ども像と目指す一元化という考え方ですけれども、そのためのいろいろな育成の仕方あるいはプログラムなり指導なり方法ということを考えていく。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問","question":"なぜ幼稚園から、今の保育園と幼稚園の違いをどういうふうに統合して総合施設という考え方に持っていこうとするのか、その辺ご答弁をお願いいたします。","respondent":"高橋区長、小沼児童保健事業部長","answer":"それから、ぷりすくーるも実施をいたしました。それを品川区が勇気を持って実施をしていこう、それから台場の幼稚園にそれぞれモデルをつくって平成１７年に実施をしてみて、その結果によって。プロの世界では悪魔の２歳児とか、系統的な状況がこの間例えばすこやかならすこやか園で実施してみて非常によくわかりましたということであれば。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"就学前教育も含めて、子どもたちがどうあるべきかという視点での幼保一元化を推進ということがよく理解できたかと思います。もう６年目をしていると思いますが、前からも非常に危惧するというふうに私のほうで質問をしているところではありましたが、それはいかがか尋ねました。","respondent":"小沼児童保健事業部長","answer":"私どものほうが夜間保育実施園の園長あるいは職員を通じて調査を２カ月ぐらいになりましょうか、３カ月ぐらいになるのかな。このことが続くことによって、やはり品川区の夜間保育というのはいい結果が出てくるんじゃないかというふうに、これは自負しています。","id":"exchange-103"},{"speaker":"西本委員","kind":"確認","question":"もう一度確認をしますが、今どういう現状になっているのか、かなりのスピードで増えている現状ではないだろうか。それは利用する、果たして子どもたちにとってどうなんだろうかという視点に立ったときに、延長保育の考え方はいかがになりますか尋ねました。","respondent":"小沼児童保健事業部長","answer":"それから、拡大ですけれども、私どもとしましては、これはむやみやたらに拡大するという考え方はございません。何でもかんでも１０時まで、こういうようなことについては厳に慎んでいきたい、こういうふうに私のほうとしては考えてあります。","id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"ほんとうに子どもたちの利益はどういうことなんだろうかということを見据えて、政策展開をしていただきたいというふうに思います。なれれば非常に子どもたちも多いですから楽しく遊べる環境ではありますが、今、子どもたちの視点からどういうふうに考えられますか尋ねました。","respondent":"小沼児童保健事業部長","answer":"見る限り、あまり１０人中パニック、あるいはなかなか親御さんから離れないというような例はそうございません。ただ、これは厳に直していかなくてはいけませんし、本来の趣旨とか目的に沿う形で整理していきたいというふうに思ってあります。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば保育園のほうではファミリー・サタディ子育て体験等々をしているわけですから、そこを踏まえて預かりをする。次に病時保育の件でご質問いたしますけれども、この病時保育を今後どういうふうに品川区で進められようとするのか、その辺はいかがか尋ねました。","respondent":"小沼児童保健事業部長","answer":"この２月から本格的に実施をしたわけですけれども、拡大していく、あるいはもっと延ばしていくというようなことは考えてございません。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"むしろ、それを推進するということをぜひ品川区としても進めてほしいと求めました。今後、保育園ＰＴＡの流れをどういうふうに考えられているのか、それについてお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"平成１７年度で一応設置完了というような見込みですので、４月以降今まで積み上げてきたもの、こんなようなことを今考えているさなかです。","id":"exchange-107"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、それを軸に子育ての輪が広がればいいかなというふうに非常に望んでいます。これは要望ですが、させていただきたいというふうに思っておりますが、どのようにお考えになりますか尋ねました。","respondent":"小沼児童保健事業部長","answer":"あるいはこういうふうに共同的なものを、ひな型というんでしょうか、そういうようなものをつくって対応していきたいというふうに今は考えてあります。","id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"いろいろな形ができるかと思いますので、ぜひ親のつながり、自主的な行動がとれるようにお願いしたいと思います。そういう意味では、保育園として児童相談所の機能をどういうふうに今後考えていくのか、その辺のお考えをお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"今後は児童相談所が今まで持っていた就学前、未就学児、あるいは乳幼児のかかわり方の業務というのが幾つかあります。今後私どものほうで取り組む、保育園現場と、利用しやすさというようなことで取り組んでいきたいというふうに今は考えているところです。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"では、次に特別支援教育についてご質問したいと思います。特別支援教育という言葉、それから制度、これがまず、なぜ今特別支援教育を必要とされるのか、その経緯も含めてご答弁をお願いしたいと思います。","respondent":"古川教育次長","answer":"もう２年前でしょうか、平成１５年３月に国の１つの報告の中に今後の特別支援教育のあり方という中でその辺が明らかにされてまいりました。","id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"具体的なところでお聞きいたしますが、固定学級、それから通級指導学級で行われておりました。この特別支援教育を導入されますと、今後、心身障害学級はどのようになっていくのか、これらの関係についていかがか尋ねました。","respondent":"古川教育次長","answer":"これはすべての学校の中で、そういう児童、お子さんに対して特別支援教室をつくりながら対応していく。このように考えてあります。","id":"exchange-111"},{"speaker":"西本委員","kind":"確認","question":"もう一度確認をしますが、そのＡＢＣのタイプが相互に発展していくというふうに考えていくべきなのか、その辺の関係性はいかがか尋ねました。","respondent":"古川教育次長","answer":"先ほど来特別な支援の必要なお子さんに対する１つの教育的ニーズにこたえるというのがこの特別支援教育のそもそもの考え方でありますけれども。こういう考え方は必要だろう、このように考えてあります。","id":"exchange-112"},{"speaker":"西本委員","kind":"質問","question":"今改築されている学校の図面を見ますと、特別支援教室というのが配置されているわけですけれども、これは改築以外の学校でも今後整備されていくのではないかなというふうに考えるわけですが、この特別支援教室の利用の方法というのはどのように考えていかれるのか尋ねました。","respondent":"古川教育次長","answer":"特別支援教室の中での事業の形態ということになろうかと思いますが、そういう達成感を通常の学級とは違う、この特別支援教室の中で行っている。こういうことをイメージしております。","id":"exchange-113"},{"speaker":"西本委員","kind":"質問","question":"そうすると、その特別支援教室というあり方は、固定的に考えるのではなくて、子どもたちの状況に合わせて、またクラスの状況に合わせて利用してくるんだという、そういう考え方でよろしいのか尋ねました。","respondent":"古川教育次長","answer":"これはそれぞれ先ほど来申し上げておりますような発達に障害のあるという一言の中では言いあらわせない状況だと思っています。特別支援教室というものはその学校の中にあえて設置される状況にはないと思いますが、特別支援教室というものを学校の中に当然に設けながら。","id":"exchange-114"},{"speaker":"西本委員","kind":"質問","question":"そうしますと、その中で非常に重要になってきますのは、この特別支援教室で指導する専門的な方ですね。普通の教員も含めまして、この専門性に対してどういうふうに確保していくのか、その考え方はいかがか尋ねました。","respondent":"古川教育次長","answer":"実は本年度、特別支援教育のための検討委員会を設けながら計４回にわたってさまざまな角度から検討いたしました。その検討の結果を踏まえて、平成１７年度に特別支援教育検討委員会のもとに巡回相談チームというものを編成しようと思ってあります。","id":"exchange-115"},{"speaker":"西本委員","kind":"意見","question":"そういう誤解されやすい状況でもあるわけですが、この地域やそれから保護者の方々の理解が非常にこれから重要になってくると思われます。啓発活動については、どのように今後展開していこうとされるのか、その点についてご答弁をお願いいたしますとの意見を述べました。","respondent":"古川教育次長","answer":"しかしながら、この問題につきましては、一方ではまだまだ十分に認識されていない面があるのも事実だろう、こういうふうに考えてあります。","id":"exchange-116"},{"speaker":"西本委員","kind":"質問","question":"品川区の教育改革プラン２１が始まりまして５年ぐらいでしょうか、たったと思います。教育改革プラン２１を推進しようと考えたのか、その目的を改めて今の時期だからこそちょっとお聞きしたいというふうに思いますが、いかがか尋ねました。","respondent":"若月教育長","answer":"こう考えたわけであります。そんな意味から、プラン２１と称しまして、教育改革の緒についたのが５年前、こういうことです。","id":"exchange-117"},{"speaker":"西本委員","kind":"質問","question":"ともすれば、学校改革、そういうとらえ方でいいのだろうかというふうに疑問に思うことがあります。それと、５年改革をした中で、その効果はどうだったのか、教師の意識は変わったんだろうかというその点についていかがか尋ねました。","respondent":"若月教育長","answer":"には先生方のものの考え方や習慣、そのための手段の１つとして学校選択制があり、さまざまな施策がある。これも成果の１つだと認識をしております。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"これからさらに改革を進めていただきたいなというふうに考えるわけですが、その中で、平成１８年度より大阪地区で小中一貫校が開校されます。なぜ教育改革で一貫教育なのか、その考え方はどういうふうに考えればよろしいんか尋ねました。","respondent":"若月教育長","answer":"中学校は中学校だけで別々に先生方が別々の考え方を持って指導をされている、これは今の子どもたちの学びや成長の実態に合っていない。そこを認識し、ほんとうの子どもたちの９年間の全人的な成長が実現できる、これが小中一貫教育を全区展開する考えに至った背景です。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"これは何回も委員会のほうでもお聞きしていますので、小中一貫した教育をしていくべきだというところで、つくりかけているというところだと思います。この品川区の教育改革プラン２１のゴールは何なのかなというところになりますが、教育委員会として、ビジョンについてお聞きしたいと思います。","respondent":"若月教育長","answer":"やはり独自性のみずからの頭で考え、これがこれからの日本の公立学校の目指す方向性ではないだろうか、こう思っているところです。まさに今やっている改革は、そのトレーニングの一環である、こういうふうに考えております。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"ではもう一度お聞きしたいと思いますが、品川区の教育というのの目的ですね、その手段としては教員の意識改革というのはわかりました。ただ、子どもたちにとって、どういう品川区の教育であるべきかというところの考え方、展望、それをお聞きしたいと思います。","respondent":"若月教育長","answer":"一言で申し上げます。区民から信頼される学校にしたい、それだけです。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に区長のほうからもご答弁ほしいと求めましたが、では、子どもたちの教育をどういうふうに考えていくのか、品川区の教育に関して一言お願いしたいと思います。","respondent":"若月教育長","answer":"個と公共とのバランスのとれた子どもたちを教育していきたいな、育てていきたいなと、こんなふうに思っております。","id":"exchange-122"},{"speaker":"西本委員","kind":"意見","question":"ぜひその意気込みで今後も品川区の改革をお願いしたいと思います。これで総括質疑を終わりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-123"},{"speaker":"三村委員","kind":"質問・要望","question":"私たちは今まさに急な坂を落ちようとするジェットコースターのような状態ではないでしょうか。待ったなしの少子化対策が求められると考えますが、品川区における少子化対策に対する今までの取り組みと今後の方針について説明を求めました。","respondent":"中尾根企画部長","answer":"こういう方針をとってございまして、それから２つ目には明るく成長できる環境づくりということで、幼保一元化のそういう施策です。それと３つ目は社会が対応協力する環境づくりということで、地域における子育て環境への総合的な支援、こういうのが当面の方針です。","id":"exchange-124"},{"speaker":"三村委員","kind":"意見","question":"倒産やリストラなどが当たり前となっている現状においては、その１割の人でさえも安心して子育てに専念できる環境ではないと言えます。こういった考え方も含め、企業による仕事と家庭に配慮した働き方の推進に対する品川区のお考えを説明を求めました。","respondent":"中尾根企画部長","answer":"３月１９日の毎日新聞では、東京労働局のアンケートでは９割の企業がそうした策定を既に終了しているという報道がありました。区といたしましても、できる限り区としてできる行為の側面はしていきたい、このように考えてあります。","id":"exchange-125"},{"speaker":"三村委員","kind":"意見","question":"正社員からパート労働への変更は、生涯賃金において１億８,０００万円もの損失を生むとの厚生労働省の試算もあります。品川区における待機児ゼロ実現のための取り組みについてお答えくださいとの意見を述べました。","respondent":"小沼児童保健事業部長","answer":"その他弾力化だとか、あるいは認証保育所の開設というようなことで１０７名の確保をしていくというようなことを考えてあります。それから、約１３０名ぐらいを定員増で増設できるような形になってくるんではないかというようなところで今取り組んでいるさなかです。","id":"exchange-126"},{"speaker":"三村委員","kind":"質問・要望","question":"入園基準を広く公表し、時代の変化に柔軟に対応していくよう求めますが、品川区のお考えをお聞きします。今後、品川区として、認可外保育園利用者への支援をしていくべきだと考えますが、お考えをお聞きいたします。","respondent":"小沼児童保健事業部長","answer":"重要事項の説明というのが今後大きなものになってまいりますので、見直しについては今後取り組んでまいりたいというふうに思っているところです。","id":"exchange-127"},{"speaker":"三村委員","kind":"質問","question":"ここの層に対する品川区の福祉というのはどうしてもまだ落ちてしまっているというふうに私には感じられます。ここの一番支援の必要な層に対する品川区の支援としては、今後どのようなことを考えているのか、お聞きをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-128"},{"speaker":"三村委員","kind":"質問・要望","question":"質問の内容を明確にします。ぜひ利用する立場に、今後支援を検討してほしいと求めましたけれども、お答えのほうを。","respondent":"小沼児童保健事業部長","answer":"先ほど来も申し上げましたけれども、認可外保育施設につきましては、支援云々というのは考えてございません。１つには品川区としての補助には適さないというふうに考えてありますし、私ども相当苦慮した、認可外云々ということでの補助は考えてございません。","id":"exchange-129"},{"speaker":"三村委員","kind":"質問・要望","question":"は、そちらでは東京都の支援を得てやっている事業でありますから、認証保育所利用者への支援というのもぜひご検討ほしいと求めました。要望として申し述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-130"}]},{"id":"topic-02","title":"質疑を終了いたします。 以上で平成１７年度品川区各会計予算についての質疑はすべて終了いたしました。 着席のまま、しばらくお待ちください。 次に、第５号議案…","agenda":"質疑を終了いたします。 以上で平成１７年度品川区各会計予算についての質疑はすべて終了いたしました。 着席のまま、しばらくお待ちください。 次に、第５号議案…","exchanges":[{"speaker":"宮崎委員","kind":"提案","question":"ここ数年の区内の年間出生数は２,３００人から２,４００人という状況ですから、予算の策定に当たって２,５００人を想定いたしました。何卒ご賛同いただき、ご決定いただきますようお願いいたしまして、提案説明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-131"},{"speaker":"石田委員","kind":"質問・要望","question":"休憩していただいて、理事会を開いていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"田中委員","kind":"質問・要望","question":"このような質疑が行われたということから、三村委員の発言のうち、議会改革に関する議事録のすべてを削除することを求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-133"},{"speaker":"三村委員","kind":"質問","question":"今回の予算に対して、区長のご意見をお伺いしたいということで、今回この問題を取り上げさせていただきました。なので、予算に対しての質疑ということでさせていただきましたので、削除の件についてはお受けできないというふうに表明します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-134"},{"speaker":"原委員","kind":"提案","question":"平成１７年度品川区一般会計予算、および共産党単独提案、平成１７年度品川区一般会計予算修正案についての我が会派の意見を表明いたします。自由民主党品川区議団との連携をなお一層深めていただくことを要望し、共産党単独提案平成１７年度品川区一般会計予算修正案には反対しとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-135"},{"speaker":"中島委員","kind":"提案","question":"社会全体での子育て支援という観点からさまざまな政策提案をしており、区でできることは最大限努力され、部分的な修正案には反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-136"},{"speaker":"高星委員","kind":"質問・要望","question":"課題である財政自主権確立を求めつつ、２１世紀のあるべき品川区像およびその具現化を求める第三次長期基本計画。本予算委員会を通じ、生かしていただきますよう要望いたしまして、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-137"},{"speaker":"沢田委員","kind":"質問・要望","question":"トンネル内の排ガスを２４時間フィルターなしに換気塔から放出、品川線の交通量は現状の２.２倍にもなるのにどうして環境は改善されるのでしょうか。改憲が俎上に上っているときにどうするべきなのか、国民的討議こそ今求められているのではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"藤原委員","kind":"提案","question":"平成１２年改革の真価を実現し、品川区の新たな自治権確立と正常な都区制度関係確立のため、断固たる施設を貫くことを強く要望します。最後に我が会派委員が提案、要望した各項目につきまして積極的に受けとめていただきとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"井上委員","kind":"提案","question":"教育改革プラン２１で進めている小中一貫教育の導入は、教職員、保護者、当事者に品川の教育改革像の内容を周知し、理解を求めていくことが必要です。以上、生活者ネットワークの提案が今後の区政に反映されるよう要望し、意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-140"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/330368?Template=document&Id=852#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":129078,"voices":314}},{"id":"h17-20050412-6","meetingId":"h17-cm04","date":"2005年4月12日","dateIso":"2005-04-12","committee":"区民委員会","time":"午後１時０３分～午後２時５５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"最初に品川区「春の地域安全運動」","agenda":"最初に品川区「春の地域安全運動」","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"ちょっと質問させていただきたいんですが、春の地域安全運動で、それに関すること、例えば振り込め詐欺被害の防止とかなんですが、例えば品川区のホームページ上などではそういう告知ですとか広報活動というのはやられるのかやられないのか説明を求めました。","respondent":"金子生活安全担当課長、田村地域活動課長","answer":"本件に関しましては、この期間にかかわらず検討していきたいと考えています。 では、私の課の話なので私からお答えします。それぞれ所轄の警察との連携が必要なので、掲載してかなり周知をしていきたい、そのように考えております。","id":"exchange-001"},{"speaker":"山村委員","kind":"意見","question":"私が言いたいのは、こういう期間だけ、例えばホームページ上で一番最初のページとかでもっと目立ちやすく、普段とは違って、その期間だけでもアップの仕方を変えるような工夫をなされたほうがいいんじゃないかということを聞きたいんですが、そこでやられているかどうかとの意見を述べました。","respondent":"田村地域活動課長","answer":"やっぱりトピックス的な問題なので、一番最初の画面に期間限定ですけれども、現在は載せてはいませんので、載せる形で検討してまいりたいと、そのように考えております。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"初めに、やはり金子生活安全担当課長も警視庁からお見えになっているんか尋ねました。","respondent":"金子生活安全担当課長","answer":"４月１日に着任したわけですが、それ以前は警視庁の四谷警察署のほうの生活安全課長をやっておりました。","id":"exchange-003"},{"speaker":"藤原委員","kind":"確認","question":"現時点でも４つに関して目標としてやっていかなければならないということはわかるんですが、あとＣＭ等でも振り込む前にもう１回確認とか、現時点でもまだこの詐欺事件というのは減っていないんか尋ねました。","respondent":"金子生活安全担当課長","answer":"品川区については４３件の８,７００万円です。４億５,０００万円、品川区のほうでは１４件２,０４７万円ということで、依然として振り込め詐欺等の被害実態は増えているです。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"そういうお答えが来るんですけれども、こういう露骨な今振り込め詐欺とかの詐欺事件のようなのは、やはり所轄警察に相談するしかないんでしょうか。そういうふうに一番住民に近い自治体としても、窓口として相談に乗ってあげるというようなことは品川区としてはしていくつもりはないんか尋ねました。","respondent":"田村地域活動課長","answer":"もうご存じだと思いますが、はがきで脅しまがいの、ご自宅あるいは勤め先に行って振り込まない場合にはというはがきが実際に幾つかの例であります。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"４番の品川区の取り組みということで、１番目、２番目あたりは場所は特定されているんですか。全体的にまわるということか尋ねました。","respondent":"金子生活安全担当課長","answer":"４番目の１の生活安全パトロール隊については全域を実施いたします。それと２つ目のポスターによる周知活動につきましても全域です。","id":"exchange-006"},{"speaker":"山路委員","kind":"意見","question":"ただ決まったとおりにやられるのかどうか。それを説明してもらえますかとの意見を述べました。","respondent":"金子生活安全担当課長","answer":"そういった要望等がありますれば、そこを重点的なパトロール広報等を実施したいと思います。いわゆる空き巣につきましては、薄暮帯、そういったところも参考にして今後パトロール等を実施したいと思ってあります。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"では、先ほど言われた相談と同じですけれども、生活安全担当にご連絡しますと、何日にチラシを配ってやるとか、そういうことも可能だと考えていいわけか尋ねました。","respondent":"金子生活安全担当課長","answer":"そのとおりです。具体的にそうした話もあります。","id":"exchange-008"},{"speaker":"山路委員","kind":"質問","question":"この期間外になるかと思うんですけれども、生活安全担当のほうに相談すれば、いろいろ対応は可能でしょうか。警察の範囲じゃなく、対策としていかがか尋ねました。","respondent":"金子生活安全担当課長","answer":"被害実態等につきましては、警察署との連絡もありますので、こちらで承って、また警察署との連絡を密にして対応していきたいと考えております。","id":"exchange-009"},{"speaker":"原委員","kind":"質問・要望","question":"１つだけちょっと確認をさせていただきたいんですが、例えば町会をターゲットなんでしょうか、そこをターゲットにしているんですか。テーマの話とちょっと違いますけれども、町会にそれだけの負担を負わせようとしていらっしゃるのか、そこのところもちょっと確認させていただきたい。","respondent":"田村地域活動課長","answer":"やはりこういう活動を実施して、全体で犯罪件数、例えばひったくりだとかを含めまして５,８０７件年間です。若干先ほど担当課長のほうからご説明ありましたけれども、できるだけ負担のかからないような取り組みにしていきたいというふうに思っております。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"わからなくもないんですが、今のお話の中にも地域が町会を限定しないんだというようなお話のようですから、あまり負担の高い。人数的なものがどうのと細かいところは別として、いらっしゃるのかなというふうに思うんですけれども、わかりますか尋ねました。","respondent":"金子生活安全担当課長、山田区民生活事業部長","answer":"ボランティア活動の一環としまして、我が町パトロール、これはたくさんの参加がありまして、月３回をベースにそれぞれ実施しております。防犯協会等の活動につきましては、ちょっと今手持ちの資料はございませんで、申しわけございませ… ４署の警察署の生活安全担当課長、その中で今年度こういうテーマでこういうふうに進めていこうと共通認識のもとにやっていこうというふうにはなっているんですけれども、後ほどご報告させていただきたいと思います。","id":"exchange-011"}]},{"id":"topic-02","title":"平成１７年度品川区中小企業事業資金融資あっ旋制度","agenda":"平成１７年度品川区中小企業事業資金融資あっ旋制度","exchanges":[{"speaker":"山村委員","kind":"質問","question":"環境対策資金のところにあります低公害車の導入のところでご質問するんですが、これは低公害車の範囲というのは、大体どこからどこら辺までと考えていらっしゃるのかちょっと伺いたい。","respondent":"金子産業振興課長","answer":"低公害車の対象範囲ですけれども、これにつきましては、いわゆる低公害車として販売されております電気自動車、ハイブリッド自動車あるいは天然ガスを使用した自動車等、環境にいわゆるやさしいと言われているものを中心に考えているところです。","id":"exchange-012"},{"speaker":"山村委員","kind":"質問","question":"仕事に使うのかどうかあやふやな部分はあるとしても、融資ですか、広報する気があるのか。ほんとうにやるんだったら、例えばトヨタの販売店と連携したほうが確実にできるものですから。","respondent":"金子産業振興課長","answer":"私どもこの事業資金の融資というのはあくまでも中小企業の事業の支援のために実施しているものですから、活動は考えているところではございません。それからもう１点は、この段階で幾らというふうには申し上げ切れないということでご理解いただきたいと思います。","id":"exchange-013"},{"speaker":"山村委員","kind":"質問","question":"ただハイブリッド車を市販しているメーカーが少ないものですから、自動的にトヨタかホンダになってしまう部分はあるとは思っております。これは仕事兼自家用の場合も融資されるのかどうか、どこら辺まで厳しく基準を設けているというか、考えられているのか教えてほしいと求めました。","respondent":"金子産業振興課長","answer":"私どもとしては融資をするわけにはいきませんので、提出されている事業資金の内容について、きちっと吟味した上で融資のあっ旋については決定していきたいというふうに考えてあります。","id":"exchange-014"},{"speaker":"山村委員","kind":"質問","question":"例えば自分のうちで工場を持っているような場合に、それで、どうしても自家用と兼になる場合がいろいろ出てくると思うんです。どうしても自宅兼ということが多くなってくる場合があるとは思うんですが、それとも時と場合によっては融資するのか教えていただくとうれしいです。","respondent":"金子産業振興課長","answer":"これが自家用に使われるようなものであれば、本来融資をすべきものではないというふうに考えておりますので、その辺については事業計画を精査するときに厳密に精査すべきものというふうに考えてあります。","id":"exchange-015"},{"speaker":"山村委員","kind":"確認","question":"そうすると、例えば自家用に使っていることが確認された場合は、何かそれ相応の措置をされるのかどうか、教えていただけますか。","respondent":"金子産業振興課長","answer":"山村委員ご指摘の、もし万が一そういうケースがあった場合には、もちろん先ほどから申し上げているとおり事前に十分なチェックはするという考えでおりますが、個別のケースにつきましては対応を検討した上で、あるべき対応をしていきたいというふうに考えてあります。","id":"exchange-016"},{"speaker":"山路委員","kind":"質問","question":"その助成の兼ね合い。例えば１００万円かかるときに、助成を受けて、その残りを融資を受けるという方法でもいいのか、それとはまた別なものなのか教えていただけますか。","respondent":"金子産業振興課長","answer":"委員のご質問は他の助成事業との関係ですけれども、私どもこの融資につきましては助成の部分というのは当然融資の対象にはならないというふうに考えていますので、その辺におきましては、その助成以外の部分について対象というふうにご理解いただきたいと思います。","id":"exchange-017"},{"speaker":"山路委員","kind":"意見","question":"の残りをここで融資を受けられるのか、１００万円を借りなきゃいけないのか、１００万円を借りるのか、その辺を。ちょっとわかりづらいので明確に説明を求めました。","respondent":"金子産業振興課長","answer":"ちょっと説明が不十分だったと思いますが、あるいはあるものについては３分の１助成するとかというふうな考えがあろうかとは思います。保証料の２分の１を助成するというものですから、同じ対象のものについて助成と融資というものは対象にならないというふうに考えてあります。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"１番の協定利率なんですけれども、金融機関から課長のご努力かもしれないんですけれども、下げてもいいよという話があった。別に下げてくれなくてもいいのに金融機関との協議の中で下げてくれたわけですけれども、これはまず１点はなぜこの時期に下げてくれたんか尋ねました。","respondent":"金子産業振興課長","answer":"昨年の８月あたりに山がありまして、それ以降、多少の波はありつつも低下傾向にあるというふうに私どもは認識してございました。それで、そういう認識のもとで金融機関と協議した結果、下げてもいいというお話をいただいたので、０.１％下げたわけです。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"平成１７年度のこのチラシをいただいたんですけれども、利率等の変更はあっても、中身がそんなに変わっていないと思う。保証料の補助２分の１とか３分の２というふうな形でずっと今までやってきたと思うんですけれども、金利負担を、会議の中とかで出てくるんか尋ねました。","respondent":"金子産業振興課長","answer":"それについては金融機関はみずからの責任を持って対応する、そういう意味では違う趣旨のもの、違う意味合いのものかなというふうに考えてあります。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"保証協会のことでちょっとお伺いしたいのは、わかる範囲で結構なんですが、保証協会が融資をする保証対象業種でない業種は何か尋ねました。","respondent":"金子産業振興課長","answer":"よく言われます保証協会の保証対象外業種において、保証の対象にならない業種というのは幾つかあります。それで簡単に申し上げますと、例えば飲食業のうちでも風俗営業に関するもの、こういったものが主な対象外の業種になってあります。","id":"exchange-021"},{"speaker":"井上委員","kind":"確認","question":"先ほどの山路委員の質問に関連しての確認なんですが、その後変わったのかどうかということなんですが、このあっ旋制度が変更になったのかというところで確認だけお願いしたいと思うんですが。","respondent":"金子産業振興課長","answer":"ただいまの件ですけれども、区民委員会でのお話というのはちょっと承知していませんので、大変申しわけありませんが、もう一度確認してお返事をしたいというふうに考えております。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"補助というのとあっ旋をして融資をするだけなので、返してもらうことだったので、合わせて大丈夫ということだったと思いますので、そこのところだけまた後日ということになるんでしょうか、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"近隣セキュリティシステムのモデル実施","agenda":"近隣セキュリティシステムのモデル実施","exchanges":[{"speaker":"山村委員","kind":"質問","question":"それと、通報内容が発信地点と児童の学年および性別となっていますが、児童の学年および性別だけでほんとうにどの子どもか判別できるんですか。それと最後に、じゃあどこが責任をとるのかというような責任問題はどうするのかなと思っているんですけれども、教えていただけますか。","respondent":"金子産業振興課長","answer":"万が一駆けつけなかった場合には、これ自体が万全の安全を保証するというものではなくて、安全を確保するための１つの私どもの支援する手段ですので。発信につきまして現在考えているところは、学年と性別、これで対応できるんではないかというふうに考えているところです。","id":"exchange-024"},{"speaker":"山村委員","kind":"意見","question":"そこら辺をもうちょっと詰めないとどうにもならない場合があるんじゃないかなと思うんですけれども。例えば顔がわかっていないわけだからどうにもならないし、児童が例えば誤報でやった場合に、本人に気付いてもらってどうするのかとの意見を述べました。","respondent":"金子産業振興課長、田村地域活動課長","answer":"顔がわからなくても学年と性別等々あるいは事件が起きている周辺の状況等々で判断できるんではないかというふうに考えております。先ほども申し上げました子機なんですけれども、１度発報しますと… 実際にＰＴＡの説明会の中でももう既に連絡先等を総会のときにお聞きして、それぞれお子さんの親御さんですから、まず協力者に当然なっていただく。今のところ５月ごろ、さらに協力者を集めていきたい、そのように考えております。","id":"exchange-025"},{"speaker":"山村委員","kind":"意見","question":"先ほど名前等は言わないのは一方の要請があってということなんですが、その要請というのは保護者からなのか、じゃあ。","respondent":"金子産業振興課長","answer":"先ほど申し上げたのは、一般的なプライバシーというものの概念から、プライバシーを保護しなければならないという考え方から私どもが導き出している結論だという意味ですので、個々の保護者に確認をとったわけではございません。","id":"exchange-026"},{"speaker":"山村委員","kind":"意見","question":"そのときに、プライバシーをどうこうを決めるのは保護者なわけですね。保護者に聞いて決められたのかどうなのか知りたいんですけどとの意見を述べました。","respondent":"山田区民生活事業部長","answer":"言ってみれば、今被害者支援ということについて法律上もいろいろな支援のあり方論が言われております。どういう子であるかというのは問題になりますから大体何年生で性別がわかれば特定できるだろうということで、今回こういう形で踏み切ったものです。","id":"exchange-027"},{"speaker":"山村委員","kind":"質問","question":"最後に、協力者、ボランティア。当然品川区の職員で品川区に住んでいる方は１００％これに入られるだろうなと私は思っているんですが、そこら辺はどうお考えか尋ねました。","respondent":"田村地域活動課長","answer":"ただ本来業務がありますので、その辺は柔軟に対応せざるを得ないですけれども、やはり職務の中でその発報に対応する。そのように考えております。","id":"exchange-028"},{"speaker":"山村委員","kind":"質問","question":"どうでしょうか。そんなことを言っていると私もならなきゃいけないんじゃないかと思っているのですが、家族等がなることを考えられているのか。","respondent":"田村地域活動課長","answer":"やはり地域で地域が地域の安全をともに支えながら助け合おうというような、本来警察が来るまでの間、地域が支えようという仕組みなんですね。本人が協力者になりたいというようなことであれば、それは区の職員であろうと一向に差し支えない、そのように考えております。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"山村委員と部長のご質問と答えで、子どもが持つわけですから、子どものプライバシーはありますよね。ぜひ守っていただきたいという観点からちょっと質問するんですけれども、何か一定のルールというんですか、広まっちゃうと。","respondent":"金子産業振興課長","answer":"これはモデル実施までに協力者の方にどういったことをお願いするのか、役割、そういった守るべきこと等々のマニュアルをきちっと整備した上でお願いしていきたいというふうに考えてあります。","id":"exchange-030"},{"speaker":"原委員","kind":"質問","question":"現実にどういう基準で選ばれているのか。それを今の状況で結構ですから、あるいは民生委員を頼むとか、その辺のお考えというのはあるんか尋ねました。","respondent":"田村地域活動課長","answer":"今考えているのは、性別等は問わないで、できるだけ先ほども言ったように地域の中でメッシュを細かくするような形で考えていきたい。それは随時まだこれから開始ということなので、それは一気にという形ではなく、そのように考えてあります。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"子どものやることですから、そういったところのそうなったときにはこうなるんだよということのちゃんとした教育というか指導をしてほしいので、あと。これは何もなければ何もない状態なので、訓練として何らかのことをするのかどうかというところを説明を求めました。","respondent":"金子産業振興課長","answer":"一定程度、今のところ業者のほうの考えもありますが、あまり高くない額で実費弁償をしていくように検討しています。それから、訓練につきましては実際にモデル校のところでも実施していきまして、具体的に子どもたちにもわかってもらうということが必要ですので。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"ほんとうに定期的な確認作業も今後出てくるんじゃないかというところではきちっと対応はしていっていただきたいんです。１人に何カ所かの保険がかかっているというケースが今でもあるわけですが、その辺はどのように考えて対応されていくんか尋ねました。","respondent":"金子産業振興課長、田村地域活動課長","answer":"実費弁償の件ですけれども、私どもとしましては、大体消費税がついて３,１５０円というものを中心に検討しています。２番目の協力者の番号等々が変更した場合… ただ、やはりそれの対象なり事業内容に応じて選択しているので、一括同じ保険というのはなかなか難しいものかなと。ですから、区が今回みたいに保険で入る内容を一定整理して、一定の形が出るのかなというふうに思っております。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問","question":"は公立の小学校の１万１,０００人ぐらいに配付ということだったんですけれども、そういった子どもたちに対してはどのようにされていくのか。どうなんか尋ねました。","respondent":"田村地域活動課長、金子産業振興課長","answer":"実はセンターシステム、地域活動課におくので私のほうからご説明しますけれども、一番心配なのは誤報です。今の段階では研究はしていますけれども、そういう形でやっていくのがいいのかなと、そのように考えているところです。先ほど委員との答弁でも申し上げたとおり、このシステムそのものが学校でのやはり指導、協力というものも非常に大きな要素になってまいります。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"ほんとうにここまで研究をされて導入をされるということですから、お子さんたちのほんとうの声というか、地域の声もきちんと聞いた上でいいシステムにしていってほしいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"塚本副委員長","kind":"質問","question":"何点か伺います。この種の犯罪がどういう地域特性のところで起きるかというようなこと、ある種の想定があろうかと思うんですけれども、その２点をまず詳しく。","respondent":"金子産業振興課長、田村地域活動課長","answer":"この学校の選択の理由ですけれども、これにつきましては教育委員会と協議して決定いたしまして、教育委員会の考え方で決めているものです。それからモデル実施に当たっては、それで３校の中ではやはりこの地域バランス… 先ほど部長の答弁の中で、学校の近辺をうろついているので生活安全パトロール隊に見ていてほしい、警備してほしいというような問い合わせがあります。","id":"exchange-036"},{"speaker":"塚本副委員長","kind":"質問","question":"かなりの能力を持っているはずですから、いずれ二、三年たつと競合関係になってくると思うんです。ある程度運用される点、民間型のそういう能力をどういうふうに横にらみしていくかということを、考えがあればお聞きをしたいと思います。","respondent":"山田区民生活事業部長","answer":"地域の住民の方々によって安全の意識を高め、お互いに支援をし、２層の安全をつくれるというのがこの特色だというふうに思っております。","id":"exchange-037"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"民間も確かな仕事をするわけですから、その辺の協働といいますか、それを考えながら進んでいってほしいというふうに思っております。ここへ来て何かするといいことがないよということが１つと、優先順位をつけて、こういう順番ですよということがあれば教えていただきたい。","respondent":"山田区民生活事業部長","answer":"今、３点ご指摘をいただいているんですが、全くこれが私どものねらいということになろうかと考えています。副次的には出てくるだろうというふうに考えてあります。","id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問","question":"それぞれの効果をねらうには、やはりそれぞれ違った表現の仕方というのはあろう。働きかけの仕方も違ってくるでしょうから、それぞれの効果を見据えて、最大の結果が出るようにご努力願いたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"山村委員","kind":"質問","question":"ちょっと質問をするんですけれども、お話を聞いていて思ったんですが、例えば児童虐待、家庭内でこういうのが鳴った場合はどうなんでしょうか。要するに児童相談所等にも連携していくんじゃないんか尋ねました。","respondent":"金子産業振興課長","answer":"当然児童虐待防止法に規定がありますとおり、それを通報する義務というのがありますので、それは１つのきっかけにはなるかなというふうに考えてあります。","id":"exchange-040"},{"speaker":"山村委員","kind":"質問・要望","question":"少しは何か想定したようなものにつくっていくことがいいのかなと思って要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほどの幹部職員の異動のところで少しお伺いしたいことがあったんですが、それをもう少しきちんと説明をいただきたいということと、その辺はどういう経過でこのような組織改正になったのかということを２点ほどお伺いしたいと思います。","respondent":"原国保年金課長、岩崎環境清掃事業部長","answer":"私のほうから従来の保険年金課で扱っておりました事務の一部が高齢福祉課のほうに移管したことについてご説明させていただきたいと思います。例えば介護保険料の収納等についても一体的に高齢福祉課のほうで徴収率… その中で継続的に通常の業務の中でさらにＣＯ2を減らすなどの成果を目指していきたいという、その平常業務化を方針として持っております。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"国保年金課のほうでは職員の異動が具体的にどうなったのかということと、もう少しきちっとした形での取り組みが必要ではないかというふうに思っていたんですけれども、そこの辺はどのような体制をとられているんか尋ねました。","respondent":"原国保年金課長、岩崎環境清掃事業部長、川西委員長","answer":"職員の関係ですけれども、職員につきましては７名の職員を保険年金課、国保年金課からこの４月１日で異動させてあります。それから… それから学校の子どもをそもそもどういうふうに主体として位置づけるのかというような難しい問題がありまして、まだできていないということです。… ほかになければ、本日の予定はすべて終了いたしました。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/678828?Template=document&Id=2420#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":32796,"voices":123}},{"id":"h17-20050412-8","meetingId":"h17-cm04","date":"2005年4月12日","dateIso":"2005-04-12","committee":"建設委員会","time":"午後１時０３分～午後４時２３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"もちろんできて初めてなんですが、行く上において留意するような場所といいますか、特筆すべきようなことはありますか。ただ漠然と見てもしようがないと思いますので、どうなんか尋ねました。","respondent":"藤田道路公園課長","answer":"イルカのプールにつきましては、３６０度から見えるような形になっている施設です。そのほかは、ペンギンが泳ぐ姿が見えるとか、そういったような施設もありますので、ぐるっと回っていただくと大変よろしいかと思います。","id":"exchange-001"},{"speaker":"高星委員","kind":"質問","question":"ずっと見ていると、先ほど委員長がちょっと触れましたように、全部冠がついているんですね。そこだけやっぱり教えておいてもらわないと、向こうに行ってつまらないことを言ってもしようがないので、わかればちょっと説明を求めました。","respondent":"藤田道路公園課長","answer":"最近非常に多いパターンですけども、ちょっと例に出しますと、味の素スタジアムですとか、ああいった形のネーミングライツと同じ考えで、エプソンから維持管理費の一部を負担してもらっていると、そういうような形になっているものというふうに聞いてあります。","id":"exchange-002"}]},{"id":"topic-02","title":"平成１６年請願第２１号、（仮称）「グローリオ戸越銀座II」新築工事に関する請願","agenda":"平成１６年請願第２１号、（仮称）「グローリオ戸越銀座II」新築工事に関する請願","exchanges":[{"speaker":"高星委員","kind":"質問・要望","question":"その上に立ちまして、請願代表者のほうから取り下げをしたいんだと、こういうような意向がございましたので、今日のことです。このことを確認させていただきましたので、どうでしょうね、委員長。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"高星委員","kind":"意見","question":"それだったら、円満解決の方向であるならば取り下げられるのが一番ベターであろうという話をさせていただきましたら、「わかりました」と。できるだけ早い時間帯でというような話になったんですけどとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"高星委員","kind":"質問","question":"話をしたところが、そういうことで取り下げたいというような意向だったものですから、こんなときはどうしたらいいのかな。例えば５分でも休憩してもらって、書記か委員長か電話をしていただくというのは、そういう手はずはとれないんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"ほんとうに何か今高星委員からいい話を、業者と住民の方が円満に粛々と解決されるということは、ほんとうに今いい吉報を聞いたのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"高星委員","kind":"質問","question":"つい先ほどのあれだけれども、奥様に最終的に請願代表者の携帯電話を教えていただいて、そこに追っかけの電話をさせていただいた。したがって、そういうふうに取り下げる旨のお話をいただいたものですから、こういうふうに言わさせてもらっている次第なんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"実は、私も代表者の方に昨日電話でお話をお伺いしたところなんですけれども、それで今朝もちょっとお話をお伺いしたところだったんですけど。今の高星委員のお話をお伺いしますと、ぜひ区のほうでは住民の皆さんからの要望を受けながら、業者のほうに対してもご指導をお願いして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"林（和）委員","kind":"質問","question":"この緑被率なんですけれども、昔私なんかが区議会に出たころは、２３区中、品川区は後ろから二、三番目であったんですけれども、その後において努力をしていただいて、真ん中辺まで来たということで、今回の緑被率は２３区中どの程度まで上がったのかということを説明を求めました。","respondent":"藤田道路公園課長","answer":"それぞれの各区の最新の情報で合わせた形ですと、品川区の今１２.７％、こちらは２３区中の１７番目になってあります。全部で８区、品川区もまじえて８区ありますが、今後も引き続き施策を展開することでよりよい結果が生まれてくるかなというふうに考えてあります。","id":"exchange-009"},{"speaker":"三村委員","kind":"質問・要望","question":"今日の新聞で、都がヒートアイランド対策ということで熱環境マップというんですか、そちらのほうを策定したということで。この辺、どういったことか、詳しい情報がわかれば教えていただきたい。","respondent":"藤田道路公園課長、上野都市開発課長","answer":"私どもみどりの条例の中でも１,０００平米以上の建物については、屋上緑化をどんどん推進してほしいという思いで施策を展開しています。これを今後も推進してまいりたいというふうに考えてあります。緑化というよりも、反射塗装を広く普及するようなことを考えてございまして、直接の緑化とは必ずしもリンクしないところがあるようです。","id":"exchange-010"},{"speaker":"大沢委員","kind":"意見","question":"ちょっと後ろに話を戻しちゃって申しわけないんですけれども、屋上緑化の義務がほとんど反映されていなかったということですけれども、反映されていなかった原因というのがわからないんですけどとの意見を述べました。","respondent":"藤田道路公園課長","answer":"今回の調査が２番目の調査内容(1)緑被地調査ということで、平成１６年６月の航空写真を撮影して行ってあります。２年足らずということで、今後事業が進んでいく中では、屋上緑化がどんどん進んでいけば計測する数値上明確にあらわれてくるといったようなことです。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"草地ですか、どういう形で減ったり増えたりしているのかという、具体的なところをちょっと教えていただけないか尋ねました。","respondent":"藤田道路公園課長","answer":"草のままではなくて、維持管理がしやすい舗装等を施したりしているのかなと、そういった関係で草地の量が相当量減ってしまったというのが現状です。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この増えた部分はしながわ中央公園の６個分というふうなことですけれども、公園がこの間に新たにどれくらい増えたというのがあるんか尋ねました。","respondent":"藤田道路公園課長","answer":"私どものほうの分類の中の公園の数としては、平成１１年から６個の公園が公園として新たにオープンしています。みどりの今回の緑被率という考え方は、舗装になっているところ、その辺とは直接リンクはしていない形になっております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは今からすると１.３％増やしていくということになりますけど、これは具体的にどういうところで増やしていくということで考えているのか、そこのところをちょっと説明を求めました。","respondent":"藤田道路公園課長","answer":"緑化指導を進めること、そういった中でこういった数値まで何とか持っていけるのではないかといったような考え方です。そういった計画もあわせる中で最終的な目標を立てるべきというふうに考えてありますけれども、こんな形になるというふうに考えているものです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところも含めて、こういうふうに具体的に目標にしているわけですから、この目標を実現しようというのはあるわけですよね。それが１４％になるだろうということではなくて、やっぱり１４％にするために具体的にどうするという、そこら辺のところというのはどうなんでしょう。","respondent":"藤田道路公園課長","answer":"今回の実態調査を踏まえた考え方の中では、そのほかに長期計画あるいは実施計画の中で新たな公園をつくろうというような形での施策を打ち出していますので、そうした施策とあわせた中で緑化のほうの推進は今後も進めていくべきというふうに考えてあります。","id":"exchange-015"},{"speaker":"三上委員","kind":"提案","question":"過去、品川区の中で緑被率を求めていくというのは、将来的には４分の１緑化構想というのがありますよね、品川区はね。どうか尋ねました。","respondent":"藤田道路公園課長","answer":"公共施設の壁面の緑化等についても今後有効な手だてがないのかといったような検討を今後進めていかなければいけないというふうに考えてあります。","id":"exchange-016"},{"speaker":"大沢委員","kind":"意見","question":"みどりを多くするということの考え方なんですけれども、さっきから言っている温暖化現象でヒートアイランドに対する対策がこれから重んじられるか、それとも景観という観点からみどりの多さが重んじられるのか、どちらがこれから先、重きをなしてくるのかとの意見を述べました。","respondent":"藤田道路公園課長","answer":"委員ご指摘の両方とも非常に重要なところだというふうに考えてあります。当然今大きな話題となっているヒートアイランド現象、多岐にわたる面でみどりの重要性がここに来て問われているというふうに考えているところです。","id":"exchange-017"},{"speaker":"高星委員","kind":"意見","question":"それは包括的にやっぱり、みどりをどう担保していくというか、やっぱり場当たり的になってしまうんじゃないかな。だから、包括的にどうやって区民と一緒に行政が担保していくのか、その辺の考え方はどうなのとの意見を述べました。","respondent":"藤田道路公園課長","answer":"税の優遇措置みたいなものを受けられるようにしていきたいということで、国土交通省のほうで検討しています。そういったさまざまな施策を通しまして、みどりの担保を継続して図っていければというふうに考えてあります。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"どのくらい。民有地でも木を植えて、こういう考え方の基本をちょっと知りたいので、どのくらい品川区でボリュームあるんか尋ねました。","respondent":"藤田道路公園課長","answer":"民有地の緑地の保全ということで、以前みどりのある遊び場の助成事業というのをやってございました。平成１４年度でこの事業については一定の効果が図れたということで、助成制度そのものを見直しまして、今現在はその制度そのものは廃止したものです。","id":"exchange-019"},{"speaker":"高星委員","kind":"質問・要望","question":"細かくは求めませんけど、目標を達成したということなのか、所定の目標を達成したのかどうなのか、ちょっとそこの基準がわからない。何で必要と思って補助金まで出したけれども、事業をやめましたと、そこはどこまで達したのでやめたんか尋ねました。","respondent":"松代管理工事課長","answer":"そういった中で進めてきておったんですが、今現在は目的とはそのままの形で自主的な管理をしていただいていると、そういった現状にあります。そういった形で増やすというようなことも一つの施策とは当時考えておったんですけども、その後、こういう状況にあります。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"基本的なことでお聞きしたいんですけど、デジタル航空写真を写して、そのときに６月ですから、葉っぱが勢いよくついていると。そして、それは高木、中木、低木とあるんですけど、それは全部一括して面積をとっているという解釈でよろいか尋ねました。","respondent":"藤田道路公園課長","answer":"それをもとに樹木と草地、そういった分けで数値を把握しています。例えば緑色の屋根、その辺はすべて目視によって除去をして、コンピュータの処理の中で面積を算出するといった形で測定しているものです。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"そういう区分のほうが逆にわかりやすいと思うんですけど、うっかりすると、緑化面積は確かに１４％ですか。その辺、これは全国的にこういうみどりの実態調査というのは、こういうふうな算出方法になっちゃうんか尋ねました。","respondent":"松代管理工事課長、岩田まちづくり事業部次長","answer":"やはり５年前と現在はどうかということで、ここにもありますように、若干まだまだみどりの少ないところがある。そういったものにまず使うような形、そういったものが重要だろうと、このように考えているところです。緑色の植物はすべて炭酸同化作用を行いますので、高木であろうが、葉っぱがあればすべて昼間は二酸化炭素を吸収して酸素を放出します。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"ちょっと区民とすれば、イコール温暖化とか、そういうふうにどうしても緑化率とか何かになると思うんですよね。そういうことも、これだけ品川区で樹木を植えて維持管理しているわけですから、それは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"三村委員","kind":"質問・要望","question":"もし２０倍としたら、その２０倍の面積に換算できるような、やっぱり意識的にきちんと増やしていくという視点は絶対必要だと思うんですね。ぜひ再開発や何かの際に、みどりのボリュームをきちんと生み出すような視点での取り組みをずっとしていっていただきたいと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"関連だけで。桜の木、全部植えかえなきゃいけないというのをこの間ちょっとテレビで放映されていたんですが、それは事実なんか尋ねました。","respondent":"岩田まちづくり事業部次長","answer":"ソメイヨシノは比較的寿命が短くて、大体人間の寿命と同じぐらいだと言われていますので、６０年から８０年ぐらい。もうちょっと様子を見ないとわかりませんけど、一般的には人間と同じぐらいということで、全体で寿命で死んじゃうということは特に聞いておりません。","id":"exchange-025"}]},{"id":"topic-03","title":"中延５、６丁目および２丁目の浸水対策","agenda":"中延５、６丁目および２丁目の浸水対策","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どうしてもだめであれば検討すると、こういう形で抜本対策がとられるというところでは、ほんとうに感謝しています。品川区は２３区の課長に働きかけて、そういう下水道整備を進めてほしいという要望を繰り返しこの間出していただいたと思うんですけど、そういう中で。","respondent":"矢部下水道河川課長","answer":"そういう意味でいきますと、最盛期が約２,７００億円ございましたので、半分以下というところで厳しい状況にあります。品川区は非常に２３区、他区に比べて突出してやっぱり多くなっているから、その辺を了解してくださいというような話もございました。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと具体的なところで聞かせていただきたいんですが、具体的には今の立会川幹線の下を通るという工事になるんでしょうか。それからあと、そこら辺のところはどういうふうにクリアされるのかというふうなところもお聞かせほしいと求めました。","respondent":"矢部下水道河川課長","answer":"できるかというところを、なるべく平成１９年度中に荏原町公園まで押したいと、そのまま押したいというような話を聞いてあります。第二立会川幹線自体が道路から２０ｍぐらい深いところをずっと押してきますので、それを避けながら横断できるものというふうに考えてあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"原っぱ公園から荏原町公園までは何ｍぐらいあるんでしょうか。それともう一つ、これはどこからどこまで具体的にどういう道順を通ってバイパス管が、ちょっと具体的なところを教えてほしいと求めました。","respondent":"矢部下水道河川課長","answer":"先ほど申し上げましたとおり、そのままずっと池上線のところを横断しまして、その間の道路あたりにずっと北上していくのかなと考えております。延長その他につきましては、まだ詳細な情報は得ておりません。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"バイパスというのは、中延幹線のところから若干外れると思うんですけど、それ以外の部分は中延幹線の下を通るということで考えていいんでしょうか。それが１点と、例えば今まで平成１１年と１４年のこういう被害が起こってきましたけれども、それがわかったら教えていただけないか尋ねました。","respondent":"矢部下水道河川課長","answer":"先ほど来申し上げていますが、基本的に言えば中延幹線の下をバイパスが抜いていくんだろうというふうに考えてあります。東京都が現在進めております溝渠の５０mmに対して、流出係数８０％、それに見合うものになるというふうに考えております。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、このことに対して、地域の方に対しての説明会というのはどういうふうに考えられているのかをちょっとお聞かせほしいと求めました。","respondent":"矢部下水道河川課長","answer":"品川区で実際に工事を受託してやるという今予定になってございませんので、住民説明会等については今回は要するに東京都下水道局のほうで行うことになるかと思いますので、その辺はできましたら品川区のほうも一緒になってその辺を開いていけたらというふうに考えております。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この事業期間については、バイパス管の整備のことで平成１７年度から２０年度までかかるということなんでしょうか。そこのところをちょっと説明を求めました。","respondent":"矢部下水道河川課長","answer":"そこの辺もどういう順番でどこに立坑を設けて、どういう形で施工していくかというのは、ちょっともう少し時間をいただきたい。現在のところ、平成１７年度から予算で着手するというところまでは聞いておりますけれども、ちょっとまだ詰めの段階ですので申しわけございません。","id":"exchange-031"}]},{"id":"topic-04","title":"平成１７年５月都営住宅（世帯向、定期使用住宅等）募集","agenda":"平成１７年５月都営住宅（世帯向、定期使用住宅等）募集","exchanges":[{"speaker":"木下副委員長","kind":"質問・要望","question":"わからないので教えていただきたいんですが、まだきていないということで。ただ、品川区内では大体どのくらいの募集があるのか、あるのかないのかも含めて教えていただきたい。","respondent":"浜脇住宅課長","answer":"あるとは聞いているんですけども、幾つというまで情報が全部来ておりませんので。資料が来てござませんので、すみません。","id":"exchange-032"},{"speaker":"三上委員","kind":"質問・要望","question":"私はあえてきちっとした単位というのを「m2」という単位が使われているのに、なぜそういう単位があるのに、そこがわからないんだけど。すべてそういう考え方でやりましょうと、そういうふうな考え方で出てきている話なのかどうか、ちょっと聞かせていただきたい。","respondent":"福田まちづくり事業部長、浜脇住宅課長","answer":"もどうなんだろうというような場合も想定せざるを得ないような環境も見られるのかなというような認識がございまして。したがいまして、住宅政策の転換というふうな認識は事業部としては持っておりません。 先ほどの２点目の単位の問題ですけれども、m2なんかが入ってくると古いような感じで、このほうが見やすいというふうに思われてやってあります。","id":"exchange-033"},{"speaker":"三上委員","kind":"質問・要望","question":"品川区としてどうするのかということで、事業部だけの問題じゃないですよ。どういうふうにしていくかということについての、宿題として何とか考えたものを、統一したものを返事していただきたいなと思います。","respondent":"浜脇住宅課長","answer":"住宅施策そのものが変わっていないかということで、私どもとして、実は検討の中で新幹線のほうに流通倉庫のところがありますね。そういった方々がそろそろそういった時代の流れで、果たしてそれが住宅を付置することがどうだろうということは、前から実は検討してございました。","id":"exchange-034"},{"speaker":"三上委員","kind":"意見","question":"どうなんだろう、その辺。今日の話題としては、ちょっと私としては納得できない報告事項だと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"高星委員","kind":"質問・要望","question":"例えば、５００坪ぐらいに似合うような寄付というふうになるのか、その辺の整合性というのはどういうふうになっているのか。規定みたいなものができているのかどうかちょっとわからないんだけど、その辺の、その辺のところをわかりやすくちょっと説明していただきたい。","respondent":"浜脇住宅課長","answer":"今後の価格の検討になりますが、予定というと変ですけども、そういう算定というのはつくっていきたいなと思ってあります。何戸だと幾ら、そういうふうな感じかなと考えています。","id":"exchange-036"},{"speaker":"高星委員","kind":"意見","question":"だから、その辺のところの、どのくらいを計算されて、どのくらいお支払いいただくというか、寄付をいただくか、寄付をだれがもらうかも含めてですよ。これはまちづくり事業部の総責任者のちょっとその辺の考え方、もう一度きちっと聞いて、私は終わりますとの意見を述べました。","respondent":"福田まちづくり事業部長","answer":"先ほどもご答弁させていただきましたが、例外というふうに位置づけられる選択肢をもう一つ設けた、そういうような状況に対応したというものですので、政策、つまり、施策の基本的な理念ですとか、目的とするところ、そういう部分を変更したものではございません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/825107?Template=document&Id=3812#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":34435,"voices":126}},{"id":"h17-20050412-5","meetingId":"h17-cm04","date":"2005年4月12日","dateIso":"2005-04-12","committee":"総務委員会","time":"午後１時０3分～午後２時２１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件整理しています。","topics":[{"id":"topic-01","title":"の総合実施計画（第４次）策定","agenda":"の総合実施計画（第４次）策定","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"ただいまのご説明はよくわかったんですが、今はいいところのお話、新しくやるところと、充実するところというお話だったんですけれども、いろいろ事業評価をした結果を出すとすれば、縮めたところ、あるいは、消したところがどうなったのかなということを、聞かせていただきたいんですけれども。","respondent":"榎本行財政改革担当課長","answer":"具体的には、総合実施計画事業の評価の中で、Ｄ評価が三つございました。そういうほうへシフトしていくということで、保育園での相談事業の活動自体は縮小していく、そういうものはあります。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"公園の新設整備の中で、国文学研究資料館が、跡地公園ということで突然出てきたんですけれども、平成１９年に用地取得となっていますけれども、これの経緯というんですか、どのような形で進んでいるのか、ちょっとお教え願いますか。","respondent":"榎本行財政改革担当課長","answer":"昭和６１年か６２年だったと思うんですけれども、その跡地を都心のいろいろな有効活動のために使おうという、大きな国の指針が策定されました。正式な回答等はないんですけれども、最終的には、あそこを戸越公園と一体の公園にしていきたいという計画を持ってあります。","id":"exchange-002"},{"speaker":"松澤委員","kind":"意見","question":"既存の建物を何か有効活用できないのかなという思いがあるんですが、公園整備の中で、既存の建物をどのようにするかお考えを持っていますか。それを壊しちゃうのか、あるいは有効活用していくのか、その辺の部分をとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"まだ具体的にはそこまで検討は進んでいないんですけれども、実際上、都市計画公園としたときに、どこまで建物が残せるのか。実際に用地取得をするときに、更地で取得するのか、それとも建物つきで取得するのかということも踏まえて検討を進めていくと考えております。","id":"exchange-003"},{"speaker":"本田委員","kind":"意見","question":"平成１９年度はうんと低くなるわけですけれども、税金を払って多くなっているのに、事業量が減っていいのかなと。以上、２点との意見を述べました。","respondent":"榎本行財政改革担当課長、日下部企画財政課長","answer":"要支援、９０％は元気ということで、従来も打ってきているものです。元気高齢者の部分と介護予防の部分という形で、この計画の具体的な事業としては、そういうものが盛り込まれております。通常の行政運営に要する経常的な経費等が主になってまいりますけれども、平成１７年度から１９年度までは、若干微増の推移ということで見込んです。","id":"exchange-004"},{"speaker":"本田委員","kind":"意見","question":"さっきの見解の特徴の問題なんですけれども、お尋ねしたのは、ご回答いただいた趣旨とちょっとずれているんです。その点だけ、もう１回との意見を述べました。","respondent":"新美企画部長","answer":"先ほども若干ご説明しましたが、できるだけ地域の中で働いていただくための就業支援、力を入れている分野です。当然、今後、検討していかなければいけない領域だと考えているところです。","id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"これはどういう意味かと、こういうものをどこかで１回、そこら辺の考え方を教えていただきたい。教えていただきたいんですけれども、平成１９年に建物の費用とかそういうものが入らないのかなと、二つ教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"ここだけで１３０億円落ちているということにつきましては、何らかの説明を加えられるような形で、ちょっと工夫を図りたいなと思います。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"そこを平年化していくと、３カ年の中で、都南病院を建てる建物も全部入ってくるのかなと思うんですけれども。すみません、全然わからなくて、これを教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"５億６,０００万円、４億３,０００万円という形で、具体的には入っております。１９年度のところが都南病院跡地ということで、およそ９億円近いものが、今言った三つの施設のそれぞれの部分の整備として入っているものです。","id":"exchange-007"},{"speaker":"土井委員","kind":"質問","question":"実施計画ですから、特に学校の改築の関係でいきますと、この後まだたくさん出てくるピークが来るだろうと思いますね。勘定が合わなくなるんじゃないかなという気がするんですが、そこら辺は、どんなふうに考えたらよろしいんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"今現在、耐震診断を全校にかけておりまして、今年度、全部終わる予定です。学校の改築に入っていけばいいのかというものがありますので、その辺を見据えた上で、計画的に進めていきたいという考えです。","id":"exchange-008"},{"speaker":"土井委員","kind":"意見","question":"区が全部持つわけでもないし、今、議論がいろいろされているところだと思うんです。そこら辺のところは、頑張りきるぞという見通しで立てられているのかどうか、ちょっと決意をとの意見を述べました。","respondent":"榎本行財政改革担当課長、濱野助役","answer":"今現在は、わかっている範囲内のものは、ここに組み込まれているという形です。この実施計算のもとになります１０年間の第三次長期基本計画の中でも、平成２２年度まで、計画を組んです。","id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"建物を建てる実施計画ではなくて、金をためる実施計画、金をどこかから取ってくる実施計画は、どうなっているんですかということが聞きたいんです。","respondent":"濱野助役","answer":"いわゆる主要５課題の成果といいますか、十分な裏付けをとらなければいけないと考えておりますし、これについては比較的精緻な数字を持っております。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと今の質問に関連するんですけれども、２校つくっていますけれども、全部小中一貫教育に移行ですよね。あるいは、教育は小中一貫教育にしていくけれども、校舎そのものは動かさないということなのか、そこら辺の考え方はどうなんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"小学校４０校、中学校１８校ありますので、カリキュラム上で連携をしていく。小中連携教育の発展形という形で、小中一貫教育というカリキュラム上の連携を図ったものと併存していくという形で、展開をしていくという流れです。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと私が伺いたかったのは、小中一貫校が、今、２校なんですけれども、それの拡大というのは、今後どういうふうに見ているのかということ。そこら辺は、どういうふうになるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"意見","question":"そうすると、小中一貫校のほうは別途検討ということですね。今回の第４次の実施計画のところは、どれがどういうふうに計画の前倒しで反映したのかということを、具体的なことで説明いただけますかとの意見を述べました。","respondent":"榎本行財政改革担当課長","answer":"先ほどちょっと説明した中では、防災危険度の高い地域がありまして、それは前期のほうに持ってこようということで前倒しをしています。前倒しで、ある程度まとめてできたので、前期で終了するという計画に含まれているものです。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"総合体育館の件なんですけれども、今の総合体育館の跡地の計画というのは、具体的に進んでいるんですか。第４次の実施計画には、どんな感じで入っているんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"現行の総合体育館の跡地ですけれども、それにつきましては、大崎地区周辺のまちづくりということで、具体的には、地域としては北品川五丁目の地区計画の中に入っているものなんですけれども、その中で、今後、どういうふうに進めていくのかは、検討段階に入っているものです。","id":"exchange-014"}]},{"id":"topic-02","title":"続きまして、(2)平成１７年度組織改正","agenda":"続きまして、(2)平成１７年度組織改正","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ教えてください。そう考えると、矢印は担当課長の下に入るんじゃないのかなと思っていたんですけれども、上に入っているから、そこら辺の考え方を教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"ただ、実務的には、住環境整備担当（主査）制が、担当課長のもとについて行っていく形のものです。ただ、規則上、そういうふうな並べ方をしておりますので、ここでは、点線で区切らせていただいて、そのような位置づけをかけているものです。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"時間も、人手もかかる事業かなと思うんですけれども、ちょっとそこら辺のイメージがわかないんです。体制が何かちぐはぐな感じがするんですけれども、こんなことを聞いても、わかるんか尋ねました。","respondent":"榎本行財政改革担当課長","answer":"その部分は、そこのほうで計画的に実施できるという形で、住宅紛争と密集市街地のほうは分けたという組織づくりというものです。密集市街地を進める上でも、一体的に都市開発のほうでしていこうというのが、この考え方です。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594587?Template=document&Id=1680#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":25961,"voices":66}}]);
